window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s7-329","number":329,"surah":7,"verses":[62],"references":[{"surah":7,"verses":[62]}],"verseLabel":"الأعراف: 62","question":"لماذا اختير المضارع ﴿أبلغكم وأنصح لكم﴾؟","answer":"المضارع يدل على تجدد التبليغ والنصح واستمرارهما، لا على فعل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص556، تحت «دلالة التعبير بالمضارع في قوله: ﴿أبلغكم﴾»","url":""}]},{"id":"s7-330","number":330,"surah":7,"verses":[62],"references":[{"surah":7,"verses":[62]}],"verseLabel":"الأعراف: 62","question":"لماذا عُدي النصح باللام: ﴿أنصح لكم﴾؟","answer":"عُدّي النصح باللام لأنه إرادة الخير للمنصوح وتوجيهه إلى ما ينفعه؛ فاللام تبرز منفعة نصحه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص559، تحت «سر التعبير بقوله: ﴿وأنصح لكم﴾ دون وأنصحكم»","url":""}]},{"id":"s7-331","number":331,"surah":7,"verses":[62],"references":[{"surah":7,"verses":[62]}],"verseLabel":"الأعراف: 62","question":"ما سرّ قول نوح لقومه في الأعراف: ﴿وأعلم من الله ما لا تعلمون﴾؟","answer":"أُسند العلم إلى نوح للدلالة على تمكنه منه، ثم قُيد بأنه من الله ليبيّن أن إنذاره قائم على الوحي وأحكام الله وعلمه بعاقبة التكذيب، لا على دعوى بشرية مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص560، تحت «نكتة إسناد العلم إلى نوح، ثم بيان أنه ﴿من الله﴾»","url":""}]},{"id":"s7-332","number":332,"surah":7,"verses":[63],"references":[{"surah":7,"verses":[63]}],"verseLabel":"الأعراف: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿أوعجبتم أن جاءكم ذكر من ربكم﴾ في صورة إنكار؟","answer":"الاستفهام إنكاري: لا موجب لتعجبهم من الوحي، فإرسال بشر منهم تقتضيه الحكمة ولا يصح ذريعة للتكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص567–568، تحت «غرض الاستفهام في قوله: ﴿أوعجبتم﴾»","url":""}]},{"id":"s7-333","number":333,"surah":7,"verses":[63],"references":[{"surah":7,"verses":[63]}],"verseLabel":"الأعراف: 63","question":"لماذا سُمي الوحي ﴿ذكرًا﴾؟","answer":"سمي الوحي ذكرًا لأنه موعظة تذكرهم بربهم وخالقهم وبما غفلوا عنه من أمره، فتوقظهم من الغفلة وتدعوهم إلى طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص565–566، تحت «شرح المفردات: ﴿ذكر﴾»","url":""}]},{"id":"s7-334","number":334,"surah":7,"verses":[63],"references":[{"surah":7,"verses":[63]}],"verseLabel":"الأعراف: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿على رجل منكم﴾، لا: إلى رجل؟","answer":"من توجيهاته أن ﴿جاءكم﴾ ضمن معنى نزل، فناسبه حرف الاستعلاء: جاءكم ذكر نازل على رجل منكم. وفي التعبير تصوير لمجيء الوحي من عند الله إلى الرسول ليبلغه قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص570–571، تحت «غرض استعمال حرف الاستعلاء ﴿على﴾»","url":""}]},{"id":"s7-335","number":335,"surah":7,"verses":[63],"references":[{"surah":7,"verses":[63]}],"verseLabel":"الأعراف: 63","question":"لماذا ذكر بشريته وقربه: ﴿رجل منكم﴾؟","answer":"﴿رجل منكم﴾ يرفع الاستغراب؛ فهو بشر يعرفون نسبه ولسانه وصدقه، فيسهل تلقي البيان عنه وتقوم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص571، تحت «غرض التعبير بالرجولة في قوله: ﴿على رجل منكم﴾»","url":""}]},{"id":"s7-336","number":336,"surah":7,"verses":[63],"references":[{"surah":7,"verses":[63]}],"verseLabel":"الأعراف: 63","question":"لماذا ترتبت الغايات: ﴿لينذركم ولتتقوا ولعلكم ترحمون﴾؟","answer":"الترتيب سببي: جاء الذكر للإنذار، والإنذار يحمل على التقوى، والتقوى سبب يرجى به نيل الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص572–573، تحت «بلاغة ذكر التقوى إثر الإنذار في قوله: ﴿لينذركم ولتتقوا﴾»","url":""}]},{"id":"s7-337","number":337,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿فكذبوه فأنجيناه﴾ بفاءين متتابعتين؟","answer":"الأولى تصل تكذيبهم بدعوته وتصور مبادرتهم إلى الرد. والثانية ترتب النجاة على ما انتهى إليه التكذيب، مع إيجاز أحداث طويلة بينهما؛ فالتعقيب فيها بحسب سياق القصة، ولا يعني أن الطوفان والنجاة وقعا فور أول دعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص579–580، تحت «بلاغة الإيجاز في قوله: ﴿فكذبوه فأنجيناه﴾»","url":""}]},{"id":"s7-338","number":338,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين معه في الفلك﴾، دون أن يقال: ومن آمن معه؟","answer":"جمعت العبارة صحبتهم لنوح ووجودهم في وسيلة النجاة؛ فالعبرة بمن صدق واتبع وركب الفلك معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص581–582، تحت «بلاغة الإيجاز في قوله: ﴿والذين معه﴾»","url":""}]},{"id":"s7-339","number":339,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿وأغرقنا الذين كذبوا بآياتنا﴾، فأظهر الصلة بدل الضمير؟","answer":"أظهر ﴿الذين كذبوا بآياتنا﴾ بدل الضمير لتسجيل سبب الإغراق عليهم: تكذيبهم بآيات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص584–585، تحت «نكتة التعبير بالاسم الموصول ﴿الذين﴾ دون الصريح المكذبين»","url":""}]},{"id":"s7-340","number":340,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"لماذا خُتمت بـ﴿إنهم كانوا قومًا عمين﴾؟","answer":"الخاتمة تعلل التكذيب والإغراق بعمى البصيرة المتأصل؛ و﴿كانوا﴾ تدل على رسوخ الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص586–587، تحت «موجب فصل جملة: ﴿إنهم كانوا قومًا عمين﴾ عما قبلها»","url":""}]},{"id":"s7-341","number":341,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"ما دلالة وصف قوم نوح بـ﴿عمين﴾؟","answer":"﴿عمين﴾ جمع عَمٍ، وهي صفة مشبهة تصف عمى القلب والبصيرة. فالمراد رسوخ الضلالة فيهم وعدم اهتدائهم إلى الحق، رغم طول دعوة نوح لهم، لا فقد حاسة البصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص587، تحت «سر تفرد هذه الآية بوصف قوم نوح بقوله: ﴿عمين﴾»","url":""}]},{"id":"s7-342","number":342,"surah":7,"verses":[64],"references":[{"surah":7,"verses":[64]}],"verseLabel":"الأعراف: 64","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿فأنجيناه والذين معه﴾، وفي يونس: ﴿فنجيناه ومن معه﴾؛ فاختار «أنجينا/الذين» هنا و«نجّينا/من» هناك؟","answer":"في يونس جاءت ﴿فنجيناه﴾ بالتضعيف لتلائم مقام إظهار تمام النجاة بعد تحدي نوح قومه وإعلامهم بعجزهم عن الإضرار به، ثم ذكر جعله ومن معه خلائف. وفي الأعراف جاء الإنباء بالنجاة بـ﴿فأنجيناه﴾. وأما الموصول، فـ﴿الذين معه﴾ ينوه بجماعة المؤمنين المعروفين بصحبته، و﴿من معه﴾ في يونس يشمل من أنجاهم الله معه من العقلاء وغيرهم. ولا يلزم من ذلك أن يكون اختيار الموصول ناشئًا عن تخفيف فعل النجاة أو تشديده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص581–582، تحت «توجيه المتشابه اللفظي بين ﴿فأنجيناه﴾ و﴿فنجيناه﴾»","url":""}]},{"id":"s7-343","number":343,"surah":7,"verses":[65],"references":[{"surah":7,"verses":[65]}],"verseLabel":"الأعراف: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿وإلى عاد أخاهم هودًا﴾، فجعل هودًا أخًا لهم؟","answer":"الأخوة أخوة نسب وقوم، وفيها استمالة وإظهار للنصح والمودة؛ وليست أخوة دين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص590–591، تحت «شرح المفردات: ﴿أخاهم﴾»","url":""}]},{"id":"s7-344","number":344,"surah":7,"verses":[65],"references":[{"surah":7,"verses":[65]}],"verseLabel":"الأعراف: 65","question":"لماذا حُذف فعل الإرسال قبل ﴿إلى عاد﴾؟","answer":"حُذف ﴿أرسلنا﴾ اعتمادًا على قصة نوح، والتقدير: وأرسلنا إلى عاد أخاهم هودًا؛ فالإيجاز يربط القصص.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص591–592، تحت «دلالة العطف على الحذف»","url":""}]},{"id":"s7-345","number":345,"surah":7,"verses":[65],"references":[{"surah":7,"verses":[65]}],"verseLabel":"الأعراف: 65","question":"لماذا خُتمت دعوته بـ﴿أفلا تتقون﴾، بينما قال نوح: ﴿إني أخاف عليكم﴾؟","answer":"انتقل خطاب هود إلى التحضيض على التقوى بعد بيان عاقبة قوم نوح، فصار في مصيرهم زاجر يغني عن بسط الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص593–594، تحت «غرض الاستفهام في قوله: ﴿أفلا تتقون﴾»","url":""}]},{"id":"s7-346","number":346,"surah":7,"verses":[66],"references":[{"surah":7,"verses":[66]}],"verseLabel":"الأعراف: 66","question":"لماذا وصف المتكلمون بأنهم ﴿الملأ الذين كفروا من قومه﴾؟","answer":"من توجيهاته تمييز الملأ الكافرين من غيرهم ممن آمن وكتم إيمانه، ويذكر المصدر أيضًا حمل الوصف على الذم. وفي إبراز الكفر تسجيل لمنطلق موقفهم من الرسول، فلا يكون القيد لمجرد وجود غيرهم في مجموع القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص596–597، تحت «فائدة ذكر قوله: ﴿الذين كفروا﴾»","url":""}]},{"id":"s7-347","number":347,"surah":7,"verses":[66],"references":[{"surah":7,"verses":[66]}],"verseLabel":"الأعراف: 66","question":"ما سرّ تعبير قوم هود عنه بأنه ﴿في سفاهة﴾، وتعبير قوم نوح عنه بأنه ﴿في ضلال﴾؟","answer":"يربط المصدر كل اتهام بسياقه: لما خوف نوح قومه بالطوفان وشرع في السفينة عدوا عمله في أرض لا ماء فيها ضلالًا عن الصواب. وأما هود فدعاهم إلى ترك آلهتهم، فعدوا العدول عن عبادة الآباء سفاهة وخفة عقل. وكلا الاتهامين باطل صادر عن فساد تصورهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص598–599، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-348","number":348,"surah":7,"verses":[66],"references":[{"surah":7,"verses":[66]}],"verseLabel":"الأعراف: 66","question":"لماذا أكدوا مرتين: ﴿إنا لنراك... وإنا لنظنك﴾؟","answer":"كرروا ﴿إنا﴾ واللام لتوكيد كل تهمة على حدة: السفاهة والكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص597، تحت «فائدة المؤكدات في الآية الكريمة»","url":""}]},{"id":"s7-349","number":349,"surah":7,"verses":[66],"references":[{"surah":7,"verses":[66]}],"verseLabel":"الأعراف: 66","question":"ما سرّ تعبيرهم في الكذب بـ﴿لنظنك من الكاذبين﴾، مع جزمهم بالسفاهة؟","answer":"على التوجيه الذي يذكره المصدر، ادعوا اليقين بسفاهته بسبب ما رأوه من مخالفته عبادتهم، فعبروا بالرؤية القلبية بمعنى العلم. أما اتهامه بالكذب فتوقفوا عن الجزم به وعبروا بالظن؛ إذ كان عندهم علم بالرسل وعاقبة مخالفتهم، ولم يبعد عهدهم بقصة نوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص597–598، تحت «سر إيثار التعبير بالرؤية في السفاهة والظن في الكذب»","url":""}]},{"id":"s7-350","number":350,"surah":7,"verses":[66],"references":[{"surah":7,"verses":[66]}],"verseLabel":"الأعراف: 66","question":"لماذا جاء جواب الملأ في الأعراف: ﴿قال الملأ﴾ بلا فاء، وفي هود والمؤمنون: ﴿فقال الملأ﴾؟","answer":"في الأعراف جاء قول الملأ مفصولًا على طريقة حكاية الحوار، كأنه جواب سؤال: ماذا قالوا حين دعاهم؟ وفي هود والمؤمنون جاءت الفاء لربط اعتراضهم بالدعوة السابقة وتصوير مبادرتهم إلى التكذيب. ومن خصوص سياق المؤمنون أنهم وجهوا الكلام إلى قومهم لتحريضهم، لا إلى نوح مباشرة. فترك الفاء في الأعراف لا يعني أن قولهم لا يصلح لغويًا جوابًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص596، تحت «سر مجيء ﴿قال الملأ﴾ بلا فاء وذكرها في سورة المؤمنون»","url":""}]},{"id":"s7-351","number":351,"surah":7,"verses":[67],"references":[{"surah":7,"verses":[67]}],"verseLabel":"الأعراف: 67","question":"ما بلاغة رد هود بـ﴿ليس بي سفاهة ولكني رسول من رب العالمين﴾؟","answer":"نفى السفاهة عن نفسه نفيًا عامًا من غير أن يقابلهم بمثل إساءتهم، ثم أثبت الرسالة المنافية لما نسبوه إليه. وفي هذا الرد جمع بين الحلم في مخاطبتهم وتفنيد التهمة بالحقيقة التي ينبغي أن يعرفوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص602–603، تحت «بلاغة الرد في قوله تعالى: ﴿ليس بي سفاهة﴾»","url":""}]},{"id":"s7-352","number":352,"surah":7,"verses":[67],"references":[{"surah":7,"verses":[67]}],"verseLabel":"الأعراف: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿رسول من رب العالمين﴾ كما قال نوح؟","answer":"التعبير نفسه يقرر وحدة مصدر الرسالات؛ فهود ونوح لا يدعوان لأنفسهما، وإنما يبلغ كل منهما عن رب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص603–604، تحت «دلالة تنكير ﴿رسول﴾ وأنه ﴿من رب العالمين﴾»","url":""}]},{"id":"s7-353","number":353,"surah":7,"verses":[68],"references":[{"surah":7,"verses":[68]}],"verseLabel":"الأعراف: 68","question":"ما سرّ تعبير هود بقوله: ﴿أبلغكم رسالات ربي﴾ بالمضارع والجمع؟","answer":"المضارع لاستمرار التبليغ وتجدده، والجمع لتعدد ما يبلغه من أوامر ونواه ووعد ووعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص607–608، تحت «دلالة التعبير بالفعل المضارع: ﴿أبلغكم﴾»","url":""}]},{"id":"s7-354","number":354,"surah":7,"verses":[68],"references":[{"surah":7,"verses":[68]}],"verseLabel":"الأعراف: 68","question":"ما سرّ تعبير هود بقوله: ﴿وأنا لكم ناصح أمين﴾، وتعبير نوح بقوله: ﴿وأنصح لكم﴾؟","answer":"عبّر هود بالجملة الاسمية ﴿وأنا لكم ناصح أمين﴾ لإثبات رسوخ النصح والأمانة، وهو أنسب للرد على اتهامه بالكذب؛ أما نوح فذكر فعل النصح المتجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص610–611، تحت «التشابه بين قول نوح: ﴿أنصح لكم﴾ وقول هود: ﴿وأنا لكم ناصح أمين﴾»","url":""}]},{"id":"s7-355","number":355,"surah":7,"verses":[68],"references":[{"surah":7,"verses":[68]}],"verseLabel":"الأعراف: 68","question":"لماذا جمع هود بين ﴿ناصح﴾ و﴿أمين﴾؟","answer":"﴿ناصح﴾ يثبت إرادة الخير لهم، و﴿أمين﴾ يثبت صدقه في نقل رسالة ربه؛ فانتفى الغش في القصد والخيانة في البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص611، تحت «سر وصف الناصح بالأمانة في هذا الموضع الفريد»","url":""}]},{"id":"s7-356","number":356,"surah":7,"verses":[69],"references":[{"surah":7,"verses":[69]}],"verseLabel":"الأعراف: 69","question":"لماذا تكرر إنكار العجب نفسه في قصة هود؟","answer":"تكرر الإنكار لأن عادًا تعجبوا من الرسالة كما تعجب قوم نوح؛ فوحدة الشبهة اقتضت وحدة نقضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص614–615، تحت «الغرض من افتتاح الجملة بالاستفهام بالهمزة في قوله: ﴿أوعجبتم﴾»","url":""}]},{"id":"s7-357","number":357,"surah":7,"verses":[69],"references":[{"surah":7,"verses":[69]}],"verseLabel":"الأعراف: 69","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿لينذركم﴾ وحذف ﴿ولتتقوا ولعلكم ترحمون﴾؟","answer":"اكتفى بالإنذار لأن التحذير من الخطر أولى في هذا المقام، وحذف ما دل عليه من الغايات؛ فالإنذار يدعوهم إلى التقوى، والتقوى سبب الرحمة. وبذكر أول هذه السلسلة يستدل السامع على ما بعدها، كما صرح به خطاب نوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص618–619، تحت «فائدة تخصيص الإنذار دون التبشير»","url":""}]},{"id":"s7-358","number":358,"surah":7,"verses":[69],"references":[{"surah":7,"verses":[69]}],"verseLabel":"الأعراف: 69","question":"لماذا ذكّر عادًا بأنهم ﴿خلفاء من بعد قوم نوح﴾؟","answer":"ذكّرهم أنهم خلفاء بعد قوم نوح ليجمع لهم النعمة والعبرة: أورثهم الله الأرض بعد الهالكين، فلا يسلكوا طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص619–620، تحت «تلوين الخطاب بذكر النعم بعد ذكر النذارة»","url":""}]},{"id":"s7-359","number":359,"surah":7,"verses":[69],"references":[{"surah":7,"verses":[69]}],"verseLabel":"الأعراف: 69","question":"ما دلالة لفظ الخلق بين المصدرية والاسمية وأثره في المعنى في قوله تعالى: ﴿وزادكم في الخلق بسطة﴾؟","answer":"البسطة هي الزيادة في عظم الأجسام والقوة والقدرة؛ فذكّرهم بما خصهم الله به مما يقتضي الشكر لا الاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص621–622، تحت «دلالة لفظ الخلق بين المصدرية والاسمية وأثره في المعنى»","url":""}]},{"id":"s7-360","number":360,"surah":7,"verses":[69],"references":[{"surah":7,"verses":[69]}],"verseLabel":"الأعراف: 69","question":"لماذا كرر الأمر بالذكر: ﴿فاذكروا آلاء الله لعلكم تفلحون﴾؟","answer":"ذكّرهم أولًا بنعمتين مخصوصتين: الاستخلاف وزيادة الخلق، ثم عمم فقال ﴿فاذكروا آلاء الله﴾ ليشمل سائر النعم. فالتكرار توكيد للأمر بالذكر وانتقال من التفصيل إلى الإجمال، لا إعادة للنعمتين وحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص623–624، تحت «غرض تكرار التذكير بالنعم»","url":""}]},{"id":"s7-361","number":361,"surah":7,"verses":[70],"references":[{"surah":7,"verses":[70]}],"verseLabel":"الأعراف: 70","question":"ما سرّ تعبيرهم بقوله: ﴿أجئتنا لنعبد الله وحده﴾، فجعلوا التوحيد مستنكرًا؟","answer":"صاغوا التوحيد في صورة أمر مستنكر لأن ألفتهم للشرك قلبت موازينهم، حتى صار إفراد الخالق بالعبادة موضع تعجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص630–631، تحت «علة استنكارهم عبادة الله وحده دون الرب أو صفة أخرى»","url":""}]},{"id":"s7-362","number":362,"surah":7,"verses":[70],"references":[{"surah":7,"verses":[70]}],"verseLabel":"الأعراف: 70","question":"ما سرّ إسناد العبادة إلى الآباء في قولهم: ﴿ونذر ما كان يعبد آباؤنا﴾؟","answer":"احتجوا بعبادة الآباء بدل الحجة، تعظيمًا للموروث وتقليدًا له؛ فكشف التعبير أن مستندهم عادة السابقين لا سلطان من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص632–633، تحت «سر الإضافة إلى ضمير الجمع في قوله: ﴿يعبد آباؤنا﴾»","url":""}]},{"id":"s7-363","number":363,"surah":7,"verses":[70],"references":[{"surah":7,"verses":[70]}],"verseLabel":"الأعراف: 70","question":"ما سرّ طلبهم ﴿فأتنا بما تعدنا﴾، دون: بما تتوعدنا؟","answer":"سموا العذاب ﴿ما تعدنا﴾ تهكمًا وتحديًا؛ فالوعيد وعد من جهة الإخبار بأمر مستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص634–635، تحت «فائدة استعمال الوعد في الوعيد»","url":""}]},{"id":"s7-364","number":364,"surah":7,"verses":[70],"references":[{"surah":7,"verses":[70]}],"verseLabel":"الأعراف: 70","question":"لماذا قيدوا الطلب بـ﴿إن كنت من الصادقين﴾؟","answer":"علقوا طلب العذاب على صدقه استهزاءً وتكذيبًا: إن كنت صادقًا فيما تخبر به فأنزله بنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص635–636، تحت «نكتة استعمال إن الشرطية في قوله: ﴿إن كنت من الصادقين﴾»","url":""}]},{"id":"s7-365","number":365,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"ما سرّ تعبير هود بالماضي في قوله: ﴿قد وقع عليكم من ربكم رجس وغضب﴾؟","answer":"الماضي في ﴿وقع﴾ لتحقق العذاب ووجوبه وقربه حتى صُوّر كأنه وقع؛ فوعيد الله لا مرد له.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص640–641، تحت «سر العدول بالتعبير عن المستقبل بالفعل الماضي في ﴿قد وقع﴾»","url":""}]},{"id":"s7-366","number":366,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"لماذا جمع بين ﴿رجس وغضب﴾؟","answer":"يحتمل الرجس العذاب أو فساد النفس وخبثها. وعطف الغضب يزيد الوعيد شدة؛ فعلى معنى العذاب يجمع التعبير المؤاخذة وسببها، وعلى معنى خبث النفس يبين ما جرته ضلالتهم من الغضب. فاللفظان متكاملان في تصوير سوء حالهم وعاقبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص642–643، تحت «عطف الغضب على الرجس وتأخيره عليه»","url":""}]},{"id":"s7-367","number":367,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿أتجادلونني في أسماء سميتموها﴾، مع أن الجدال في معبودات؟","answer":"سمّاها أسماء لأنها لا تملك من حقيقة الألوهية إلا الألفاظ التي أطلقوها عليها؛ فالجدال في مسميات جوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص643–644، تحت «نكتة التعبير عن الأصنام بالأسماء في مقام المجادلة»","url":""}]},{"id":"s7-368","number":368,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"لماذا كرر مادة الاسم: ﴿أسماء سميتموها﴾؟","answer":"تكرار مادة الاسم يفضح منشأها البشري: هي أسماء اخترعتموها أنتم وآباؤكم، ولم يجعل الله لمسمياتها ألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص644–645، تحت «بلاغة الجناس الاشتقاقي بين لفظي ﴿أسماء﴾ و﴿سميتموها﴾»","url":""}]},{"id":"s7-369","number":369,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"ما سرّ إيثار التعبير بسلطان دون حجة في قوله تعالى: ﴿ما نزل الله بها من سلطان﴾؟","answer":"ينفي أن تكون لتلك المعبودات حجة منزلة من عند الله تثبت ألوهيتها. وسميت الحجة سلطانًا لقوتها وتسلطها على المعارض؛ فنفي السلطان يكشف أن الجدال قائم على أسماء واصطلاحات بشرية بلا برهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص645–646، تحت «سر إيثار التعبير بسلطان دون حجة»","url":""}]},{"id":"s7-370","number":370,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"لماذا خُتمت المواجهة بـ﴿فانتظروا إني معكم من المنتظرين﴾؟","answer":"هو تهديد بعد تمام الحجة: انتظروا العذاب الذي استعجلتموه، وأنا معكم منتظر لوعد الله، وفيه ثقة بتحققه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص647–648، تحت «بلاغة الفصل في قوله: ﴿إني معكم من المنتظرين﴾»","url":""}]},{"id":"s7-371","number":371,"surah":7,"verses":[71],"references":[{"surah":7,"verses":[71]}],"verseLabel":"الأعراف: 71","question":"ما دلالة صيغة ﴿نزّل﴾ في نفي الحجة عن عبادة الأصنام: ﴿ما نزّل الله بها من سلطان﴾؟","answer":"من توجيه المصدر أن صيغة التفعيل تستحضر تنزيل الوحي وتجدد البيان، فيشمل النفي أن يكون قد جاءهم من الله برهان على ألوهية أصنامهم، دفعة أو متجددًا. فدعواهم لا تستند إلى شيء من الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص645–646، تحت «دلالة صيغة فعّل في قوله: ﴿ما نزّل﴾»","url":""}]},{"id":"s7-372","number":372,"surah":7,"verses":[72],"references":[{"surah":7,"verses":[72]}],"verseLabel":"الأعراف: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنجيناه والذين معه برحمة منا﴾، فصرح بالرحمة؟","answer":"التصريح بـ﴿برحمة منا﴾ يبين أن النجاة فضل من الله ورحمته، لا استحقاقًا مستقلًا بالأعمال، وإن كانت صحبة الإيمان سببًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص652–653، تحت «معنى الباء في قوله: ﴿برحمة منا﴾ وموقع لفظ منا من معناها»","url":""}]},{"id":"s7-373","number":373,"surah":7,"verses":[72],"references":[{"surah":7,"verses":[72]}],"verseLabel":"الأعراف: 72","question":"ما وجه البلاغة في الكناية والعدول عن التعبير بهلاكهم إلى قطع دابرهم في قوله تعالى: ﴿وقطعنا دابر الذين كذبوا﴾؟","answer":"قطع الدابر استئصال آخر القوم وقطع أصلهم؛ فالكناية تصور هلاكًا عامًا لم يبق لهم بقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص653–654، تحت «بلاغة الكناية والعدول عن التعبير بهلاكهم إلى قطع دابرهم»","url":""}]},{"id":"s7-374","number":374,"surah":7,"verses":[72],"references":[{"surah":7,"verses":[72]}],"verseLabel":"الأعراف: 72","question":"لماذا عطف: ﴿وما كانوا مؤمنين﴾ بعد وصفهم بالتكذيب؟","answer":"عطف نفي الإيمان ليقرر أن التكذيب لم يكن عارضًا، بل صدر عن قوم لم يتلبسوا بالإيمان، وفيه بيان رسوخ سبب هلاكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص655–656، تحت «دلالة عطف: ﴿وما كانوا مؤمنين﴾ على ما قبلها»","url":""}]},{"id":"s7-375","number":375,"surah":7,"verses":[72],"references":[{"surah":7,"verses":[72]},{"surah":11,"verses":[58]}],"verseLabel":"الأعراف: 72؛ هود: 58","question":"ما سرّ التعبير في قوله تعالى في الأعراف عن هود: ﴿فأنجيناه﴾، وفي هود: ﴿نجّينا هودًا﴾ بصيغة التفعيل؟","answer":"يلائم التضعيف في ﴿نجّينا﴾ بسورة هود تفصيل النجاة وتكرار ذكرها: ﴿نجينا هودًا﴾ ثم ﴿ونجيناهم من عذاب غليظ﴾. وفي الأعراف ذكرت النجاة مرة واحدة فجاءت ﴿فأنجيناه﴾. والتكرار في هود يبرز عظم النعمة وشدة العذاب؛ ولا يلزم أن تكون الريح والعذاب الغليظ حادثتين منفصلتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص221، تحت «التشابه اللفظي بين آيتي هود والأعراف»","url":""}]},{"id":"s7-376","number":376,"surah":7,"verses":[72],"references":[{"surah":7,"verses":[72]},{"surah":41,"verses":[16]},{"surah":51,"verses":[41,42]},{"surah":69,"verses":[6,7,8]}],"verseLabel":"الأعراف: 72؛ فصلت: 16؛ الحاقة: 6–8؛ الذاريات: 41–42","question":"ما الذي تضيفه صور هلاك عاد المختلفة: ﴿وقطعنا دابر الذين كذبوا﴾ في الأعراف، و﴿ريحًا صرصرًا﴾ في فصلت، و﴿الريح العقيم﴾ في الذاريات، و﴿بريح صرصر عاتية﴾ في الحاقة؟","answer":"في الأعراف تبرز كناية قطع الدابر نتيجة الهلاك: الاستئصال الذي لا يبقي للمكذبين بقية. وفي فصلت تبرز ﴿صرصرًا﴾ شدة الريح وصوتها وبردها. وفي الذاريات تصفها ﴿العقيم﴾ بأنها لا تأتي بخير ولا نماء، وإنما تحمل الهلاك. وفي الحاقة تضيف ﴿عاتية﴾ تجاوزها الحد في القوة، ثم يفصل السياق مدة تسخيرها ومشهد صرعاهم. فالألفاظ تعرض جوانب متكاملة من العذاب ونتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص653–654، تحت «بلاغة الكناية والعدول عن التعبير بهلاكهم إلى قطع دابرهم»","url":""}]},{"id":"s7-377","number":377,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿وإلى ثمود أخاهم صالحًا﴾ على نسق هود؟","answer":"وصف صالح وهود بالأخوة لإبراز اشتراك كل منهما مع قومه في النسب، وفيه استمالة لهم بما بينهم من القرابة والتراحم. فهما يدعوان أقوامهما إلى الخير بلسان الناصح القريب، وليست الأخوة هنا موافقة لهم في الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص659–660، تحت «سر وصف صالح وهود بالأخوة لقومه وعدم وصف نوح بها»","url":""}]},{"id":"s7-378","number":378,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"لم أتبع صالح دعوته إلى التوحيد بقوله: ﴿قد جاءتكم بينة من ربكم﴾؟","answer":"لأن دعوته تقتضي بيان صدق رسالته، فكأنهم يسألون: ما الدليل على أنك مرسل إلينا؟ فجاء الجواب بالبينة المشاهدة، ثم بينها بقوله ﴿هذه ناقة الله لكم آية﴾، فجمعت الآية الدعوة وبرهانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص661–662، تحت «علة فصل قوله تعالى: ﴿قد جاءتكم بينة من ربكم﴾ عما قبله»","url":""}]},{"id":"s7-379","number":379,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"لماذا أضيفت الناقة إلى الله: ﴿ناقة الله﴾؟","answer":"أضيفت إلى الله تشريفًا وتعظيمًا، وإشارة إلى خصوصيتها بوصفها حجة وآية على صدق صالح. فهي آية خصهم الله بها، وفي الإضافة تنبيه إلى حرمتها ووجوب صيانتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص663، تحت «سر الإضافة في ﴿ناقة الله﴾»","url":""}]},{"id":"s7-380","number":380,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿لكم آية﴾ بتقديم ﴿لكم﴾؟","answer":"تقديم ﴿لكم﴾ يبرز اختصاصهم بالانتفاع بهذه الآية وقيام الحجة عليهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص663–664، تحت «دلالة التخصيص بشبه الجملة ﴿لكم﴾»","url":""}]},{"id":"s7-381","number":381,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]},{"surah":11,"verses":[64]}],"verseLabel":"الأعراف: 73؛ هود: 64","question":"ما سرّ إضافة الأرض إلى اسم الله في قوله تعالى: ﴿فذروها تأكل في أرض الله﴾؟","answer":"في الأعراف: 73: أي اتركوها حرة غير ممنوعة من الرعي؛ ووصف الأرض بأنها أرض الله يقرر ألا حق لهم في التضييق عليها فيما أباحه مالك الأرض.\n\nفي هود: 64: قابل ملكيتهم الضيقة بملك الله للأرض كلها؛ فلا حق لهم في منع آيته من رزقه، والمس بها يستجلب عذابًا قريبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص664–665، تحت «سر إضافة الأرض إلى اسم الله»","url":""}]},{"id":"s7-382","number":382,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"لماذا نُهي عن مجرد مسها بالسوء: ﴿ولا تمسوها بسوء﴾؟","answer":"النهي عن أدنى اتصال بسوء أبلغ في الحماية؛ فإذا حرم مجرد المس المؤذي كان العقر أولى بالتحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص665–666، تحت «دلالة التعبير بالمس في قوله: ﴿ولا تمسوها بسوء﴾»","url":""}]},{"id":"s7-383","number":383,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿فيأخذكم عذاب أليم﴾، فجعل العذاب آخذًا؟","answer":"صور إصابة العذاب لهم بالأخذ، وهو أبلغ في تصوير تمكنه وإحاطته بهم. وأسند الأخذ إلى العذاب كأنه الآخذ بنفسه، فيقوى التهديد ويستحضر السامع هول المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص666، تحت «بلاغة الاستعارة في قوله: ﴿فيأخذكم﴾»","url":""}]},{"id":"s7-384","number":384,"surah":7,"verses":[73],"references":[{"surah":7,"verses":[73]}],"verseLabel":"الأعراف: 73","question":"ما سرّ اختلاف وصف العذاب في قصة ناقة صالح: ﴿عذاب أليم﴾ في الأعراف، و﴿عذاب قريب﴾ في هود، و﴿عذاب يوم عظيم﴾ في الشعراء؟","answer":"في الأعراف وصف العذاب بالألم لإبراز أثره المؤذي في مقام الوعيد. وفي هود وصف بالقرب، وهو ملائم لقوله بعدها: ﴿تمتعوا في داركم ثلاثة أيام﴾. وفي الشعراء وصف يومه بالعظمة، ويذكر المصدر مناسبة ذكر اليوم لما سبق من تقسيم الشرب: ﴿لها شرب ولكم شرب يوم معلوم﴾؛ فلكل وصف جهة يبرزها من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص301–302، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-385","number":385,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"لماذا ذكّرهم بالاستخلاف من بعد عاد؟","answer":"ذكّرهم بالاستخلاف بعد عاد ليشكروا تمكين الله، وليعتبروا بهلاك من سبقهم حين كفروا وطغوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص676–677، تحت «فائدة ذكر عاد في قوله: ﴿من بعد عاد﴾»","url":""}]},{"id":"s7-386","number":386,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿وبوأكم في الأرض﴾، لا: أسكنكم؟","answer":"التبوئة ليست مجرد الإسكان، بل إنزالهم منازل مهيأة للاستقرار والانتفاع؛ فدل اللفظ على التمكين وحسن الإعداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص677–678، تحت «نكتة التعبير بلفظ: ﴿وبوأكم﴾»","url":""}]},{"id":"s7-387","number":387,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"ما دلالة جمال الكناية عن التنعم في الآية في قوله تعالى: ﴿تتخذون من سهولها قصورًا وتنحتون الجبال بيوتًا﴾؟","answer":"جمع بين القصور في السهول والبيوت المنحوتة في الجبال ليصور سعة تمكينهم وعمرانهم وانتفاعهم بلين الأرض وصلابتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص681–682، تحت «جمال الكناية عن التنعم في الآية»","url":""}]},{"id":"s7-388","number":388,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"لماذا عُدّي اتخاذ القصور بـ﴿من﴾، والنحت بلا حرف مماثل؟","answer":"تحتمل ﴿من﴾ التبعيض، أي يتخذون القصور من بعض السهول أو من مادتها، ويذكر المصدر وجهًا سببيًا أيضًا. أما ﴿تنحتون الجبال﴾ فأسند النحت إلى الجبال مباشرة للمبالغة في قوتهم وتمكنهم، حتى تبدو الجبال كأنها مطاوعة لصناعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص679، تحت «بلاغة استعمال ﴿من﴾ في ﴿من سهولها﴾»","url":""}]},{"id":"s7-389","number":389,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"لماذا تكرر: ﴿فاذكروا آلاء الله﴾ كما في قصة عاد؟","answer":"تكرر الأمر لأن ثمود أنعمت كما أنعمت عاد بالاستخلاف والتمكين؛ فتكرر موجب الشكر والتحذير من عاقبة الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص684–685، تحت «فائدة جمع لفظ ﴿آلاء﴾»","url":""}]},{"id":"s7-390","number":390,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تعثوا في الأرض مفسدين﴾، أليس العثو فسادًا؟","answer":"من توجيهاته أن ﴿مفسدين﴾ حال مؤكدة؛ لأن العثو هو شدة الفساد، فتزيد النهي تقريرًا وتشنيعًا. ويذكر المصدر احتمال أن تكون مقيدة لنوع العثو، فالمعنى ليس محصورًا في وجه إعرابي واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص686–687، تحت «الحال ﴿مفسدين﴾ بين التأكيد والتأسيس»","url":""}]},{"id":"s7-391","number":391,"surah":7,"verses":[74],"references":[{"surah":7,"verses":[74]}],"verseLabel":"الأعراف: 74","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وتنحتون الجبال بيوتًا﴾، وفي الشعراء: ﴿وتنحتون من الجبال بيوتًا﴾ بزيادة «من»؟","answer":"من توجيهاته أن ﴿من﴾ المذكورة قبلها في الأعراف: ﴿من سهولها قصورًا﴾ أغنت عن تكرارها، فجاء في الشعراء ﴿من الجبال﴾. ويذكر المصدر وجهًا آخر: حذفها في الأعراف يصور تمكنهم من نحت الجبال على سبيل المبالغة، وذكرها في الشعراء يبين أن النحت يقع في بعض الجبل؛ فالوجهان لا يختزلان في تعليل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص683–684، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-392","number":392,"surah":7,"verses":[75,88],"references":[{"surah":7,"verses":[75,88]}],"verseLabel":"الأعراف: 75؛ الأعراف: 88","question":"لماذا وُصف الملأ هنا بـ﴿الذين استكبروا﴾، ولم يقتصر على ﴿الملأ﴾؟","answer":"في الأعراف: 75: وصفهم بالاستكبار لأنه العلة التي صدتهم عن البينة وحملتهم على استضعاف المؤمنين ومجادلتهم.\n\nفي الأعراف: 88: وصفهم بالاستكبار لكشف الدافع إلى تهديد شعيب والمؤمنين؛ فالتعالي منعهم من قبول الحجة وحملهم على الإكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص693–694، تحت «نكتة التعبير بالاستكبار لا الكفر»","url":""}]},{"id":"s7-393","number":393,"surah":7,"verses":[75],"references":[{"surah":7,"verses":[75]}],"verseLabel":"الأعراف: 75","question":"ما سرّ توجيه الخطاب إلى ﴿لمن آمن منهم﴾، ففرقوا داخل المستضعفين؟","answer":"في العبارة توجيهان بحسب مرجع ﴿منهم﴾: إن عاد إلى المستضعفين، خص الكلام المؤمنين من بينهم؛ وإن عاد إلى القوم، كان ﴿لمن آمن﴾ بيانًا للمستضعفين المقصودين، وهم المؤمنون. فالتركيب يحدد أهل الإيمان الذين وجه إليهم الملأ خطابهم، ولا يوجب وحده أن يكون بعض المستضعفين غير مؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص695، تحت «توجيه إعراب البدل في ﴿لمن آمن منهم﴾»","url":""}]},{"id":"s7-394","number":394,"surah":7,"verses":[75],"references":[{"surah":7,"verses":[75]}],"verseLabel":"الأعراف: 75","question":"ما سرّ سؤالهم: ﴿أتعلمون أن صالحًا مرسل من ربه﴾، دون: أتؤمنون؟","answer":"سؤالهم عن العلم تهكم يراد به زعزعة يقين المؤمنين؛ فسألوا عن ثبوت الرسالة كأنها دعوى بعيدة، لا طلبًا صادقًا للإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص696–697، تحت «غرض الاستفهام في قوله: ﴿أتعلمون﴾»","url":""}]},{"id":"s7-395","number":395,"surah":7,"verses":[75],"references":[{"surah":7,"verses":[75]}],"verseLabel":"الأعراف: 75","question":"ما سرّ جواب المؤمنين: ﴿إنا بما أرسل به مؤمنون﴾، دون الاكتفاء بنعم؟","answer":"أجابوا بجملة مؤكدة تثبت إيمانهم بما أرسل به، لا بمجرد شخصه؛ فكان أبلغ من «نعم» وأقوى في مواجهة الاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص698–699، تحت «نكتة العدول بالحديث عن الإيمان بدل الإرسال»","url":""}]},{"id":"s7-396","number":396,"surah":7,"verses":[76],"references":[{"surah":7,"verses":[76]}],"verseLabel":"الأعراف: 76","question":"ما سرّ جواب المستكبرين: ﴿إنا بالذي آمنتم به كافرون﴾؟","answer":"أعلنوا الكفر بنفس الرسالة التي أعلن المؤمنون الإيمان بها، فجاءت الصلة ﴿بالذي آمنتم به﴾ لإظهار المقابلة والعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص702–703، تحت «دلالة التعبير بالموصول وصلته»","url":""}]},{"id":"s7-397","number":397,"surah":7,"verses":[76],"references":[{"surah":7,"verses":[76]}],"verseLabel":"الأعراف: 76","question":"لم قابل المستكبرون قول المؤمنين ﴿مؤمنون﴾ بقولهم ﴿كافرون﴾؟","answer":"جاء اسم الفاعل ﴿كافرون﴾ في مقابلة ﴿مؤمنون﴾ ليظهر إصرارهم على المناقضة والتحدي؛ فكأنهم يعلنون أن ثبات أولئك على الإيمان يقابله ثباتهم هم على الرفض، من غير مناقشة للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص704، تحت «علة التعبير بصيغة اسم الفاعل: ﴿كافرون﴾»","url":""}]},{"id":"s7-398","number":398,"surah":7,"verses":[77],"references":[{"surah":7,"verses":[77]}],"verseLabel":"الأعراف: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿فعقروا الناقة وعتوا عن أمر ربهم﴾، فجمع الفعل الحسي والتمرد القلبي؟","answer":"ذكر عقر الناقة أولًا لأنه أبرز مظهر من مظاهر تمردهم، ثم عطف عليه العتو الذي يشمله ويشمل غيره من العصيان. فهو من عطف العام على الخاص، ويبين أن فعلتهم لم تكن حادثة معزولة، بل مظهرًا لإصرارهم على مخالفة أمر ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص709–710، تحت «بلاغة العطف بين فعلي العقر والعتو»","url":""}]},{"id":"s7-399","number":399,"surah":7,"verses":[77,166],"references":[{"surah":7,"verses":[77,166]}],"verseLabel":"الأعراف: 77؛ الأعراف: 166","question":"لماذا عُدّي العتو بـ﴿عن﴾؟","answer":"في الأعراف77: ضمن العتو معنى الإعراض، فناسبه ﴿عن﴾؛ أي تمردوا معرضين عن أمر ربهم، ويذكر المصدر أيضًا وجه المجاوزة.\n\nوفي الأعراف166: يصور ﴿عتوا عن ما نهوا عنه﴾ إصرارهم على المخالفة وتجاوزهم النهي؛ فالمقام يبرز استمرار تمردهم بعد التذكير والتحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص709، تحت «بلاغة التضمين في تعدية الفعل ﴿وعتوا﴾ بحرف عن»","url":""}]},{"id":"s7-400","number":400,"surah":7,"verses":[77],"references":[{"surah":7,"verses":[77]}],"verseLabel":"الأعراف: 77","question":"لماذا نادوا صالحًا باسمه مجردًا: ﴿يا صالح﴾؟","answer":"نادوه باسمه مجردًا استخفافًا وتحديًا، فلم يعترفوا له بوصف الرسالة، ثم استعجلوا ما توعدهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص711، تحت «نكتة نداء صالح بالأداة يا المخصصة للبعيد»","url":""}]},{"id":"s7-401","number":401,"surah":7,"verses":[77],"references":[{"surah":7,"verses":[77]}],"verseLabel":"الأعراف: 77","question":"ما سرّ تكرار تحديهم بقولهم: ﴿ائتنا بما تعدنا﴾ على نسق عاد؟","answer":"كرروا تحدي عاد نفسه، فسمّوا الوعيد وعدًا تهكمًا واستعجالًا للعذاب، وأضافوا ﴿إن كنت من المرسلين﴾ زيادةً في التكذيب بالرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص711–712، تحت «لفظ الوعد بين الاستعارة التهكمية والحقيقة»","url":""}]},{"id":"s7-402","number":402,"surah":7,"verses":[78],"references":[{"surah":7,"verses":[78]}],"verseLabel":"الأعراف: 78","question":"لماذا اختيرت ﴿الرجفة﴾ لعذاب ثمود؟","answer":"تبرز ﴿الرجفة﴾ اضطراب الأرض وزلزلتها الشديدة، وتصويرها آخذة لهم يستحضر إحاطة العذاب بهم. وذكر الصيحة في موضع آخر يعرض جانب الصوت المهلك من الواقعة، فلا يلزم من اختلاف الوصف اختلاف الحادثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص720–721، تحت «توجيه المتشابه اللفظي في ذكر الرجفة والصيحة والطاغية»","url":""}]},{"id":"s7-403","number":403,"surah":7,"verses":[78],"references":[{"surah":7,"verses":[78]}],"verseLabel":"الأعراف: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿فأصبحوا في دارهم جاثمين﴾، مع تعدد مساكنهم؟","answer":"أُفردت ﴿دارهم﴾ لأن المراد بلدهم أو جنس مساكنهم، فكأن الديار المتعددة دار واحدة جمعهم فيها المصير نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص721–722، تحت «نكتة إفراد الدار في جملة: ﴿فأصبحوا في دارهم﴾»","url":""}]},{"id":"s7-404","number":404,"surah":7,"verses":[78],"references":[{"surah":7,"verses":[78]}],"verseLabel":"الأعراف: 78","question":"لماذا اختير ﴿جاثمين﴾؟","answer":"الجثوم لزوم المكان مع السقوط على الركب أو الصدر؛ فصوّرهم هامدين ملتصقين بالأرض بعد قوتهم وحركتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص724، تحت «بلاغة التعبير بلفظ ﴿جاثمين﴾»","url":""}]},{"id":"s7-405","number":405,"surah":7,"verses":[78],"references":[{"surah":7,"verses":[78]}],"verseLabel":"الأعراف: 78","question":"ما سرّ التعبير في قوله تعالى عن ثمود في الأعراف: ﴿في دارهم جاثمين﴾ بالإفراد، وفي هود: ﴿في ديارهم جاثمين﴾ بالجمع؟","answer":"وحّد ﴿دارهم﴾ في الأعراف مع ذكر الرجفة، وهي زلزلة أرضهم الجامعة؛ وجمع ﴿ديارهم﴾ في هود مع الصيحة الآتية من السماء، إذ كان بلوغها أوسع وأبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص722–723، تحت «توجيه المتشابه اللفظي في إفراد الدار وجمعها»","url":""}]},{"id":"s7-406","number":406,"surah":7,"verses":[79,93],"references":[{"surah":7,"verses":[79,93]}],"verseLabel":"الأعراف: 79؛ الأعراف: 93","question":"ما سر خطاب صالح وشعيب قومهما بعد هلاكهم بقولهما: ﴿يا قوم لقد أبلغتكم﴾؟","answer":"في الأعراف79: على حمل الخطاب على ما بعد الهلاك، يتضمن تقريع المكذبين وإظهار انقطاع عذرهم، مع التحسر على أنهم لم يقبلوا البلاغ والنصح.\n\nوفي الأعراف93: يقرر شعيب أنه أدى الرسالة وأخلص النصيحة، فيوبخ قومه على الإعراض ويظهر تمام الحجة عليهم، ثم يبين سبب ترك الأسى عليهم بعدما أصروا على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص725–726، تحت «عنوان القومية ﴿يا قوم﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s7-407","number":407,"surah":7,"verses":[79],"references":[{"surah":7,"verses":[79]}],"verseLabel":"الأعراف: 79","question":"لماذا أفرد ﴿رسالة ربي﴾، بينما قال نوح وهود ﴿رسالات﴾؟","answer":"أفرد ﴿رسالة﴾ لأن أبرز ما حُكي في قصة صالح الأمر المتعلق بالناقة، فكأنها رسالة واحدة؛ أما القصص الأخرى فتعدد فيها المبلغ من الأوامر.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص727، تحت «سبب إفراد لفظ الرسالة في ﴿رسالة ربي﴾»","url":""}]},{"id":"s7-408","number":408,"surah":7,"verses":[79],"references":[{"surah":7,"verses":[79]}],"verseLabel":"الأعراف: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكن لا تحبون الناصحين﴾، لا: لم تقبلوا نصحي؟","answer":"لم ينف مجرد قبولهم نصحه، بل أثبت فيهم نفرةً من جنس الناصحين؛ فالمشكلة فساد استعدادهم وكراهتهم لمن يريد لهم الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص728–729، تحت «بلاغة الكناية في جملة: ﴿لا تحبون الناصحين﴾»","url":""}]},{"id":"s7-409","number":409,"surah":7,"verses":[80],"references":[{"surah":7,"verses":[80]}],"verseLabel":"الأعراف: 80","question":"لم سماهم ﴿قومه﴾ في قصة لوط مع أنه لم يكن من نسبهم؟","answer":"أضيفوا إليه لأنه عاش بينهم وأرسل لإصلاحهم، فالعلاقة هنا علاقة معاشرة ورسالة. وفي تسميتهم قومه إبراز لصلته بهم وحرصه على دعوتهم، ولا يلزم أن تكون الإضافة دالة على النسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص734–735، تحت «فائدة إضافة قوم إلى الضمير العائد على لوط»","url":""}]},{"id":"s7-410","number":410,"surah":7,"verses":[80],"references":[{"surah":7,"verses":[80]}],"verseLabel":"الأعراف: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿أتأتون الفاحشة﴾ بالتعريف؟","answer":"من توجيهات التعريف أنه للعهد الذهني: الفعلة المعروفة بينهم. ويذكر المصدر حمله على الجنس مع المبالغة في قبحها، حتى كأنها جامعة لصفات الفحش؛ فالتعريف يحدد الفعل ويقوي التشنيع عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص736–737، تحت «معنى أل في لفظ ﴿الفاحشة﴾»","url":""}]},{"id":"s7-411","number":411,"surah":7,"verses":[80],"references":[{"surah":7,"verses":[80]}],"verseLabel":"الأعراف: 80","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من أحد﴾؟","answer":"نفى أن يكون أحد من العالمين سبقهم إليها، و﴿من﴾ تؤكد استغراق النفي؛ فجمع عليهم قبح الفاحشة وابتداعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص738–739، تحت «دلالة ﴿من﴾ في قوله تعالى: ﴿من أحد﴾»","url":""}]},{"id":"s7-412","number":412,"surah":7,"verses":[81],"references":[{"surah":7,"verses":[81]}],"verseLabel":"الأعراف: 81","question":"لماذا أكد: ﴿إنكم لتأتون الرجال شهوة﴾؟","answer":"في القراءة الخبرية أكد الكلام بإن واللام، فنزلوا منزلة من ينكر قبح فعله؛ لأنهم استمروا عليه غير مبالين بنهي لوط. وجاء التصريح بالفعل بعد إجماله باسم الفاحشة زيادة في التوبيخ والتقريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص742–743، تحت «بلاغة تأكيد الكلام في جملة ﴿إنكم لتأتون﴾»","url":""}]},{"id":"s7-413","number":413,"surah":7,"verses":[81],"references":[{"surah":7,"verses":[81]}],"verseLabel":"الأعراف: 81","question":"لماذا نصب ﴿شهوة﴾، ولم يقل: بشهوة؟","answer":"نُصبت على المفعول لأجله أو الحال؛ أي تأتونهم لأجل الشهوة أو مشتهين، فينكشف أن المحرك شهوة مجردة لا مقصد مشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص744–745، تحت «توجيه نكتة تقييد فعل الإتيان بلفظ ﴿شهوة﴾»","url":""}]},{"id":"s7-414","number":414,"surah":7,"verses":[81],"references":[{"surah":7,"verses":[81]}],"verseLabel":"الأعراف: 81","question":"ما فائدة مجيء الحال: ﴿مِنْ دُونِ النِّسَاءِ﴾؟","answer":"أي متجاوزين النساء اللاتي جعلهن الله موضعًا للفطرة والإعفاف؛ فالتعبير يبرز العدول عن الطريق المشروع إلى ضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص745–746، تحت «نكتة التعبير بالظرف دون»","url":""}]},{"id":"s7-415","number":415,"surah":7,"verses":[81],"references":[{"surah":7,"verses":[81]}],"verseLabel":"الأعراف: 81","question":"لماذا أضرب بقوله: ﴿بل أنتم قوم مسرفون﴾؟","answer":"﴿بل﴾ تترك مجرد وصف الفعل إلى كشف أصله في نفوسهم: الإسراف المتجاوز لكل حد هو الذي حملهم على تلك الفاحشة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص746–747، تحت «دلالة حرف الإضراب في قوله: ﴿بل أنتم قوم مسرفون﴾»","url":""}]},{"id":"s7-416","number":416,"surah":7,"verses":[81],"references":[{"surah":7,"verses":[81]}],"verseLabel":"الأعراف: 81","question":"لماذا خُتم إنكار فاحشة قوم لوط في الأعراف بـ﴿قوم مسرفون﴾، وفي النمل بـ﴿قوم تجهلون﴾؟","answer":"في الأعراف يبرز ﴿مسرفون﴾ تجاوزهم الحدود ورسوخ هذا الوصف فيهم، وجاء الاسم ملائمًا للفواصل الاسمية في السياق. وفي النمل يبرز ﴿تجهلون﴾ فساد تصرفهم مع وضوح الحق لهم؛ فالسورة تكثر فيها دلائل العلم، ومع ذلك يعملون عمل الجاهل. والمضارع يصور تجدد هذا التصرف واستمرارهم عليه، مع ملاءمته للفواصل الفعلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص747–748، تحت «سر اختيار مفردة الإسراف في وصف قوم لوط»","url":""}]},{"id":"s7-417","number":417,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"ما سرّ تسمية غير الجواب جوابًا في قوله تعالى: ﴿وما كان جواب قومه إلا أن قالوا أخرجوهم﴾؟","answer":"أسلوب القصر يكشف أن ردهم الوحيد لم يكن حجة، بل قرار إقصاء: لم يجدوا جوابًا إلا إخراج الداعين إلى الطهارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص751–752، تحت «سر تسمية غير الجواب جوابًا»","url":""}]},{"id":"s7-418","number":418,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"لماذا جُمِع لوط ومن معه في ﴿أخرجوهم من قريتكم﴾؟","answer":"جمعوه مع أهله ومن آمن به لأن إنكار الفاحشة والطهارة منها كان موقف جماعة، فصبوا تهديدهم على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص750–751، تحت «دلالة إسناد الإخراج إلى ضمير الجمع في ﴿أخرجوهم﴾»","url":""}]},{"id":"s7-419","number":419,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"لماذا أضافوا القرية إلى أنفسهم: ﴿قريتكم﴾؟","answer":"إضافتهم القرية إلى أنفسهم ادعاء للسلطان والاستئثار بها، وكأن الطاهرين غرباء لا حق لهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص753، تحت «دلالة الإضافة في قوله: ﴿قريتكم﴾»","url":""}]},{"id":"s7-420","number":420,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"ما سرّ تعبيرهم الساخر: ﴿إنهم أناس يتطهرون﴾؟","answer":"قالوها سخرية وتنقصًا، فجعلوا تنزه لوط ومن معه عن فعلهم سببًا لإخراجهم. ومن مفارقة التعبير أن ما أرادوه ذمًا هو في حقيقته مدح بالطهارة؛ فتكشف عبارتهم فساد المعيار الذي يحاكمون به الداعين إلى الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص754–755، تحت «بلاغة الكناية في قوله: ﴿إنهم أناس يتطهرون﴾»","url":""}]},{"id":"s7-421","number":421,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وما كان جواب قومه﴾ بالواو، وفي النمل والعنكبوت: ﴿فما كان جواب قومه﴾ بالفاء؟","answer":"من توجيه المصدر أن الفاء تلائم إبراز تفرع الرد على الكلام السابق؛ ففي النمل ختم الإنكار بالفعلين ﴿تبصرون﴾ و﴿تجهلون﴾، وهما أنسب بتقدير معنى التسبب. وفي العنكبوت تفرع التحدي على تعداد أفعالهم وتقريعهم. أما الأعراف فختمت بالوصف ﴿مسرفون﴾، فجاءت الواو لربط حكاية جوابهم بما قبلها. وهذه مناسبة للسياقات المذكورة، وليست قاعدة تلزم كل اسم أو فعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص756–757، تحت «المتشابه اللفظي»","url":""}]},{"id":"s7-422","number":422,"surah":7,"verses":[82],"references":[{"surah":7,"verses":[82]}],"verseLabel":"الأعراف: 82","question":"ما سرّ التعبير في الأعراف: ﴿أخرجوهم من قريتكم﴾ بالضمير، وفي النمل: ﴿أخرجوا آل لوط من قريتكم﴾ بالاسم الظاهر؟","answer":"في الأعراف عُرف لوط وأهله من السياق فأغنى عن تسميتهم الضمير في ﴿أخرجوهم﴾. وفي النمل زاد تفصيل إنكار أفعال القوم وتقريعهم، فناسبه التصريح بـ﴿آل لوط﴾ في جوابهم؛ فوافق الإيجاز هنا والتصريح هناك بناء كل سياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص756–757، تحت «المتشابه اللفظي»","url":""}]},{"id":"s7-423","number":423,"surah":7,"verses":[83],"references":[{"surah":7,"verses":[83]}],"verseLabel":"الأعراف: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنجيناه وأهله إلا امرأته﴾، دون أن يقال: وزوجه؟","answer":"يلفت المصدر إلى أن لفظ ﴿امرأته﴾ هنا يبرز اختلافها عنه في الدين والموقف، مع بقاء صلة النكاح؛ فهي من أهله في الظاهر، لكنها ليست معهم في الإيمان والنجاة. فالتسمية تلائم هذا الانفصال المعنوي في سياق الاستثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص762–763، تحت «امرأته وزوجه»","url":""}]},{"id":"s7-424","number":424,"surah":7,"verses":[83],"references":[{"surah":7,"verses":[83]}],"verseLabel":"الأعراف: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿كانت من الغابرين﴾، لا: فهلكت؟","answer":"﴿الغابرون﴾ الباقون خلف الراحلين؛ فصورتها ممن تخلف مع قومها عن ركب النجاة فشملها الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص760–761، تحت «بلاغة الاستئناف في ﴿كانت من الغابرين﴾»","url":""}]},{"id":"s7-425","number":425,"surah":7,"verses":[83],"references":[{"surah":7,"verses":[83]}],"verseLabel":"الأعراف: 83","question":"ما سرّ التعبير في قوله تعالى عن امرأة لوط في الأعراف: ﴿كانت من الغابرين﴾، وفي النمل: ﴿قدرناها من الغابرين﴾؟","answer":"﴿كانت﴾ تبين صيرورتها في الهالكين كما سبق في علم الله، و﴿قدرناها﴾ في النمل تصرح بأن ذلك كان بتقدير الله؛ فالثاني يبين منشأ الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص761–762، تحت «المتشابه اللفظي»","url":""}]},{"id":"s7-426","number":426,"surah":7,"verses":[84],"references":[{"surah":7,"verses":[84]}],"verseLabel":"الأعراف: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿وأمطرنا عليهم مطرًا﴾، فكرر مادة المطر؟","answer":"ذكر المطر نكرة بعد فعل الإمطار لتعظيمه وتهويل نوعه؛ فهو مطر غير مألوف من حجارة العذاب. وفي تسميته مطرًا تصوير لنزول الحجارة متتابعة من السماء كما ينزل المطر، مع اختلاف أثرها المهلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص765–766، تحت «بلاغة الاستعارة في لفظ الإمطار في قوله: ﴿وأمطرنا عليهم مطرًا﴾»","url":""}]},{"id":"s7-427","number":427,"surah":7,"verses":[84],"references":[{"surah":7,"verses":[84]}],"verseLabel":"الأعراف: 84","question":"لماذا عُدّي المطر بـ﴿على﴾؟","answer":"عُدّي بـ﴿على﴾ لأن المطر انصب من فوقهم واستعلى عليهم، وفي الحرف إيحاء بإحاطة العذاب وقهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص766، تحت «دلالة حرف الاستعلاء في جملة: ﴿عليهم مطرًا﴾»","url":""}]},{"id":"s7-428","number":428,"surah":7,"verses":[84],"references":[{"surah":7,"verses":[84]}],"verseLabel":"الأعراف: 84","question":"لماذا خُتمت القصة بـ﴿فانظر كيف كان عاقبة المجرمين﴾؟","answer":"الخاتمة تحول الخبر إلى عبرة مشاهدة، وتأمر بالنظر في مصير من أجرموا ليحذر المخاطبون طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص766–767، تحت «نوع الاستفهام في قوله: ﴿فانظر كيف كان عاقبة المجرمين﴾»","url":""}]},{"id":"s7-429","number":429,"surah":7,"verses":[84],"references":[{"surah":7,"verses":[84]}],"verseLabel":"الأعراف: 84","question":"لم ختم هلاك قوم لوط في الأعراف بـ﴿فانظر كيف كان عاقبة المجرمين﴾، وفي النمل بـ﴿فساء مطر المنذرين﴾؟","answer":"في الأعراف سبقت الإشارة إلى أنهم ابتدعوا الفاحشة: ﴿ما سبقكم بها من أحد من العالمين﴾، فناسبها وصفهم بالإجرام والأمر بالاعتبار بعاقبتهم. وفي النمل تتابع الإنذار والوعظ وتقريعهم مع إبصارهم ووضوح قبح فعلهم، فناسب وصفهم بالمنذرين وذم المطر الذي نزل بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص767–768، تحت «توجيه المتشابه بين الأعراف والنمل»","url":""}]},{"id":"s7-430","number":430,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"ما النكتة البلاغية في التعبير بلفظ الأخوة في قوله تعالى: ﴿وإلى مدين أخاهم شعيبًا﴾؟","answer":"الأخوة أخوة نسب وقوم، وفيها تقريب للنصح وإقامة للحجة بلسان رجل يعرفونه، لا أخوة موافقة في العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص772–773، تحت «نكتة التعبير بلفظ الأخوة»","url":""}]},{"id":"s7-431","number":431,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"لماذا انتقل شعيب من التوحيد إلى ﴿أوفوا الكيل والميزان﴾؟","answer":"بعد تقرير أصل التوحيد انتقل إلى أبرز فساد عملي اشتهروا به؛ لأن صحة العبادة تثمر العدل في معاملات الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص778–779، تحت «مناسبة الترتيب في الأوامر والنواهي»","url":""}]},{"id":"s7-432","number":432,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"لماذا جمع بين الكيل والميزان؟","answer":"جمعهما ليستوعب وسائل تقدير الحقوق: المكيلات والموزونات، فلا يبقى باب للتطفيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص770، تحت «شرح المفردات: ﴿الكيل﴾ و﴿الميزان﴾»","url":""}]},{"id":"s7-433","number":433,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تبخسوا الناس أشياءهم﴾، دون أن يقال: أموالهم؟","answer":"﴿أشياءهم﴾ أعم من الأموال؛ فيشمل كل حق مادي أو معنوي يجب توفيته، قليلًا كان أو كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص777–778، تحت «نكتة التعبير بلفظ: ﴿أشياءهم﴾»","url":""}]},{"id":"s7-434","number":434,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿بعد إصلاحها﴾ كما في الآية 56؟","answer":"نهى عن إفساد الأرض بعد أن أصلحها الله بالشرائع والنظام والأمن، كما سبق في الآية 56؛ فالجريمة أشد بعد قيام الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص779–780، تحت «نكتة التعبير بالقيد: ﴿بعد إصلاحها﴾»","url":""}]},{"id":"s7-435","number":435,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"ما مناسبة التذييل بالجملة الشرطية في قوله تعالى: ﴿ذلكم خير لكم إن كنتم مؤمنين﴾؟","answer":"الإشارة تجمع التوحيد وإيفاء الحقوق وترك الفساد، وهذه خير لهم في الدنيا والآخرة إن صدق إيمانهم وعملوا بمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص782–783، تحت «مناسبة التذييل بالجملة الشرطية»","url":""}]},{"id":"s7-436","number":436,"surah":7,"verses":[86],"references":[{"surah":7,"verses":[86]}],"verseLabel":"الأعراف: 86","question":"لماذا نهى: ﴿ولا تقعدوا بكل صراط توعدون﴾؟","answer":"نهى عن ترصد الطرق لتخويف الناس ومنعهم من شعيب ودين الله؛ فالقعود تصوير للملازمة والتعمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص786–787، تحت «جملة ﴿ولا تقعدوا﴾ بين الكناية والاستعارة التمثيلية»","url":""}]},{"id":"s7-437","number":437,"surah":7,"verses":[86],"references":[{"surah":7,"verses":[86]}],"verseLabel":"الأعراف: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿بكل صراط﴾ بالإفراد بعد ﴿كل﴾؟","answer":"﴿كل﴾ تضاف إلى المفرد لإفادة العموم، أي لا تقعدوا على أي طريق من الطرق؛ فالإفراد لا يحد المعنى بطريق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص787، تحت «دلالة التعبير بلفظ العموم ﴿بكل﴾»","url":""}]},{"id":"s7-438","number":438,"surah":7,"verses":[86],"references":[{"surah":7,"verses":[86]}],"verseLabel":"الأعراف: 86","question":"ما دلالة العطف في ﴿توعدون وتصدون عن سبيل الله... وتبغونها عوجًا﴾؟","answer":"يجمع العطف وجوهًا متغايرة من فسادهم: تخويف من يريد الإيمان، وصده عن طريق الحق، والطعن في سبيل الله وطلب الزيغ عنه. فالأفعال مترابطة في مقصد الإفساد، مع تميز كل وجه منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص790–791، تحت «دلالة العطف على المغايرة وترابط المعاني»","url":""}]},{"id":"s7-439","number":439,"surah":7,"verses":[86],"references":[{"surah":7,"verses":[86]}],"verseLabel":"الأعراف: 86","question":"ما مناسبة الحديث عن تكثير العدد في قوله تعالى: ﴿واذكروا إذ كنتم قليلًا فكثركم﴾؟","answer":"ذكّرهم بنعمة التكثير بعد القلة ليدعوهم إلى الشكر وترك الصد عن الإيمان. ويحتمل التكثير كثرة العدد بعد القلة، والقوة بعد الضعف، والغنى بعد الفقر؛ فالتعبير يستحضر حالهم الأولى وما أنعم الله به عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص791–792، تحت «مناسبة الحديث عن تكثير العدد»","url":""}]},{"id":"s7-440","number":440,"surah":7,"verses":[86],"references":[{"surah":7,"verses":[86]}],"verseLabel":"الأعراف: 86","question":"لماذا خُتمت بـ﴿وانظروا كيف كان عاقبة المفسدين﴾؟","answer":"أمرهم أن يعتبروا بمصائر المفسدين قبلهم؛ فمن سنن الله أن الإفساد بعد الإصلاح ينتهي إلى الخسران والهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص792–793، تحت «سر الدعوة إلى النظر في عاقبة المفسدين»","url":""}]},{"id":"s7-441","number":441,"surah":7,"verses":[87],"references":[{"surah":7,"verses":[87]}],"verseLabel":"الأعراف: 87","question":"لم عبّر عن الفريقين بلفظ ﴿طائفة﴾ في ﴿وإن كان طائفة منكم آمنوا... وطائفة لم يؤمنوا﴾؟","answer":"الطائفة تطلق على جماعة من الناس، وفي اختيارها هنا إشارة إلى كثرة الفريقين؛ فلا يلزم من إيمان طائفة أن يكون الذين لم يؤمنوا قليلين بالنسبة إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص797، تحت «نكتة التعبير بلفظ ﴿طائفة﴾ دون ما يقاربها من الألفاظ»","url":""}]},{"id":"s7-442","number":442,"surah":7,"verses":[87],"references":[{"surah":7,"verses":[87]}],"verseLabel":"الأعراف: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿بِالذي أرسلت به﴾ بالبناء للمجهول؟","answer":"بُني ﴿أرسلت﴾ للمجهول لأن المقصود ما حُمّل من الرسالة لا تعيين المرسِل، وهو معلوم أنه الله من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص799، تحت «نكتة التعبير بالفعل المبني للمفعول ﴿أرسلت﴾»","url":""}]},{"id":"s7-443","number":443,"surah":7,"verses":[87],"references":[{"surah":7,"verses":[87]}],"verseLabel":"الأعراف: 87","question":"لماذا أمر الفريقين بالصبر: ﴿فاصبروا حتى يحكم الله بيننا﴾؟","answer":"على توجيه الخطاب إلى الفريقين، يكون الصبر للمؤمنين على ما يصيبهم، ويكون في حق المكذبين بمعنى الانتظار والوعيد؛ حتى يفصل الله بينهما. ويذكر المصدر أيضًا قولًا بتخصيص الخطاب بالكافرين، فلا يجزم بأن الأمر موجه إلى الجميع على وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص799–800، تحت «فعل ﴿فاصبروا﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s7-444","number":444,"surah":7,"verses":[87],"references":[{"surah":7,"verses":[87]}],"verseLabel":"الأعراف: 87","question":"لماذا خُتمت بـ﴿وهو خير الحاكمين﴾؟","answer":"الخاتمة تثبت عدل الحكم وكماله وتطمئن المؤمنين؛ فلا حاكم أصدق ولا أعلم ولا أعدل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص801–802، تحت «بلاغة التذييل بقوله: ﴿وهو خير الحاكمين﴾»","url":""}]},{"id":"s7-446","number":446,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا قدّموا إخراج شعيب على إعادته في ملتهم: ﴿لنخرجنك... أو لتعودن﴾؟","answer":"قدموا الإخراج لأنه العقوبة العاجلة التي يملكونها، ثم جعلوا الرجوع في ملتهم بديلًا يمنعها؛ فخيّروهم بين الوطن والعقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص17، تحت «نكتة تقديم القسم»","url":""}]},{"id":"s7-447","number":447,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا أكّدوا التهديد باللام والنون: ﴿لنخرجنك﴾ و﴿لتعودن﴾؟","answer":"اللام والنون الثقيلة توكد تصميمهم على إنفاذ أحد الأمرين، وتصور شدة التهديد والتسلط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص17، تحت «بلاغة حشد المؤكدات»","url":""}]},{"id":"s7-448","number":448,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"ما النكتة البلاغية في توسيط النداء باسم شعيب الظاهر؟","answer":"خصّوا شعيبًا بالاسم لأنه أصل الدعوة ومقدم المؤمنين، وجاء نداؤه باسمه في سياق التغليظ والتهديد وقلة الاحترام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص16–17، تحت «نكتة توسيط النداء بالاسم الظاهر لنبيهم»","url":""}]},{"id":"s7-1606","number":1606,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا قالوا: ﴿والذين آمنوا معك﴾، ولم يذكروا متعلق الإيمان؟","answer":"لأن خصوم شعيب لا يعترفون برسالته، فحذفوا متعلق الإيمان وعدلوا إلى وصف المصاحبة بقولهم ﴿معك﴾، مع إبراز ارتباط أتباعه به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص18، تحت «سر حذف متعلق الفعل ﴿آمنوا﴾»","url":""}]},{"id":"s7-449","number":449,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا حُذف متعلَّق ﴿آمنوا﴾، فلم يقل: آمنوا بك؟","answer":"لأن القائلين من خصوم شعيب لا يعترفون بالإيمان به، فاستعاضوا عن التصريح بمتعلق الإيمان بذكر المصاحبة في ﴿معك﴾. ويذكر المصدر أيضًا أن المتعلق معلوم من السياق، وأن حذفه يناسب مقام إنكارهم واستهجانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص18، تحت «سر حذف متعلق الفعل ﴿آمنوا﴾»","url":""}]},{"id":"s7-450","number":450,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"ما وجه قولهم لشعيب: ﴿لتعودن في ملتنا﴾ مع أنه نبي لم يكن على ملتهم؟","answer":"من استعمالات العود معنى الصيرورة، فيكون المراد: لتصيرن في ملتنا وتدخلن فيها، ولا يلزم أن يكون شعيب قد كان عليها من قبل. ويلائم ذلك تعديته بـ﴿في﴾ التي تصور الملة وعاءً يحيط بالداخل فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص17، تحت «سر تعدية لفظ العود بـ﴿في﴾»","url":""}]},{"id":"s7-451","number":451,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا عُدّي ﴿لتعودن﴾ بـ﴿في﴾: ﴿في ملتنا﴾؟","answer":"عُدّي العود بـ﴿في﴾ لتصوير الملة كالحيز المحيط بمن يدخل فيها ويتمكن منها، وفيه بيان إرادتهم دمج المؤمنين في باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص17، تحت «سر تعدية لفظ العود بـ﴿في﴾»","url":""}]},{"id":"s7-452","number":452,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا أجابهم شعيب باستفهام: ﴿أولو كنا كارهين﴾؟","answer":"الاستفهام إنكاري: أتجبروننا على ملتكم ولو كنا شديدي الكراهة لها؟ فهو رفض للإكراه وإظهار لبطلان عرضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص18–19، تحت «بلاغة الاستفهام في ﴿أولو﴾»","url":""}]},{"id":"s7-453","number":453,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"لماذا اختيرت ﴿لو﴾ في ﴿أولو كنا كارهين﴾، وحُذف جوابها؟","answer":"على جعل ﴿لو﴾ وصلية، تذكر الحالة التي كان ينبغي أن تمنع إجبارهم، وهي كراهتهم للملة؛ فيكون المعنى: أتردوننا إليها ولو كنا كارهين؟ وحذف جوابها لدلالة ما قبلها عليه، فيبالغ الاستفهام في إنكار الإكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص19، تحت «نكتة التعبير بـ﴿لو﴾ في الفاصلة»","url":""}]},{"id":"s7-454","number":454,"surah":7,"verses":[88],"references":[{"surah":7,"verses":[88]}],"verseLabel":"الأعراف: 88","question":"ما دلالة صيغة اسم الفاعل في ﴿أولو كنا كارهين﴾؟","answer":"تفيد صيغة ﴿كارهين﴾ ثبوت كراهيتهم للإذعان إلى ملة قومهم ودوامها، وتنزلها منزلة الخصلة المستقرة؛ فهي كراهة راسخة، لا انفعال عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص20، تحت «دلالة صيغة اسم الفاعل»","url":""}]},{"id":"s7-455","number":455,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿قد افترينا على الله كذبًا﴾، فجمع بين الافتراء والكذب؟","answer":"الافتراء هو اختلاق الكذب عمدًا ونسبته إلى الله؛ فذكر ﴿كذبًا﴾ يصرح بحقيقة الافتراء ويبالغ في تقبيحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص29، تحت «بلاغة مصدرية الكذب وتنكيره»","url":""}]},{"id":"s7-456","number":456,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا جاء الشرط بـ﴿إن عدنا﴾ مع أن الخصوم قالوا: ﴿لتعودن﴾؟","answer":"جاء الشرط لبيان المحال المترتب على فرض رجوعهم: إن وقع العود الذي تطلبونه فقد افترينا؛ وليس فيه تردد في ثباتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص29–30، تحت «بلاغة الربط بين الشرط وجوابه»","url":""}]},{"id":"s7-457","number":457,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما دلالة ضمائر المتكلمين في جواب شعيب: ﴿افترينا﴾ و﴿عدنا﴾ و﴿نجانا﴾؟","answer":"يضم شعيب المؤمنين إلى نفسه في الجواب، فيظهر شدة اتباعهم له ومشاركتهم إياه في الثبات على الإيمان. وفي جمعهم بضمير واحد تواضع لهم وتأكيد أن دعوتهم ليست لمصلحة شخصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص28–29، تحت «علة التعبير بضمير المتكلم»","url":""}]},{"id":"s7-458","number":458,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿بعد إذ نجانا الله منها﴾، دون أن يقال: بعد أن خرجنا منها؟","answer":"سمّى مفارقة الملة نجاةً لأن الشرك هلاك، ولأن الخروج من سلطانه وفتنته فضل من الله لا مجرد انتقال بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص30، تحت «بلاغة الكناية في فعل الإنجاء»","url":""}]},{"id":"s7-459","number":459,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما دلالة التناوب بين اسم الجلالة ولفظ ﴿ربنا﴾ في جواب شعيب؟","answer":"يرسخ ذكر اسم الجلالة الإقرار بألوهية الله ووحدانيته، ويستحضر وصف ﴿ربنا﴾ ولايته للمؤمنين وتدبيره أمرهم. وفي الجمع بينهما رد على أهل الشرك الذين يتعلقون بغير الله ويعتمدون على أنفسهم وقوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص33، تحت «تناوب التعبير بأسماء الله وصفاته»","url":""}]},{"id":"s7-460","number":460,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يكون لنا أن نعود فيها﴾ بدل «ولن نعود فيها»؟","answer":"هذا التركيب ينفي الاستحقاق والإمكان اللائق بهم، لا مجرد نية مستقبلية؛ أي لا يصح ولا يستقيم لنا أن نعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص31، تحت «فائدة لام الجحود»","url":""}]},{"id":"s7-461","number":461,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا استثنى: ﴿إلا أن يشاء الله ربنا﴾ بعد التصريح باستحالة العود؟","answer":"في الاستثناء تفويض الأمر إلى الله وتأدب معه، وإقرار بأن الدوام على الإيمان بتثبيته ومشيئته. فهو افتقار إليه وسؤال للثبات، مع البراءة من الاتكال على النفس، ويجري على أدب الأنبياء في تعليق أمرهم بعلم الله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص31–32، تحت «سر التعبير بالمشيئة دون غيرها»","url":""}]},{"id":"s7-462","number":462,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا وصف الله هنا بـ﴿ربنا﴾؟","answer":"اسم الرب يستحضر الولاية والتربية والحفظ؛ فهو الذي نجاهم ويتولى تثبيتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص32، تحت «فائدة إيثار لفظ الربوبية في قوله: ﴿إلا أن يشاء الله ربنا﴾»","url":""}]},{"id":"s7-463","number":463,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا كرر ﴿ربنا﴾ في ﴿إلا أن يشاء الله ربنا وسع ربنا كل شيء علمًا﴾؟","answer":"في تكرار ﴿ربنا﴾ مضافًا إلى ضميرهم إظهار للافتقار إلى ربهم، وتلذذ بذكره واستحضار لربوبيته. ويؤكد هذا الإظهار تضرعهم وتفويضهم أمر الثبات إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص32–33، تحت «إيثار لفظ الرب مضافًا»","url":""}]},{"id":"s7-464","number":464,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿وسع ربنا كل شيء علمًا﴾، فجعل العلم تمييزًا للسعة؟","answer":"نُصب ﴿علمًا﴾ تمييزًا يفسر جهة السعة: ليست سعة مكان، بل إحاطة علم بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص33–34، تحت «بلاغة المجاز في لفظ السعة»","url":""}]},{"id":"s7-465","number":465,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا قدّم الجار والمجرور في ﴿على الله توكلنا﴾؟","answer":"قدم ﴿على الله﴾ لإفادة الاختصاص والاهتمام: عليه وحده اعتمدنا في الثبات والحماية والحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص34، تحت «نكتة تقديم الجار والمجرور»","url":""}]},{"id":"s7-466","number":466,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿ربنا افتح بيننا وبين قومنا بالحق﴾، واختار «افتح» بمعنى احكم؟","answer":"الفتح أصله إزالة الإغلاق والفصل بين شيئين، فاستعير للحكم الذي يكشف الحق ويفصل النزاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص37–38، تحت «الفتح والفصل»","url":""}]},{"id":"s7-467","number":467,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لم كرر ﴿بين﴾ في ﴿ربنا افتح بيننا وبين قومنا بالحق﴾؟","answer":"يزيد التكرار تأكيد التباعد بين المؤمنين وقومهم بعد إصرار المكذبين على الكفر. ويقابله قوله السابق ﴿حتى يحكم الله بيننا﴾ حيث كان مقام الدعوة والمحاورة لا يزال قائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص35، تحت «فائدة تكرار الظرف ﴿بين﴾»","url":""}]},{"id":"s7-468","number":468,"surah":7,"verses":[89],"references":[{"surah":7,"verses":[89]}],"verseLabel":"الأعراف: 89","question":"لماذا خُتم الدعاء بـ﴿وأنت خير الفاتحين﴾ لا «خير الحاكمين» كما في الآية 87؟","answer":"لما دعا بلفظ ﴿افتح﴾ ناسبت الخاتمة ﴿خير الفاتحين﴾، أما الآية 87 فذكرت الحكم صراحة فختمت بـ﴿خير الحاكمين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص35–36، تحت «سر ختام جملة الفاصلة بالمصدر والجمع»","url":""}]},{"id":"s7-469","number":469,"surah":7,"verses":[90],"references":[{"surah":7,"verses":[90]}],"verseLabel":"الأعراف: 90","question":"لماذا أعيد وصف القادة بـ﴿الملأ الذين كفروا من قومه﴾ بعد وصفهم بالاستكبار؟","answer":"أعاد وصف الكفر لتسجيل حقيقة موقفهم بعد تهديدهم، ولأن خطابهم التالي تحريض عقدي يصد الناس عن اتباع شعيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص41، تحت «سر إيثار الوصف بالكفر دون غيره»","url":""}]},{"id":"s7-470","number":470,"surah":7,"verses":[90],"references":[{"surah":7,"verses":[90]}],"verseLabel":"الأعراف: 90","question":"ما دلالة صيغة الافتعال في قولهم: ﴿لئن اتبعتم شعيبًا﴾؟","answer":"تشير صيغة الاتباع هنا إلى الانقياد والمطاوعة، وقد جاء تهديد الملأ في مقام حمل قومهم على ترك مطاوعة شعيب والاستمرار على باطلهم. فالتعبير يتعلق بالاستجابة لدعوته واتباع طريقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص41–42، تحت «بلاغة صيغة الافتعال في فعل الاتباع»","url":""}]},{"id":"s7-471","number":471,"surah":7,"verses":[90,92],"references":[{"surah":7,"verses":[90,92]}],"verseLabel":"الأعراف: 90؛ الأعراف: 92","question":"ما أثر التعريف بالموصول في ﴿الملأ الذين كفروا من قومه﴾، ثم في ﴿الذين كذبوا شعيبًا﴾؟","answer":"في الأعراف: 90 يسجل وصف الملأ بالكفر حالهم الذميمة التي صدر عنها تهديد المؤمنين. وفي الأعراف: 92 يربط وصفهم بتكذيب شعيب بين جرمهم وهلاكهم وخسرانهم، فيبين سبب الحكم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص53، تحت «بلاغة التعريف بالموصول»","url":""}]},{"id":"s7-472","number":472,"surah":7,"verses":[90],"references":[{"surah":7,"verses":[90]}],"verseLabel":"الأعراف: 90","question":"لماذا أكدوا جوابهم بـ﴿إنكم إذًا لخاسرون﴾؟","answer":"أكدوا بـ﴿إن﴾ واللام، وجاءت ﴿إذًا﴾ جزاءً للاتباع المزعوم؛ فصوّروا الخسران نتيجة محققة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص42، تحت «بلاغة حشد المؤكدات»","url":""}]},{"id":"s7-473","number":473,"surah":7,"verses":[90],"references":[{"surah":7,"verses":[90]}],"verseLabel":"الأعراف: 90","question":"لماذا وصفوا المؤمنين بالخاسرين مع أن الخاسرين الحقيقيين هم المكذبون في الآية 92؟","answer":"سموا المؤمنين خاسرين لقلب الحقائق وتخويفهم من فوات مصالح الدنيا؛ ثم رد السياق القصر عليهم فأثبت أن المكذبين هم الخاسرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52–53، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-474","number":474,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿فأخذتهم الرجفة﴾، فجعل الرجفة آخذة لهم؟","answer":"جُعلت الرجفة آخذةً استعارةً لشدة إحاطتها بهم وتمكنها منهم، كآخذ لا يترك مأخوذه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص46، تحت «بلاغة المجاز في لفظ الأخذ»","url":""}]},{"id":"s7-475","number":475,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"لماذا اختيرت ﴿الرجفة﴾ لعذاب قوم شعيب؟","answer":"ذكر الرجفة يلائم تهديدهم شعيبًا ومن آمن معه بالإخراج من أرضهم؛ فجاءهم ما زعزع الأرض تحتهم. ويذكر المصدر أن الرجفة والصيحة متلازمتان في هذا العذاب، وأن اختيار كل تعبير يناسب سياقه، فلا يدل اختلاف اللفظ على تناقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص46–47، تحت «توجيه التشابه في التعبير عن العذاب»","url":""}]},{"id":"s7-476","number":476,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"كيف يصور لفظ ﴿فأصبحوا﴾ ظهور أثر العذاب في ﴿فأصبحوا في دارهم جاثمين﴾؟","answer":"يبرز التعبير ظهور هلاكهم في الصباح أمام الناس للعظة والاعتبار. ويشرح المصدر نظير العبارة بأن ﴿أصبحوا﴾ تحتمل معنى صاروا جاثمين وقت الصباح، أو دخلوا في الصباح وهم على تلك الحال؛ فلا يقتضي وجه الصيرورة إلغاء الدلالة على الصباح.","sources":[{"label":"[نظير العبارة في الأعراف: 78] موسوعة التفسير البلاغي، ج13، ص720، تحت «سر استعمال لفظ ﴿فأصبحوا﴾»","url":""}]},{"id":"s7-477","number":477,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿في دارهم﴾ بالإفراد مع أنهم جماعة؟","answer":"أُفردت الدار بمعنى البلد أو جنس المساكن، فوحد المصير مساكن الجماعة كأنها دار واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص48–49، تحت «قصدية التعبير بلفظ الدار مفردًا»","url":""}]},{"id":"s7-478","number":478,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"لماذا صُوّر هلاكهم بقوله: ﴿جاثمين﴾؟","answer":"الجثوم لزوم الأرض بلا حركة؛ فصور أجسادهم ساقطة هامدة بعد قوتهم وتهديدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص49–50، تحت «بلاغة الاستعارة في لفظ ﴿جاثمين﴾»","url":""}]},{"id":"s7-479","number":479,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"ما مناسبة ﴿جاثمين﴾ لتهديدهم شعيبًا بالإخراج من القرية؟","answer":"توعدوا شعيبًا والمؤمنين بإخراجهم من القرية، فانقلب الأمر عليهم؛ صار المهددون أنفسهم جثثًا هامدة في مساكنهم. وتصور ﴿جاثمين﴾ زوال حركتهم وقوتهم بعد ما أظهروه من السلطان والتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص49، تحت «بلاغة الاستعارة في لفظ ﴿جاثمين﴾»","url":""}]},{"id":"s7-480","number":480,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"لماذا أعيد الموصول: ﴿الذين كذبوا شعيبًا﴾ مرتين؟","answer":"تكرار الموصول يثبت الحكمين للفئة نفسها ويشهر سبب مصيرها: تكذيب شعيب، لا عارض آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص54، تحت «نكتة تكرار جملة ﴿الذين كذبوا شعيبًا﴾»","url":""}]},{"id":"s7-482","number":482,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"لماذا شُبّهوا بمن لم يقيموا في الديار: ﴿كأن لم يغنوا فيها﴾؟","answer":"مُحيت آثارهم وانقطع أنسهم بالديار حتى صار حالها كأنهم لم يقيموا فيها يومًا، بعد ادعائهم ملك القرية والتمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص54، تحت «بلاغة التشبيه في الآية»","url":""}]},{"id":"s7-483","number":483,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"كيف يسهم معنى ﴿يغنوا﴾ في تصوير مصير المكذبين؟","answer":"معنى ﴿يغنوا﴾ هنا يقيموا ويعيشوا؛ فنفيه يصور زوالهم عن الديار حتى كأنهم لم يكونوا من أهلها ولم يقيموا فيها. وبه يشتد تصوير انقطاع حياتهم واندثار مقامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص52، تحت «شرح المفردات: ﴿يغنوا﴾»","url":""}]},{"id":"s7-484","number":484,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"ما سر تقديم الموصول في قوله: ﴿الذين كذبوا شعيبًا كانوا هم الخاسرين﴾؟","answer":"تقديم الموصول يقوي الحكم بالخسران عليهم، وتجيء الجملة الاسمية بما يفيد ثبوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص54، تحت «سر تقديم الموصول»","url":""}]},{"id":"s7-1607","number":1607,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"ما دلالة ضمير الفصل في قوله: ﴿كانوا هم الخاسرين﴾؟","answer":"يؤكد ضمير الفصل اختصاص المكذبين بالخسران في مقابل المؤمنين، ردًا على دعواهم أن أتباع شعيب هم الخاسرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص55، تحت «بديع التعبير بضمير الفصل»","url":""}]},{"id":"s7-485","number":485,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"لماذا أُتي بضمير الفصل ﴿هم﴾؟","answer":"ضمير الفصل ﴿هم﴾ يفيد القصر والتوكيد: هم الخاسرون حقًا، لا المؤمنون الذين رموهم بالخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص55، تحت «بديع التعبير بضمير الفصل»","url":""}]},{"id":"s7-486","number":486,"surah":7,"verses":[92],"references":[{"surah":7,"verses":[92]}],"verseLabel":"الأعراف: 92","question":"لماذا خُتمت القصة بـ﴿الخاسرين﴾ بعد أن نسبوا الخسران إلى أتباع شعيب؟","answer":"جاءت الخاتمة ردًا مطابقًا لمقالتهم؛ فقلبت دعواهم وأثبتت أن من فقد نفسه ودياره هو الخاسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص54–55، تحت «نكتة تكرار جملة ﴿الذين كذبوا شعيبًا﴾»","url":""}]},{"id":"s7-487","number":487,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما علة إيثار الفاء في قوله: ﴿فتولى عنهم﴾؟","answer":"تفيد الفاء ترتيب توليه على ما تقدم وتعقيبه له.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص59، تحت «علة إيثار الفاء في مطلع الآية»","url":""}]},{"id":"s7-1608","number":1608,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما وجه المجاز في لفظ التولي في قوله: ﴿فتولى عنهم﴾؟","answer":"يحتمل التولي المفارقة الحسية عقب العقوبة، ويحتمل الإعراض عن نصحهم قبل الرجفة؛ فالتعبير يصور انصرافه عن قوم أعرضوا عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص60، تحت «وجه المجاز في لفظ التولي»","url":""}]},{"id":"s7-489","number":489,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما سرّ تعبير شعيب بالماضي ﴿أبلغتكم﴾، وتعبير نوح بالمضارع ﴿أبلغكم﴾؟","answer":"ورد مضارع نوح ﴿أبلغكم﴾ في سياق عرضه مهمة تبليغ الرسالة واستمرارها، أما ماضي شعيب ﴿أبلغتكم﴾ فورد في ختام قصته لتقرير أنه قد أدى البلاغ. فاختلاف الصيغة يناسب موضع الكلام من عرض الدعوة أو تسجيل تمام أدائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص61–62، تحت «براعة عطف الأفعال، والأسماء»","url":""}]},{"id":"s7-490","number":490,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿رسالات ربي﴾ بالجمع، وقال صالح: ﴿رسالة ربي﴾ بالإفراد؟","answer":"من توجيهات المصدر أن جمع ﴿رسالات﴾ عند شعيب يناسب تعدد ما بلغه من أوامر ونواهٍ، كالتوحيد والوفاء بالكيل والميزان وترك البخس. وأفردت رسالة صالح، على أحد الأوجه، لأن أمر الناقة كان أبرز ما أرسل به إلى قومه؛ ويذكر المصدر للجمع والإفراد توجيهات أخرى أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص62، تحت «علة جمع لفظ ﴿رسالات﴾»","url":""}]},{"id":"s7-491","number":491,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"لماذا أضاف الرب إلى نفسه: ﴿ربي﴾، بينما قال في الآية 89: ﴿ربنا﴾؟","answer":"قال ﴿ربي﴾ في مقام شهادته على أداء رسالته الخاصة، وقال ﴿ربنا﴾ حين جمع نفسه والمؤمنين في الدعاء والتوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص62–63، تحت «توجيه الإضافة في لفظ الرب»","url":""}]},{"id":"s7-492","number":492,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"لماذا عُدّي ﴿نصحت﴾ باللام: ﴿ونصحت لكم﴾؟","answer":"اللام تبين أن نصحه خالص لمنفعتهم ومصلحتهم، لا طلبًا لحظ نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص63، تحت «سر تعدية فعل النصيحة باللام»","url":""}]},{"id":"s7-493","number":493,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿فكيف آسى﴾ بالاستفهام لا «فلا آسى»؟","answer":"الاستفهام إنكاري بمعنى انتفاء الأسى بعد قيام الحجة وإصرارهم على الكفر؛ وكيف يحزن على من اختار سبب هلاكه؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص61، تحت «بلاغة مقابلة الصيغ»","url":""}]},{"id":"s7-494","number":494,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"لماذا صدّر الاستفهام بالفاء: ﴿فكيف آسى﴾؟","answer":"الفاء تفرع انتفاء الأسى على ما قبلها: لقد بلّغ ونصح فكذبوا، فكيف يبقى موضع للحزن عليهم بعد ذلك؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص63، تحت «دلالة الفاء في مطلع الاستفهام»","url":""}]},{"id":"s7-495","number":495,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"لماذا عبّر بالمضارع ﴿آسى﴾ بعد الأفعال الماضية: تولى، أبلغت، نصحت؟","answer":"يناسب المضارع تأكيد عدم تحقق الأسى واستمرار هذا الموقف، بينما سجلت الأفعال الماضية ما تم من البلاغ والنصح. ويجيز المصدر حمل المضارع على حكاية الحال الماضية، فيستحضر موقفه عند إعراضه عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص63–64، تحت «نكتة التعبير عن الأسى بالمضارع»","url":""}]},{"id":"s7-496","number":496,"surah":7,"verses":[93],"references":[{"surah":7,"verses":[93]}],"verseLabel":"الأعراف: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿على قوم كافرين﴾ فنكّر «قومًا» ووصفهم بالكفر؟","answer":"التنكير مع وصف الكفر يذمهم بهذا الوصف ويبين أن سبب عدم الأسى ليس القرابة، بل كونهم قومًا راسخين في الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص64، تحت «علة تنكير القوم ونسبته»","url":""}]},{"id":"s7-497","number":497,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"لماذا انتقل السياق من قصة شعيب إلى قاعدة عامة: ﴿وما أرسلنا في قرية من نبي﴾؟","answer":"بعد عرض نماذج الرسل وأقوامهم انتقل إلى السنة العامة التي تجمعها: الابتلاء بالبأساء والضراء لعل أهل القرى يتضرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص65، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-498","number":498,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿في قرية﴾ لا «إلى قرية»؟","answer":"﴿في قرية﴾ تصور بعثة النبي وقيامه داخل مجتمعها ومخالطته أهلها، لا مجرد توجيه رسالة من خارجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص68–69، تحت «نكتة تعدية فعل الإرسال بـ﴿في﴾»","url":""}]},{"id":"s7-499","number":499,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿من نبي﴾ بزيادة ﴿من﴾؟","answer":"﴿من﴾ زائدة لتوكيد الاستغراق بعد النفي: ما أرسل الله نبيًا واحدًا في قرية إلا جرت سنته المذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص69، تحت «معنى حرف الجر ﴿من﴾»","url":""}]},{"id":"s7-500","number":500,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا أخذنا أهلها﴾ فجاء الاستثناء عقب نفي الإرسال؟","answer":"الاستثناء يبين سنة ملازمة لإرسال الرسل إلى المكذبين: لا يقع إرسال نبي في قرية إلا أعقبته تربية أهلها بالشدة لعلهم يضرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص69–70، تحت «سر التعبير بالاستثناء المفرغ»","url":""}]},{"id":"s7-501","number":501,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما دلالة المجاز في ﴿إلا أخذنا أهلها بالبأساء والضراء﴾؟","answer":"الأخذ هنا مجاز عن التأثير والإصابة؛ أي إصابتهم بالشدة والضر ليظهر افتقارهم ويتذكروا. فتجعل صورة الأخذ أثر الابتلاء واقعًا عليهم متمكنًا منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص69، تحت «بلاغة المجاز في لفظ الأخذ»","url":""}]},{"id":"s7-503","number":503,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما الفرق البياني بين ﴿البأساء﴾ و﴿الضراء﴾؟","answer":"يذكر المصدر من وجوه التفريق أن البأساء مصائب تمس البدن كالأمراض، والضراء ما يصيب الأموال والأنفس من فقر وحاجة، ويذكر توجيهًا آخر للبأساء بالشدة في الأبدان والأموال والأولاد، وللضراء بالآلام والمخاوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص69–70، تحت «سر إتباع البأساء بالضراء»","url":""}]},{"id":"s7-504","number":504,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"لماذا خُتم الابتلاء بقوله: ﴿لعلهم يضرعون﴾؟","answer":"جعل غاية الأخذ أن يتذللوا لله ويرجعوا إليه؛ فالابتلاء تربية وإنذار قبل أن يكون عقوبة استئصال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص70–71، تحت «فائدة التعبير بـ﴿لعل﴾»","url":""}]},{"id":"s7-505","number":505,"surah":7,"verses":[94],"references":[{"surah":7,"verses":[94]}],"verseLabel":"الأعراف: 94","question":"ما دلالة التضرع في ﴿لعلهم يضرعون﴾؟","answer":"التضرع تذلل وتخشع، وهو هنا كناية عن الاعتراف بالذنب والتوبة منه. فالمطلوب أن يحملهم الابتلاء على الانكسار لله والرجوع إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص71، تحت «بلاغة الكناية في لفظ التضرع»","url":""}]},{"id":"s7-506","number":506,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا افتتحت الآية بـ﴿ثم﴾: ﴿ثم بدلنا﴾؟","answer":"تفيد ﴿ثم﴾ التراخي وعدم تعجيل الأخذ، وفيه إمهال لهم وتمكين للاستدراج بالرخاء بعد الشدة. فامتداد المهلة والتبديل كانا فرصة للاعتبار والتضرع، ثم لم ينتفعوا بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص77، تحت «وجه الاستفتاح بـ﴿ثم﴾»","url":""}]},{"id":"s7-507","number":507,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿بدلنا مكان السيئة الحسنة﴾، دون أن يقال: بدلنا السيئة بالحسنة؟","answer":"جعل الحسنة في مكان السيئة يصور إحلال الرخاء محل الشدة إحلالًا تامًا، كأن موضع البلاء نفسه شُغل بالنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص77–78، تحت «إيثار لفظ المكان لجر السيئة بدل الباء»","url":""}]},{"id":"s7-508","number":508,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا سمّى الشدة ﴿السيئة﴾ والرخاء ﴿الحسنة﴾؟","answer":"سميت الشدة سيئة لأنها تسوءهم، والرخاء حسنة لأنه يحسن عندهم ويسرهم؛ فالتسمية بالنظر إلى أثرهما في الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص74–75، تحت «شرح المفردات: ﴿السيئة﴾ و﴿الحسنة﴾»","url":""}]},{"id":"s7-509","number":509,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى عفوا﴾، وما دلالة «عفوا» هنا؟","answer":"﴿عفوا﴾ أي كثروا في العدد والمال ونموا، ومن أصل العفو الزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص75–76، تحت «شرح المفردات: ﴿عفوا﴾»","url":""}]},{"id":"s7-510","number":510,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا جعل كثرتهم ورخاءهم غاية للتبديل بـ﴿حتى﴾؟","answer":"جعل الكثرة غاية لأن الاختبار بالرخاء بلغ مداه عندها؛ وكان المنتظر أن يشكروا، لكنهم غفلوا ونسبوا الأمر إلى العادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص79، تحت «وجه التعريف في ﴿الحسنة﴾ و﴿السيئة﴾»","url":""}]},{"id":"s7-511","number":511,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"ما سرّ تعبيرهم بقولهم: ﴿قد مس آباءنا الضراء والسراء﴾، واختيارهم لفظ ﴿مس﴾؟","answer":"قالوا ﴿مس آباءنا﴾ لأنهم لم ينظروا إلى الضراء والسراء باعتبارهما ابتلاءً مقصودًا؛ حسبوهما أحوالًا تتداولها الأزمنة كما جرت لآبائهم. فاختيار المس في كلامهم يكشف استخفافهم بالعبرة وإعراضهم عنها، ولا يقتضي أن الشدة نفسها كانت خفيفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص79–80، تحت «إيثار التعبير بالمس دون الأخذ»","url":""}]},{"id":"s7-512","number":512,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا قدّموا ﴿الضراء﴾ على ﴿السراء﴾؟","answer":"قدموا الضراء لأنها الأقرب إلى دفع ما أصابهم أولًا من البأساء والضراء، ثم أتبعوها السراء التي جاءت بعد التبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص80، تحت «علة تأخير السراء عن الضراء»","url":""}]},{"id":"s7-513","number":513,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا نسبوا تداول الشدة والرخاء إلى عادة الآباء؟","answer":"زعموا أن الشدة والرخاء عادة تتكرر في الأجيال كما وقعت لآبائهم، فلم يعدوهما تنبيهًا يدعو إلى التوبة والشكر. وبذلك قابلوا نعمة السراء بالغفلة، كما لم ينتفعوا بإنذار الضراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص76–77، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-514","number":514,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"لماذا عُطف ﴿فأخذناهم﴾ بالفاء بعد ﴿عفوا وقالوا﴾؟","answer":"الفاء تفيد أن الأخذ جاء عقب اكتمال الغفلة والقول الباطل؛ فلما لم ينتفعوا بالشدة ولا الرخاء جاء الجزاء سريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص80، تحت «دلالة الفاء المصاحبة للفظ الأخذ»","url":""}]},{"id":"s7-515","number":515,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿بغتة وهم لا يشعرون﴾، فجمع بين المفاجأة ونفي الشعور؟","answer":"﴿بغتة﴾ تثبت وقوع الأخذ فجأة، و﴿وهم لا يشعرون﴾ تصف حالهم المستمرة من الغفلة وعدم توقع العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص80–81، تحت «الإخبار عن البغتة بالمصدر»","url":""}]},{"id":"s7-516","number":516,"surah":7,"verses":[95],"references":[{"surah":7,"verses":[95]}],"verseLabel":"الأعراف: 95","question":"ما الفرق بين خاتمة ﴿لا يشعرون﴾ هنا و﴿وهم نائمون﴾ و﴿وهم يلعبون﴾ بعدها؟","answer":"﴿لا يشعرون﴾ أعم في نفي إدراك مقدمات العذاب، و﴿نائمون﴾ يصور غفلة الليل وعجزه، و﴿يلعبون﴾ يصور غفلة النهار مع الانشغال باللهو.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص81، تحت «بديع التعبير بالجملة الاسمية»","url":""}]},{"id":"s7-517","number":517,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"ما دلالة ﴿القرى﴾ في ﴿ولو أن أهل القرى آمنوا واتقوا﴾ بعد ﴿وما أرسلنا في قرية من نبي﴾؟","answer":"على حمل التعريف على العهد، ترجع القرى إلى القرى المهلكة المشار إليها من قبل؛ فإن ﴿قرية﴾ السابقة نكرة في سياق النفي فتفيد العموم. ويحتمل التعريف الجنس فيشمل أهل القرى أينما كانوا، ويذكر المصدر أيضًا احتمال الإشارة إلى مكة وما حولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص89، تحت «دلالة تعريف الألف واللام»","url":""}]},{"id":"s7-518","number":518,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا اقترنت ﴿لو﴾ بـ﴿أن﴾: ﴿ولو أن أهل القرى آمنوا﴾؟","answer":"تؤكد ﴿أن﴾ مضمون الشرط، ويؤول ما دخلت عليه بمصدر؛ أي لو حصل إيمان أهل القرى وتقواهم. فيعلق فتح البركات على تحقق هذا الإيمان، مع ما في التركيب من تقرير الصلة بين الشرط وجوابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص88، تحت «دلالة اقتران الشرط بـ﴿أن﴾»","url":""}]},{"id":"s7-519","number":519,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا أضيف ﴿أهل﴾ إلى ﴿القرى﴾ بدل أن يقال: ولو أن القرى آمنت؟","answer":"تجعل الإضافة الحكم شاملًا لسكان القرى الذين أرسلت إليهم الرسل، فتسجل حالهم من الإيمان أو الكفر. وفي التعبير تعريض بمن كذبوا من المخاطبين، وبشارة لأهل القرى الذين يؤمنون، بحسب ما يبينه السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص88، تحت «نكتة إضافة ﴿أهل﴾ إلى ﴿القرى﴾»","url":""}]},{"id":"s7-520","number":520,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا جمع بين الإيمان والتقوى؟","answer":"الإيمان تصديق القلب وأصل الاستجابة، والتقوى امتثال عملي وترك للمعصية؛ فلا تتم أسباب البركة بأحدهما دون الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص89، تحت «سر العطف في الآية»","url":""}]},{"id":"s7-521","number":521,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا عُطف ﴿واتقوا﴾ على ﴿آمنوا﴾ بالواو؟","answer":"الواو تجمع الشرطين من غير جعل أحدهما بدل الآخر؛ فالمطلوب اجتماع الإيمان والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص89، تحت «سر العطف في الآية»","url":""}]},{"id":"s7-522","number":522,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿لفتحنا عليهم بركات﴾، فاستعار الفتح للبركات؟","answer":"صُورت البركات كخزائن مغلقة يفتحها الله فتفيض؛ وفي الفتح معنى السعة بعد المنع وتتابع الخيرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص89–90، تحت «دلالة الاستعارة في لفظ الفتح»","url":""}]},{"id":"s7-523","number":523,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا عُدّي الفتح بـ﴿على﴾: ﴿لفتحنا عليهم﴾؟","answer":"﴿على﴾ تصور البركات نازلةً عليهم من فوق ومحيطةً بهم، وفيها إيحاء بالفيض والشمول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص91، تحت «توجيه تعدي الفتح بـ﴿على﴾»","url":""}]},{"id":"s7-524","number":524,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا جمع ﴿بركات﴾ ونكّرها؟","answer":"جُمعت لتعدد أنواعها في الدين والدنيا، ونُكرت للتعظيم والتكثير: بركات كثيرة واسعة لا يحيط بها العد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص91–92، تحت «فائدة تنكير البركات وجمعها»","url":""}]},{"id":"s7-525","number":525,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿من السماء والأرض﴾ فجمع جهتي العلو والسفل؟","answer":"جمع الجهتين يوسع صورة العطاء، فيدل على خير يأتيهم من كل جهة؛ ومن أبرز أمثلته المطر من السماء والنبات من الأرض. فالتعبير لا يقصر البركات على نوع واحد، بل يصور سعة الفضل مع الإيمان والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص90–91، تحت «سر إطلاق فعل الفتح دون قيد»","url":""}]},{"id":"s7-526","number":526,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"ما دلالة الاستدراك بـ﴿ولكن كذبوا﴾ بعد الوعد بفتح البركات؟","answer":"يقابل الاستدراك بين ما كان يترتب على إيمانهم وبين ما وقع منهم فعلًا؛ فقد كذبوا، فلم يتحقق شرط فتح البركات، وجاء أخذهم نتيجة لتكذيبهم وما كسبوه من الذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص92، تحت «بلاغة الاستثناء بـ﴿ولكن﴾»","url":""}]},{"id":"s7-527","number":527,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"لماذا قابل ﴿لفتحنا عليهم﴾ بـ﴿فأخذناهم﴾؟","answer":"قابل الفتح بالأخذ: الإيمان يطلق أبواب الخير، والتكذيب يجعلهم في قبضة العقاب؛ فالصورتان متضادتان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص92–93، تحت «إيثار فعل الأخذ»","url":""}]},{"id":"s7-528","number":528,"surah":7,"verses":[96],"references":[{"surah":7,"verses":[96]}],"verseLabel":"الأعراف: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كانوا يكسبون﴾ لا «بما كسبوا»؟","answer":"﴿كانوا يكسبون﴾ يدل على تكرر الذنوب واستمرار اتخاذها كسبًا وعادة، لا على فعل ماض منفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص92–93، تحت «توجيه اقتران الماضي بالمضارع»","url":""}]},{"id":"s7-529","number":529,"surah":7,"verses":[97,98],"references":[{"surah":7,"verses":[97,98]}],"verseLabel":"الأعراف: 97–98","question":"لماذا تكرر الاستفهام: ﴿أفأمن أهل القرى﴾ ثم ﴿أوأمن أهل القرى﴾؟","answer":"كرر الاستفهام ليحيط بزمني الغفلة: الليل والنهار؛ فلا يأمن أهل القرى بأس الله في أي حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص99، تحت «بلاغة الإطناب في الآيات»","url":""}]},{"id":"s7-530","number":530,"surah":7,"verses":[97],"references":[{"surah":7,"verses":[97]}],"verseLabel":"الأعراف: 97","question":"لماذا دخلت الفاء بين همزة الاستفهام و﴿أمن﴾: ﴿أفأمن﴾؟","answer":"الفاء تعطف الإنكار على ما سبق من أخذ المكذبين؛ أفبعد هذه السنن والوقائع أمن اللاحقون؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص97، تحت «دلالة حرف الفاء»","url":""}]},{"id":"s7-531","number":531,"surah":7,"verses":[97],"references":[{"surah":7,"verses":[97]}],"verseLabel":"الأعراف: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يأتيهم بأسنا﴾ فجعل البأس آتيًا؟","answer":"صُور البأس كقادم يتحرك نحوهم، فيفاجئهم من حيث لا يملكون دفعه، وفي ذلك تشخيص للوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص99، تحت «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s7-532","number":532,"surah":7,"verses":[97],"references":[{"surah":7,"verses":[97]}],"verseLabel":"الأعراف: 97","question":"لماذا اختير ﴿بياتًا﴾ لا «ليلًا»؟","answer":"البيات يدل هنا على إتيان العذاب ليلًا، في وقت المبيت والدعة والأمن. وإذا حمل البأس على صورة بأس الحرب، أوحى البيات بمباغتة العدو في وقت غفلته؛ فتقوى صورة الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص95، تحت «شرح المفردات: ﴿بياتًا﴾»","url":""}]},{"id":"s7-533","number":533,"surah":7,"verses":[97],"references":[{"surah":7,"verses":[97]}],"verseLabel":"الأعراف: 97","question":"لماذا خُتمت بـ﴿وهم نائمون﴾ مع أن «بياتًا» يدل على الليل؟","answer":"ذكر النوم بعد البيات لتصوير تمام الغفلة والعجز عند مجيء العذاب، لا لمجرد تحديد الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص98–99، تحت «بلاغة حالية الفاصلة»","url":""}]},{"id":"s7-534","number":534,"surah":7,"verses":[98],"references":[{"surah":7,"verses":[98]}],"verseLabel":"الأعراف: 98","question":"لماذا عطف الاحتمال الثاني بـ﴿أو﴾: ﴿أوأمن أهل القرى﴾؟","answer":"على قراءة ﴿أو﴾ بالسكون، يعطف السياق أحد الحالين على الآخر: مجيء العذاب ليلًا أو نهارًا، فينكر أمنهم في أي منهما. ويذكر المصدر أيضًا القراءة بواو العطف مع همزة الاستفهام، وفيها إنكار الأمن من الحالين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص102–103، تحت «توجيه قراءة العطف بـ﴿أو﴾»","url":""}]},{"id":"s7-535","number":535,"surah":7,"verses":[98],"references":[{"surah":7,"verses":[98]}],"verseLabel":"الأعراف: 98","question":"لماذا كرر ﴿أهل القرى﴾ ولم يضمرهم؟","answer":"أعيد الاسم الظاهر لإبلاغ الوعيد وتجديد التوبيخ والتعظيم والتهويل. وتكرار ﴿أهل القرى﴾ يسترعي الأسماع إلى الحكم عليهم، ويناسب تفصيل وجهي مجيء البأس في الليل والنهار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص102–103، تحت «بلاغة التكرار في الآية»","url":""}]},{"id":"s7-536","number":536,"surah":7,"verses":[98],"references":[{"surah":7,"verses":[98]}],"verseLabel":"الأعراف: 98","question":"لماذا قابل ﴿بياتًا﴾ بـ﴿ضحى﴾ لا بـ«نهارًا»؟","answer":"الضحى وقت ارتفاع النهار وانتشار الحركة والاطمئنان، فقابل البيات لا بمجرد النهار بل بوقت الغفلة في النشاط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص104–105، تحت «بلاغة الطباق في الآية»","url":""}]},{"id":"s7-537","number":537,"surah":7,"verses":[98],"references":[{"surah":7,"verses":[98]}],"verseLabel":"الأعراف: 98","question":"لماذا خُتمت بـ﴿وهم يلعبون﴾ لا «وهم مستيقظون»؟","answer":"﴿يلعبون﴾ يذم حالهم؛ فهم مستيقظون قادرون على الاعتبار لكنهم مشتغلون بما لا ينفع، وهذا أشد من مجرد اليقظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص104، تحت «جملة الفاصلة بين المجاز والاستعارة»","url":""}]},{"id":"s7-538","number":538,"surah":7,"verses":[98],"references":[{"surah":7,"verses":[98]}],"verseLabel":"الأعراف: 98","question":"ما سر المقابلة بين ﴿وهم نائمون﴾ و﴿وهم يلعبون﴾؟","answer":"المقابلة تستوعب غفلتين: غفلة اضطرارية بالنوم ليلًا، وغفلة اختيارية باللهو نهارًا؛ فلا زمان يمنع بأس الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص104–105، تحت «سر التعبير باسم الفاعل، والفعل المضارع»","url":""}]},{"id":"s7-539","number":539,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿أفأمنوا مكر الله﴾ بعد تكرار ﴿أفأمن أهل القرى﴾؟","answer":"بعد إنكار أمنهم مجيء البأس في الليل والنهار جمع ذلك كله في إنكار أصل الأمن من تدبير الله الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص108–109، تحت «التعبير بـ﴿أفأمنوا مكر الله﴾ دون غيرها»","url":""}]},{"id":"s7-540","number":540,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"لماذا سُمّي أخذ الله لهم ﴿مكر الله﴾؟","answer":"يصور التعبير استدراجهم بالإمهال والنعمة، ثم مجيء العقوبة من حيث لا يتوقعون، كحال من يستدرج عدوه حتى يقع في قبضته. فالمراد هنا تدبير العقوبة والجزاء العادل، لا الظلم أو الغدر المذموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص106–107، تحت «شرح المفردات: ﴿مكر﴾»","url":""}]},{"id":"s7-541","number":541,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"لماذا كرر ﴿مكر الله﴾ ظاهرًا في الجملتين ولم يقل: فلا يأمنه؟","answer":"أعيد ﴿مكر الله﴾ لتحقيق الوعيد وتأكيده، وإثارة العظة وتفخيم المهابة. وفي إعادة الاسم الظاهر ترسيخ لعظم قدرة الله على إصابة من يشاء بما يشاء، فلا مانع لحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص109–110، تحت «نكتة تكرار لفظ المكر»","url":""}]},{"id":"s7-542","number":542,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"لماذا عبّر بالفعل أولًا ﴿أفأمنوا﴾ ثم بالمضارع ﴿فلا يأمن﴾؟","answer":"الماضي ﴿أفأمنوا﴾ ينكر وقوع الأمن منهم، والمضارع ﴿لا يأمن﴾ يقرر قاعدة مستمرة لكل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص110–111، تحت «براعة نفي المضارع بـ﴿لا﴾»","url":""}]},{"id":"s7-543","number":543,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"لماذا جاءت الفاء في ﴿فلا يأمن مكر الله﴾؟","answer":"الفاء تفريع للقاعدة على الإنكار السابق: لما كان أمنهم باطلًا ثبت أن من يأمن هذا الأمن من الخاسرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص110، تحت «بلاغة التذييل في المختتم»","url":""}]},{"id":"s7-544","number":544,"surah":7,"verses":[99],"references":[{"surah":7,"verses":[99]}],"verseLabel":"الأعراف: 99","question":"لماذا قصر الأمن من مكر الله على ﴿القوم الخاسرون﴾؟","answer":"حصر الأمن في الخاسرين لأنه يفضي إلى ترك الحذر والتوبة حتى يفجأ العذاب؛ فلا يصدر إلا عمن خسر بصيرته وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص110–111، تحت «فائدة الاستثناء المفرغ»","url":""}]},{"id":"s7-545","number":545,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لم قيل ﴿أولم يهد للذين يرثون الأرض﴾ باللام، مع أن الهداية قد تتعدى بـ«إلى»؟","answer":"تدل اللام على اختصاص هؤلاء بالبيان والإرشاد الذي كان ينبغي أن ينتفعوا به. ويذكر المصدر تضمين ﴿يهد﴾ معنى يبين؛ فالمعنى: ألم يتبين لهم من مصائر من سبقهم ما يرشدهم إلى الاعتبار؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص116–117، تحت «نكتة تعدية الفعل ﴿يهدي﴾ باللام»","url":""}]},{"id":"s7-546","number":546,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لماذا وصف اللاحقين بأنهم ﴿يرثون الأرض﴾؟","answer":"وصفهم بالوراثة لأنهم سكنوا أرض من هلك قبلهم وانتقلت إليهم من غيرهم، فكان في ذلك نعمة وعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص117، تحت «لفظ الإرث بين الحقيقة والمجاز»","url":""}]},{"id":"s7-547","number":547,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"أي أرض يستحضرها قوله ﴿يرثون الأرض من بعد أهلها﴾؟","answer":"تستحضر ﴿الأرض﴾ أرض الأقوام الذين مضوا ومنازلهم وقراهم؛ فبقاء اللاحقين فيها بعد زوال أهلها شاهد يدعوهم إلى الاعتبار. ويحتمل التعريف الجنس، فيعم من يخلف أمة في أرضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص117، تحت «دلالة الألف واللام في لفظ ﴿الأرض﴾»","url":""}]},{"id":"s7-548","number":548,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لماذا جاء التركيب ﴿أن لو نشاء﴾؟","answer":"﴿أن﴾ هنا مخففة من الثقيلة، واسمها ضمير شأن مقدر، وهي تؤكد مضمون الخبر. ثم يبين الشرط أن إصابتهم بذنوبهم تحت مشيئة الله؛ أي ينبغي أن يتضح لهم أنه لو شاء أصابهم كما أصاب من قبلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص117–118، تحت «نكتة التعبير بالمصدر المنسبك؛ دلالة فعل الشرط على الماضي»","url":""}]},{"id":"s7-549","number":549,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿أصبناهم بذنوبهم﴾ لا «عذبناهم»؟","answer":"الإصابة هنا بمعنى الإهلاك؛ فتصور حلول الجزاء بهم وتمكن أثره فيهم، والباء في ﴿بذنوبهم﴾ تبين سببه. ويذكر المصدر أيضًا توجيهًا على تقدير: أصبنا أمثالهم، تنبيهًا لهم بمصير من سبقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص120، تحت «بلاغة المجاز في لفظ الإصابة»","url":""}]},{"id":"s7-550","number":550,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"ما دلالة الباء في ﴿بذنوبهم﴾؟","answer":"الباء سببية: أصبناهم بسبب ذنوبهم؛ فلا يقع الأخذ اعتباطًا ولا ظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص118، تحت «دلالة الباء في لفظ ﴿بذنوبهم﴾»","url":""}]},{"id":"s7-551","number":551,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لماذا عدل من الشرط ﴿لو نشاء أصبناهم﴾ إلى المضارع ﴿ونطبع﴾؟","answer":"من توجيهات المصدر أن ﴿ونطبع﴾ استئناف يخبر باستمرار الطبع وتجدد أثره، بعد ذكر الإصابة في جواب الشرط بصيغة الماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص118–119، تحت «دلالة الاستئناف بالمضارع»","url":""}]},{"id":"s7-552","number":552,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿نطبع على قلوبهم﴾، فجعل القلوب موضع الختم؟","answer":"الطبع ختم يمنع نفوذ الحق، وجعل محله القلوب لأنها موضع الإدراك والقبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص121–122، تحت «بلاغة الاستعارة في لفظ الطبع»","url":""}]},{"id":"s7-553","number":553,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لماذا فرّع على طبع القلوب قوله: ﴿فهم لا يسمعون﴾؟","answer":"الفاء تجعل عدم سماع الحق نتيجة للطبع؛ فالمختوم على قلبه يسمع الصوت لكنه لا يسمع سماع قبول وانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص121، تحت «سر وصل جملة ﴿فهم لا يسمعون﴾»","url":""}]},{"id":"s7-554","number":554,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]}],"verseLabel":"الأعراف: 100","question":"لماذا نفى السماع لا الفهم أو الإيمان؟","answer":"لأن المنفي سماع القبول والانتفاع بالمواعظ، لا مجرد إدراك الأصوات؛ فاختيار السمع يصور انغلاق طريق التلقي الذي يقيم الحجة ويدعو إلى الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص121–122، تحت «علة إيثار لفظ السمع على العقل»","url":""}]},{"id":"s7-555","number":555,"surah":7,"verses":[100],"references":[{"surah":7,"verses":[100]},{"surah":9,"verses":[87]},{"surah":63,"verses":[3]}],"verseLabel":"الأعراف: 100؛ التوبة: 87؛ المنافقون: 3","question":"ما سرّ اختلاف الخاتمة بعد الطبع على القلوب: ﴿فهم لا يسمعون﴾ في الأعراف، و﴿فهم لا يفقهون﴾ في التوبة والمنافقون؟","answer":"في الأعراف يجيء نفي السماع بعد ذكر الإصابة بالذنوب والطبع على القلوب، فيصور انقطاع سماع القول الحق والانتفاع به. وفي التوبة يتصل نفي الفقه برضاهم بالقعود وترك صحبة الرسول والجهاد، فلم يدركوا ما فاتهم من الخير. وفي المنافقون جاء بعد إيمانهم ثم كفرهم، فصور فقد إدراك حقائق الإيمان والتمييز النافع؛ وتلتقي المواضع في أثر الإعراض مع اختلاف ما يبرزه السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص18، تحت «الغرض من التعبير بالجملة الاسمية ﴿فهم لا يفقهون﴾»","url":""}]},{"id":"s7-556","number":556,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿تلك القرى﴾ باسم الإشارة للبعيد؟","answer":"يشير البعد إلى عظم شأن القرى المذكورة ومصائرها، فيدعو إلى التعجب والاعتبار بما حل بها. ويذكر المصدر وجهًا آخر هو أن البعد يوقع التعظيم في نفس السامع، فتكون الإشارة إلى حال أهلها في قوتهم ومكانتهم ثم هلاكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص127–128، تحت «التعبير بـ﴿تلك﴾ دون غيرها»","url":""}]},{"id":"s7-557","number":557,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما أثر افتتاح الكلام بـ﴿تلك القرى﴾ قبل قوله ﴿نقص عليك من أنبائها﴾؟","answer":"يعين افتتاح الكلام القرى المذكورة ويستحضرها في ذهن السامع قبل الحديث عن أنبائها. وعلى جعل ﴿القرى﴾ خبرًا لـ﴿تلك﴾، يكون في الإخبار بالاسم تعظيم لشأنها والتنبيه إلى ما في هلاكها من العظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص128، تحت «بلاغة الإخبار بالاسم والفعل»","url":""}]},{"id":"s7-558","number":558,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"لماذا عبّر بالمضارع ﴿نقص عليك﴾ عن قصص وقع في الماضي؟","answer":"يذكر المصدر أن المضارع يعبر عن القص الذي سبق، مع وعد بزيادة القصص فيما يأتي؛ ففيه دلالة على تجدد عرض الأنباء واستمراره للموعظة والتخويف، لا مجرد تسجيل رواية انتهت.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص128–129، تحت «علة التعبير عن القص بالمضارع»","url":""}]},{"id":"s7-559","number":559,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما الذي تضيفه جملة ﴿نقص عليك من أنبائها﴾ إلى عرض مصائر القرى؟","answer":"فيها امتنان على النبي بإطلاعه على أنبائها وتثبيت له، كما يستدل بهذه المعرفة على نبوته؛ إذ أعلمه الله من أخبار الأمم ما لم يسبق له علم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص128، تحت «دلالة الحالية في جملة القص»","url":""}]},{"id":"s7-560","number":560,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما الذي تفيده ﴿من﴾ في ﴿نقص عليك من أنبائها﴾؟","answer":"﴿من﴾ للتبعيض؛ فما قصه القرآن من أنبائها هو القدر المختار للعبرة، لا جميع تفاصيل تاريخها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص129–130، تحت «دلالة حرف الجر ﴿من﴾»","url":""}]},{"id":"s7-561","number":561,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد جاءتهم رسلهم﴾ مع أن الجملة تفسر أنباء القرى؟","answer":"الجملة تبين أهم أنبائها وتؤكد باللام وقد أن الرسل بلغوهم فعلًا، فلا عذر لهم في التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص129، تحت «بيان وجه العطف بجملة ﴿ولقد جاءتهم﴾»","url":""}]},{"id":"s7-562","number":562,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"لم قيل ﴿جاءتهم رسلهم﴾ بضمير الجماعة بعد ذكر ﴿تلك القرى﴾؟","answer":"عاد الضمير على أهل القرى، فهم الذين جاءتهم الرسل وخوطبوا بالبينات. فالكلام ينتقل من ذكر القرى إلى بيان حال سكانها، وهو المقصود من أخبارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص130، تحت «دلالة الضمير ومغزى تأنيثه»","url":""}]},{"id":"s7-563","number":563,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"لماذا جمع ﴿البينات﴾؟","answer":"جُمعت لتعدد الحجج والمعجزات والدلائل التي جاء بها الرسل، فلم يكن التكذيب بعد بينة واحدة خفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص130، تحت «توجيه تعريف البينات وجمعها»","url":""}]},{"id":"s7-564","number":564,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿فما كانوا ليؤمنوا﴾ بدل «فلم يؤمنوا»؟","answer":"اللام في ﴿ليؤمنوا﴾ لام الجحود بعد ﴿ما كان﴾؛ فالتعبير ينفي صلاحية الإيمان ووقوعه منهم بعد رسوخ التكذيب، وهو أبلغ من مجرد ﴿لم يؤمنوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص131، تحت «بلاغة التعبير بجملة ﴿فما كانوا ليؤمنوا﴾»","url":""}]},{"id":"s7-565","number":565,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿بما كذبوا من قبل﴾، وما المراد بـ«من قبل»؟","answer":"أي لم يكونوا ليصدقوا عند مجيء الرسل بما سبق أن كذبوا به حين أخذ عليهم الميثاق أو عند أول مجيء البينات؛ فالتكذيب السابق أورث الإصرار اللاحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص132، تحت «سر التعبير بالجار ﴿من قبل﴾»","url":""}]},{"id":"s7-566","number":566,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"لماذا خُتمت بـ﴿كذلك يطبع الله على قلوب الكافرين﴾ بعد قوله قبلها: ﴿ونطبع على قلوبهم﴾؟","answer":"الخاتمة تحول أخبار القرى إلى سنة عامة: مثل ذلك الطبع الناشئ عن الإصرار يطبع الله على قلوب كل كافر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص133–134، تحت «التعبير بـ﴿يطبع الله﴾ دون غيره»","url":""}]},{"id":"s7-567","number":567,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"لماذا أظهر اسم الله في ﴿يطبع الله﴾ بعد ضمير التعظيم ﴿نطبع﴾؟","answer":"في الانتقال من ﴿ونطبع﴾ إلى ﴿يطبع الله﴾ إظهار للاسم الجليل يزيد التهويل والوعيد، ويقرر أن الحكم صادر عن الله. ويلفت السامع إلى شمول سنة الجزاء للمكذبين بعد عرض مصائر القرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص134–135، تحت «بلاغة الالتفات من المتكلم إلى الغائب»","url":""}]},{"id":"s7-568","number":568,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الأعراف: ﴿كذلك يطبع الله﴾ بالاسم الظاهر، وقوله تعالى في يونس في القصة النظيرة: ﴿كذلك نطبع﴾ بنون العظمة؟","answer":"سبق في يونس إسناد النجاة والبعث إلى ضمير العظمة، مثل ﴿فنجيناه﴾ و﴿بعثنا﴾، فجاء ﴿كذلك نطبع﴾ موافقًا له. أما الأعراف فسبق فيها ﴿ولقد جاءتهم رسلهم بالبينات﴾، فناسب الإظهار أن يقال ﴿كذلك يطبع الله﴾؛ إذ لم يجر المقطع على ضمير المتكلم في الإحسان السابق كما في يونس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص133–134، تحت «التعبير بـ﴿يطبع الله﴾ دون غيره»","url":""}]},{"id":"s7-569","number":569,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿بما كذبوا من قبل﴾، وفي يونس: ﴿بما كذبوا به﴾؟","answer":"سبق في الأعراف التصريح بالإيمان بالذي أرسل به النبي، فحذف ﴿به﴾ من ﴿بما كذبوا من قبل﴾ للإيجاز اعتمادًا على ما تقدم ودفعًا للتكرار. أما يونس فلم يسبق في موضع المقارنة ما يقوم مقامه، فذكر ﴿به﴾ لربط الصلة بالموصول. ويذكر المصدر للأعراف أيضًا وجهًا في سعة التكذيب وعدم تقييده بمتعلق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص132–133، تحت «توجيه المتشابه اللفظي في تعدية فعل التكذيب»","url":""}]},{"id":"s7-570","number":570,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"ما سر تأكيد استغراق النفي في قوله: ﴿وما وجدنا لأكثرهم من عهد﴾؟","answer":"تؤكد ﴿من﴾ استغراق النفي، فلا يفيد التعبير مجرد إخلال عارض بالعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص140، تحت «سر تأكيد الاستغراق»","url":""}]},{"id":"s7-1609","number":1609,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"ما وجه البلاغة في نفي الوجدان بقوله: ﴿وما وجدنا﴾؟","answer":"نفي الوجدان كناية عن انتفاء الوفاء بالعهد؛ فما ثبت وجوده ظهر أثره، فلما انتفى الوفاء عُبر عنه بأنه لم يوجد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص142–143، تحت «بلاغة الكناية في نفي الوجدان»","url":""}]},{"id":"s7-571","number":571,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿لأكثرهم﴾ ولم يعمم الحكم على الجميع؟","answer":"قال ﴿لأكثرهم﴾ إنصافًا؛ إذ بقي من وفى بالعهد وآمن، فلا يعمم الذم على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص141–142، تحت «علة التعبير بالأكثر دون غيره»","url":""}]},{"id":"s7-572","number":572,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"لماذا زيدت ﴿من﴾ في ﴿من عهد﴾؟","answer":"﴿من﴾ زائدة في سياق النفي لتوكيده واستغراق جنس العهد: لم يوجد لأكثرهم شيء من الوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص143، تحت «وجه تعريف العهد»","url":""}]},{"id":"s7-573","number":573,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"ما المراد بـ﴿عهد﴾ هنا: الوصية الفطرية أم الوفاء بما عاهدوا عليه؟","answer":"يشمل عهد الفطرة والتوحيد وما أخذه الله عليهم، كما يشمل وفاءهم بما عاهدوا الرسل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص138–139، تحت «شرح المفردات: ﴿عهد﴾»","url":""}]},{"id":"s7-574","number":574,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"لماذا قابل النفي بـ﴿وإن وجدنا أكثرهم لفاسقين﴾؟","answer":"قابل عدم وجدان العهد بإثبات الفسق ليبين أن السبب خروجهم المتكرر عن الطاعة، لا خفاء الحق عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص144–145، تحت «بلاغة التعبير بـ﴿وما وجدنا لأكثرهم﴾ ﴿وإن وجدنا أكثرهم﴾»","url":""}]},{"id":"s7-575","number":575,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"لماذا اختلف معنى ﴿وجدنا﴾ في الموضعين المتجاورين؟","answer":"الأول بمعنى ألفينا: لم يوجد لأكثرهم وفاء بالعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص144، تحت «بلاغة التعبير بـ﴿وما وجدنا لأكثرهم﴾ ﴿وإن وجدنا أكثرهم﴾»","url":""}]},{"id":"s7-576","number":576,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"لماذا أكد الخبر بـ﴿إن﴾ واللام: ﴿وإن وجدنا أكثرهم لفاسقين﴾؟","answer":"على الوجه الذي تكون فيه ﴿إن﴾ مخففة من الثقيلة، تؤكد الجملة علم الله بحالهم، وتأتي اللام فارقة بينها وبين النافية. وفي اجتماع التقرير والتوكيد تسجيل لرسوخ خروج أكثرهم عن الطاعة، لا مجرد وصف عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص143–144، تحت «دلالة الخبر في جملة الوجدان»","url":""}]},{"id":"s7-577","number":577,"surah":7,"verses":[102],"references":[{"surah":7,"verses":[102]}],"verseLabel":"الأعراف: 102","question":"لماذا اختيرت خاتمة ﴿لفاسقين﴾ بعد الحديث عن العهد؟","answer":"الفسق خروج عن الطاعة والعهد؛ فناسب ختام الآية التي نفت الوفاء وأثبتت النقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص144–145، تحت «بلاغة التعبير بـ﴿وما وجدنا لأكثرهم﴾ ﴿وإن وجدنا أكثرهم﴾»","url":""}]},{"id":"s7-578","number":578,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"لماذا بدأت قصة موسى بـ﴿ثم بعثنا﴾ مع أن بعث الرسل متعاقب؟","answer":"تفيد ﴿ثم﴾ مهلة بين بعثة موسى ومن سبقه، ويلائم ذلك انتقال السياق إلى قصة ذات شأن بعد تلك القصص. ويذكر المصدر أن مهلة التراخي الرتبي ملازمة هنا، ولو اختلف مقدار الفاصل الزمني بين موسى وبعض السابقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص151، تحت «دلالة العطف بـ﴿ثم﴾»","url":""}]},{"id":"s7-579","number":579,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعدهم﴾، وإلى من يعود الضمير؟","answer":"يعود إلى الرسل المذكورين أو إلى الأمم والقرى المتقدمة؛ أي بعد أولئك السابقين بعث الله موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص151، تحت «توجيه عود الضمير ﴿هم﴾»","url":""}]},{"id":"s7-580","number":580,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"لماذا قدّم ﴿من بعدهم﴾ على ﴿موسى﴾؟","answer":"قدم ﴿من بعدهم﴾ للاعتناء بتأخر هذه البعثة عن السابقين، ولتشويق السامع إلى الرسول الذي سيذكر بعدها. فيتصل الخبر بما سبقه قبل أن يصرح باسم موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص151، تحت «نكتة تقديم شبه الجملة»","url":""}]},{"id":"s7-581","number":581,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿بعثنا... موسى﴾، دون أن يقال: أرسلنا موسى؟","answer":"البعث نوع من الإرسال يتضمن الإنهاض والإثارة لمهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص150–151، تحت «متشابه التعبير عن لفظي الإرسال والبعث حذفًا وذكرًا»","url":""}]},{"id":"s7-582","number":582,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿بآياتنا﴾ قبل ذكر الجهة المبعوث إليها؟","answer":"تقديم ﴿بآياتنا﴾ يبرز عدة موسى وحجته قبل ذكر الخصم؛ فهو مبعوث مؤيد بالآيات لا داخل المواجهة بقوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص152، تحت «سر تقديم الآيات»","url":""}]},{"id":"s7-583","number":583,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما دلالة الباء في ﴿بآياتنا﴾؟","answer":"تفيد الملابسة والمصاحبة؛ أي بعث موسى ملتبسًا بآيات الله ومؤيدًا بها. ويجعل المصدر ﴿بآياتنا﴾ متعلقًا بحال من موسى، أو بوصف لمصدر البعث، فيبرز اقتران الرسالة بدليلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص151–152، تحت «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s7-584","number":584,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى فرعون وملئه﴾ لا «إلى فرعون وقومه»؟","answer":"خُص فرعون وملؤه لأنهم مركز السلطة والتدبير وقادة التكذيب، ومن ورائهم يتبع عامة القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص152، تحت «علة إيثار لفظ الملأ»","url":""}]},{"id":"s7-585","number":585,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"لم انتقل السياق من ﴿بعثنا... بآياتنا﴾ إلى ﴿فظلموا بها﴾ دون تفصيل جميع الآيات هنا؟","answer":"أجمل الآيات في هذا الموضع وأوجز القصة؛ فالتقدير أنه جاءهم بها فكفروا، ثم تأتي تفاصيل المواجهة بعد ذلك. فيهيئ الإجمال السامع للعبرة من عاقبتهم قبل عرض مشاهد القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص151–152، تحت «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s7-586","number":586,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فظلموا بها﴾، فعُدّي الظلم بالباء؟","answer":"ضمن ﴿ظلموا﴾ معنى كفروا أو كذبوا، فعدي بالباء ليدل على جحودهم الآيات مع ما فيه من ظلم بوضعها موضع الإنكار. ويذكر المصدر وجهًا آخر يجعل الباء سببية؛ أي ظلموا بسبب موقفهم من الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص152–153، تحت «بلاغة التضمين في قوله: ﴿فظلموا بها﴾»","url":""}]},{"id":"s7-587","number":587,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"لماذا حُذف مفعول ﴿ظلموا﴾؟","answer":"حذف المفعول ليعم ظلمهم أنفسهم وموسى وقومه والحق، فلا يحصر فسادهم في جهة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص152–153، تحت «بلاغة التضمين في قوله: ﴿فظلموا بها﴾»","url":""}]},{"id":"s7-588","number":588,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فانظر﴾ بالفاء مباشرة بعد ظلمهم؟","answer":"تفرع الفاء الأمر بالنظر على ما أجمل من كفرهم وظلمهم، مع إيجاز ما ترتب عليه من الهلاك؛ كأنه قيل: فكفروا فجرى عليهم ما جرى، فانظر عاقبتهم. وهي دعوة إلى نظر الاعتبار في سبب الهلاك ونتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص153–154، تحت «دلالة الفاء في لفظ النظر»","url":""}]},{"id":"s7-589","number":589,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف كان عاقبة المفسدين﴾ لا «ما عاقبتهم»؟","answer":"الاستفهام بـ﴿كيف﴾ يلفت إلى هيئة العاقبة وفظاعتها لا إلى مجرد حصولها، فيستدعي نظرًا واعتبارًا أعمق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص154، تحت «سر التعبير بـ﴿كيف﴾»","url":""}]},{"id":"s7-590","number":590,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"لماذا سمّاهم ﴿المفسدين﴾ بعد وصف فعلهم بالظلم؟","answer":"في وصفهم بالمفسدين بيان أن الكفر والظلم اللذين ارتكبوهما سبب سوء العاقبة، وأن الظلم يستلزم الإفساد. ويبرز المصدر فساد الاعتقاد والقلب الذي ينشأ عنه فساد الأعمال؛ فالإظهار يربط المصير بالوصف الذي استحقوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص154–155، تحت «علة إيثار لفظ المفسدين وإظهاره»","url":""}]},{"id":"s7-591","number":591,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"ما سرّ نداء موسى فرعون باسمه السلطاني: ﴿يا فرعون﴾؟","answer":"فرعون لقب الملك في قومه، وفي مناداته به مراعاة للعرف في الخطاب واستجلاب لحسن استماعه. ويربط المصدر هذا النداء بالأمر الإلهي بالقول اللين، مع بقاء موسى ثابتًا في إعلان رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص159، تحت «دلالة التصريح باسم فرعون»","url":""}]},{"id":"s7-592","number":592,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"لم جاء ﴿وقال موسى﴾ بالواو بعد إجمال بعثته وظلم فرعون وملئه؟","answer":"بدأت القصة بإجمال النتيجة، ثم جاء قول موسى تفصيلًا لمقدماتها. فناسب الواو التي تجمع التفصيل إلى الإجمال، ولم تناسب الفاء الدالة على التعقيب؛ لأن ابتداء الحوار سابق على النتيجة التي أجملت.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص157–158، تحت «بلاغة الوصل في الآية»","url":""}]},{"id":"s7-593","number":593,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"لماذا بدأ موسى كلامه بالتوكيد: ﴿إني رسول﴾؟","answer":"أكد بـ﴿إن﴾ لأن فرعون مظنة الإنكار والتكذيب، ولإعلان حقيقة الرسالة بثبات أمام سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص159–160، تحت «سر التوكيد في حكاية كلام موسى»","url":""}]},{"id":"s7-594","number":594,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿رسول من رب العالمين﴾ لا «رسول الله»؟","answer":"﴿من رب العالمين﴾ تهدم دعوى فرعون للربوبية وتبين أن مرسل موسى هو رب الجميع، أما ﴿رسول الله﴾ فلا تظهر هذه المقابلة بالقدر نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص160، تحت «وجه إيثار صفة ﴿رب العالمين﴾»","url":""}]},{"id":"s7-595","number":595,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"لم جعل موسى إعلان رسالته عنوان كلامه: ﴿إني رسول من رب العالمين﴾؟","answer":"لأن إعلانه أنه مرسل من رب العالمين يقرر مصدر سلطانه في الخطاب، ويستدعي قبول ما جاء به. وفي ذلك إلقاء للمهابة في نفوس المخاطبين؛ فهو يبلغ عن ربهم، ولا يتكلم من تلقاء نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص160، تحت «علة إخبار النبي بالرسالة»","url":""}]},{"id":"s7-596","number":596,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿من رب العالمين﴾ بـ﴿من﴾؟","answer":"﴿من﴾ لابتداء الغاية؛ فرسالته صادرة من رب العالمين ووحيه من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص159–160، تحت «سر التوكيد في حكاية كلام موسى»","url":""}]},{"id":"s7-597","number":597,"surah":7,"verses":[104],"references":[{"surah":7,"verses":[104]}],"verseLabel":"الأعراف: 104","question":"ما مناسبة وصف الله بـ﴿رب العالمين﴾ في مواجهة فرعون؟","answer":"وصفه برب العالمين في مواجهة فرعون لنفي ربوبيته المزعومة وإثبات أن موسى وفرعون وكل الخلق تحت تدبير رب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص160–161، تحت «وجه إيثار صفة ﴿رب العالمين﴾»","url":""}]},{"id":"s7-598","number":598,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لماذا بدأ وصف نفسه بـ﴿حقيق على أن لا أقول على الله إلا الحق﴾ قبل إظهار المعجزة؟","answer":"قدم صدقه وأمانته في القول على المعجزة لأن دلالة الآية لا تنفصل عن دعوى حاملها؛ فهو ملتزم ألا ينسب إلى الله إلا الحق ثم يقيم البينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص165–166، تحت «سر إيثار لفظ ﴿حقيق﴾ على غيره»","url":""}]},{"id":"s7-599","number":599,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لماذا عُدّي ﴿حقيق﴾ بـ﴿على﴾ في قراءة الجمهور؟","answer":"من أوجه قراءة ﴿حقيق على أن لا أقول﴾ أن ﴿على﴾ بمعنى الباء؛ أي جدير بألا يقول على الله إلا الحق، أو أن ﴿حقيق﴾ ضمن معنى حريص فعدي بعلى. ويذكر المصدر أوجهًا أخرى، فلا تخلط هذه القراءة بقراءة ﴿حقيق عليَّ﴾ ذات ياء المتكلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص164–165، تحت «دلالة توجيه قراءة ﴿على﴾»","url":""}]},{"id":"s7-600","number":600,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"ما أثر قراءة ﴿حقيقٌ عليَّ﴾ في معنى الآية؟","answer":"على قراءة ﴿حقيق عليَّ﴾ يكون المعنى: واجب عليّ ولازم لي ألا أقول على الله إلا الحق، فتصرح القراءة بالتزام موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص164–165، تحت «دلالة توجيه قراءة ﴿على﴾»","url":""}]},{"id":"s7-601","number":601,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"ما الذي يضيفه وصف موسى نفسه بـ﴿حقيق﴾ إلى إعلانه الرسالة؟","answer":"يفيد أنه جدير بالقول الحق وثابت عليه، وأن الصدق لازم لما يبلغه عن الله. ويربط المصدر الوصف بحقيقة الرسالة وثبوتها؛ فليس إعلانه دعوى منفصلة عن الأمانة في التبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص165–166، تحت «سر إيثار لفظ ﴿حقيق﴾ على غيره»","url":""}]},{"id":"s7-602","number":602,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لماذا جاء القصر بـ﴿إلا الحق﴾؟","answer":"القصر يحصر كل ما يقوله موسى منسوبًا إلى الله في الحق وحده، فينفي عنه أدنى افتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص166، تحت «دلالة التعبير بلفظ ﴿الحق﴾»","url":""}]},{"id":"s7-603","number":603,"surah":7,"verses":[105,118],"references":[{"surah":7,"verses":[105,118]},{"surah":13,"verses":[1]}],"verseLabel":"الأعراف: 105؛ الأعراف: 118؛ الرعد: 1","question":"ما دلالة تعريف ﴿الحق﴾ في قول موسى: ﴿حقيق على أن لا أقول على الله إلا الحق﴾؟","answer":"يفيد الحق الكامل الثابت الذي لا يشوبه باطل، ويحتمل العهد إلى الحق الذي أوحاه الله إلى موسى؛ فليس كلامه رأيًا يحتمل الصدق والكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص166، تحت «سر التعبير بالمصدر المعرّف بـ﴿أل﴾»","url":""}]},{"id":"s7-1610","number":1610,"surah":7,"verses":[105,118],"references":[{"surah":7,"verses":[105,118]},{"surah":13,"verses":[1]}],"verseLabel":"الأعراف: 105؛ الأعراف: 118؛ الرعد: 1","question":"ما دلالة التعبير عن ﴿الحق﴾ مصدرًا معرفًا في قوله: ﴿فوقع الحق﴾؟","answer":"يصوّر ثبوت الحق الكامل وظهوره ظهورًا حاسمًا في مقابل بطلان السحر؛ فالمصدر المعرّف يعظم حقيقته ويؤكد تمامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص240، تحت «سر التعبير عن ﴿الحق﴾ مصدرًا معرفًا»","url":""}]},{"id":"s7-1611","number":1611,"surah":7,"verses":[105,118],"references":[{"surah":7,"verses":[105,118]},{"surah":13,"verses":[1]}],"verseLabel":"الأعراف: 105؛ الأعراف: 118؛ الرعد: 1","question":"ما دلالة تخصيص ﴿الحق﴾ بالذكر في قوله: ﴿والذي أنزل إليك من ربك الحق﴾؟","answer":"ينبه إلى أن القرآن هو الحق الكامل الذي سلم من الباطل، ويرد على من زعم أنه أساطير أو سحر؛ فخُص الحق بالذكر لأنه جوهر النزاع مع المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص594، تحت «توجيه تخصيص ذكر الحق بالذكر»","url":""}]},{"id":"s7-604","number":604,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لم أكد موسى مجيئه بالبينة بقوله ﴿قد جئتكم ببينة﴾؟","answer":"تحقق ﴿قد﴾ وقوع مجيئه بالحجة وتثبته في مقام قد يستغرب فيه المخاطبون دعوى الرسالة. وتأتي الجملة استئنافًا يجيب عن طلب الدليل الذي يثيره قوله إنه رسول لا يقول على الله إلا الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص166–167، تحت «بلاغة الاستئناف في قوله تعالى: ﴿قد جئتكم﴾»","url":""}]},{"id":"s7-605","number":605,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"ما دلالة تنكير ﴿ببينة﴾ في قول موسى؟","answer":"في التنكير تفخيم للحجة وتعظيم لشأنها؛ فهي بينة عظيمة تثبت رسالته. ويذكر المصدر أن البينة تحتمل البرهان العقلي وتحتمل المعجزة، ثم يأتي طلب فرعون لما يراه من آية حسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص167، تحت «سر تنوع معاني البينة وتنكيرها في سياق الآية الحكيم»","url":""}]},{"id":"s7-606","number":606,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لماذا كرر وصف الله بـ﴿ربكم﴾ بعد قوله ﴿رب العالمين﴾؟","answer":"انتقل من رب العالمين إلى ﴿ربكم﴾ لإلزام المخاطبين خاصة: الرب العام هو ربهم الذي تجب طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص168، تحت «دلالة حرف الجر ﴿من﴾ وإضافة الرب»","url":""}]},{"id":"s7-607","number":607,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لماذا انتقل من المفرد في خطاب فرعون إلى الجمع: ﴿جئتكم... ربكم﴾؟","answer":"بدأ بمواجهة فرعون، ثم عم الخطاب فرعون وملأه الحاضرين لأن الحجة والمطالبة متوجهتان إليهم جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص167–168، تحت «سر التعبير بقوله تعالى: ﴿ببينة من ربكم﴾»","url":""}]},{"id":"s7-608","number":608,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"لم فرع موسى طلبه ﴿فأرسل معي بني إسرائيل﴾ على إعلانه الرسالة والبينة؟","answer":"فالفاء تصل الطلب بما أقامه من حجة، ويصور الإرسال إطلاق من كان مقيدًا بالاستعباد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص168–169، تحت «علة التعبير بحرف الفاء في الإرسال في قوله تعالى: ﴿فأرسل﴾»","url":""}]},{"id":"s7-609","number":609,"surah":7,"verses":[105],"references":[{"surah":7,"verses":[105]}],"verseLabel":"الأعراف: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿معي﴾ لا «إليّ» أو «معنا»؟","answer":"﴿معي﴾ تفيد المصاحبة في الخروج تحت قيادته، لا مجرد إرسالهم إليه؛ وأفرد لأن موسى المتصدر للخطاب والطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص169، تحت «سر تقييد الإرسال بـ﴿معي﴾ وأثرها في المعنى»","url":""}]},{"id":"s7-610","number":610,"surah":7,"verses":[106],"references":[{"surah":7,"verses":[106]}],"verseLabel":"الأعراف: 106","question":"لماذا أجاب فرعون بشرط: ﴿إن كنت جئت بآية﴾ مع أن موسى قال: ﴿قد جئتكم ببينة﴾؟","answer":"تجاهل فرعون وصف البينة وردّه إلى شرط مشكوك فيه ﴿إن كنت﴾ مكابرةً، كأنه لم يثبت عنده شيء بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص172–173، تحت «دلالة التعبير بـ﴿إن﴾ دون ﴿إذا﴾»","url":""}]},{"id":"s7-611","number":611,"surah":7,"verses":[106],"references":[{"surah":7,"verses":[106]}],"verseLabel":"الأعراف: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿بآية﴾ لا ﴿ببينة﴾ كما قال موسى؟","answer":"البينة حجة واضحة قد تكون عقلية أو حسية، أما طلب فرعون للآية في هذا المقام فمتجه إلى معجزة محسوسة يراها. فاختلاف اللفظين يكشف انتقاله من سماع البرهان إلى طلب أمر خارق مشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص167–168، تحت «سر التعبير بقوله تعالى: ﴿ببينة من ربكم﴾»","url":""}]},{"id":"s7-612","number":612,"surah":7,"verses":[106],"references":[{"surah":7,"verses":[106]}],"verseLabel":"الأعراف: 106","question":"لماذا أمره بقوله: ﴿فأت بها﴾؟","answer":"الفاء جواب للشرط؛ أي إن كان معك دليل كما تزعم فأحضره وأظهره، وفي الأمر تحدٍّ واستخفاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص173–174، تحت «التعبير عن الإتيان بالمجاز المرسل»","url":""}]},{"id":"s7-613","number":613,"surah":7,"verses":[106],"references":[{"surah":7,"verses":[106]}],"verseLabel":"الأعراف: 106","question":"لماذا أعاد الشرط: ﴿إن كنت من الصادقين﴾؟","answer":"أعاد الشرط تشكيكًا في صدقه وتحديًا له، فجعل إظهار الآية محك الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص174، تحت «بلاغة التعبير بالأخص في سياق هذا النص»","url":""}]},{"id":"s7-614","number":614,"surah":7,"verses":[106],"references":[{"surah":7,"verses":[106]}],"verseLabel":"الأعراف: 106","question":"كيف يرتبط قوله ﴿إن كنت من الصادقين﴾ بطلب إظهار الآية؟","answer":"يشكك فرعون في دعوى موسى الصدق والرسالة، ويجعل إظهار الآية دليلًا يطالب به على تلك الدعوى. فالصدق أعم من الإتيان بآية؛ لأنه يكون في الأقوال والأفعال، والآية هنا شاهد خاص على صدقه فيما ادعاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص174، تحت «بلاغة التعبير بالأخص في سياق هذا النص»","url":""}]},{"id":"s7-615","number":615,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"لماذا عطف إلقاء العصا بالفاء: ﴿فألقى عصاه﴾؟","answer":"الفاء تدل على سرعة امتثال موسى للتحدي من غير تردد؛ فما إن طلب الآية حتى ألقى العصا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص177–178، تحت «سر التعبير بالإلقاء في قوله: ﴿فألقى عصاه﴾»","url":""}]},{"id":"s7-616","number":616,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"لماذا أضاف العصا إلى موسى: ﴿عصاه﴾؟","answer":"الإضافة تؤكد أنها عصاه المعهودة البسيطة التي يعرفها، فتظهر المفارقة المعجزة حين تنقلب ثعبانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص177–178، تحت «نكتة تخصيص العصا الحسية بالمعجزة الإلهية»","url":""}]},{"id":"s7-617","number":617,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا هي ثعبان﴾ بأداة المفاجأة؟","answer":"﴿إذا﴾ الفجائية تصور التحول المباغت من عصا جامدة إلى ثعبان حاضر، من غير زمن أو معالجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص178، تحت «دلالة التعبير بقوله: ﴿فإذا﴾»","url":""}]},{"id":"s7-618","number":618,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"كيف تؤكد جملة ﴿هي ثعبان﴾ حقيقة تحول العصا؟","answer":"﴿هي﴾ مبتدأ يعود إلى العصا، و﴿ثعبان﴾ خبره؛ فالجملة تثبت أن العصا نفسها صارت ثعبانًا حقيقيًا. ويؤكد المصدر هذا الوجه في مقابل التخييل، وهو ما يجعل المشهد دليلًا ظاهرًا على المعجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص178–179، تحت «دلالة الجملة الاسمية بين الحقيقة والمجاز»","url":""}]},{"id":"s7-619","number":619,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"لماذا وصف الحية هنا بـ﴿ثعبان مبين﴾، وفي طه بـ﴿حية تسعى﴾، وفي موضع بـ﴿كأنها جان﴾؟","answer":"هي حية في حقيقتها، وثعبان في عظمها، وكأنها جان في سرعة حركتها؛ فكل وصف يبرز جهة تلائم مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص181–182، تحت «الثعبان والحية والجان»","url":""}]},{"id":"s7-620","number":620,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"لماذا اختير ﴿ثعبان﴾ في مواجهة فرعون والسحرة؟","answer":"الثعبان يبرز كبر الحية وضخامتها، وهو وصف يلائم إظهار قوة المعجزة وهيبتها في مواجهة فرعون.؛ وتتكامل معه أوصاف الحية والجان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص181–182، تحت «الثعبان والحية والجان»","url":""}]},{"id":"s7-621","number":621,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"لماذا وُصف الثعبان بـ﴿مبين﴾؟","answer":"﴿مبين﴾ أي ظاهر الثعبانية لا تخييل فيه ولا اشتباه، فالمعجزة حقيقة مشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص176، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-622","number":622,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿ونزع يده﴾ لا «وأخرج يده»؟","answer":"النزع إخراج فيه قوة وشدة، وقد أخرج موسى يده من جيبه فظهرت بيضاء على وجه خارق.؛ وفي اختيار النزع تصوير لقوة إظهار المعجزة وثقل حجتها على فرعون ومن حوله، بحسب ما يذكره المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص184–185، تحت «نكتة إيثار لفظ النزع في قوله تعالى: ﴿ونزع﴾»","url":""}]},{"id":"s7-623","number":623,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"لماذا عطف معجزة اليد بالواو لا بالفاء؟","answer":"الواو تجمع آية اليد إلى آية العصا باعتبارهما حجتين مستقلتين، لا تجعل الثانية نتيجة للأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص183–184، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-624","number":624,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"لم قيل ﴿بيضاء للناظرين﴾، ولم يقتصر على وصف اليد بالبياض؟","answer":"يبين القيد أن بياضها ظاهر لمن يراها، لافت للنظر على وجه الإعجاز، لا بياض علة ومرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص184–185، تحت «بلاغة التتميم في التعبير عن بياض اليد بقوله تعالى: ﴿بيضاء﴾»","url":""}]},{"id":"s7-625","number":625,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"لماذا تكرر تركيب المفاجأة: ﴿فإذا هي﴾؟","answer":"تكرار ﴿فإذا هي﴾ يجدد المفاجأة في الآية الثانية ويثبت أن اليد نفسها صارت بيضاء للناظرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص178، تحت «دلالة التعبير بقوله: ﴿فإذا﴾»","url":""}]},{"id":"s7-626","number":626,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿بيضاء﴾ من غير ذكر «من غير سوء» هنا؟","answer":"قيد ﴿للناظرين﴾ هنا يبين أن البياض خارق لافت للنظر، وليس بياض علة؛ ولذلك لا يلزم إعادة ﴿من غير سوء﴾ في هذا الموضع. ويشرح المصدر هذا القيد بنظيره في طه الذي يصرح بنفي المرض والبرص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص184–185، تحت «بلاغة التتميم في التعبير عن بياض اليد بقوله تعالى: ﴿بيضاء﴾»","url":""}]},{"id":"s7-627","number":627,"surah":7,"verses":[108],"references":[{"surah":7,"verses":[108]}],"verseLabel":"الأعراف: 108","question":"لماذا قيد بياض اليد بـ﴿للناظرين﴾؟","answer":"قيدها بالناظرين لأن بياضها آية ضوئية ظاهرة يدركها كل من يشاهدها، لا إحساسًا خاصًا بموسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص184–185، تحت «فائدة التعدي باللام في سياق الكلام»","url":""}]},{"id":"s7-628","number":628,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"لماذا تولّى الملأ الجواب فقال: ﴿قال الملأ﴾ ولم يُذكر قول فرعون؟","answer":"حكى قول الملأ لأنه كان رأي الحاشية المتداول أو لأن فرعون قال لهم وقالوا له، فاختصر السياق المشاورة الجماعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص188، تحت «بلاغة الفصل في الآية الكريمة»","url":""}]},{"id":"s7-629","number":629,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿الملأ من قوم فرعون﴾، وفي الشعراء: ﴿قال للملإ حوله﴾؟","answer":"في الأعراف نُسب الحكم إلى ملأ فرعون، وفي الشعراء صُوّر فرعون مخاطبًا من حوله؛ والمشهدان يكشفان تواطؤ الرأس والحاشية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص190، تحت «متشابه اللفظ بين آية الأعراف109 وآية الشعراء34»","url":""}]},{"id":"s7-630","number":630,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"لماذا خُصّ الملأ بذكر قولهم: ﴿إن هذا لساحر عليم﴾؟","answer":"لأنهم وجوه القوم الذين تولوا المشاورة ومواجهة دعوة موسى؛ فذكر موقفهم يبرز دور القيادة في ترويج تهمة السحر وصرف الناس عن دلالة الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص187–188، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-631","number":631,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"لماذا أكدوا قولهم بـ﴿إن هذا لساحر﴾؟","answer":"أكدوا بـ﴿إن﴾ واللام لتثبيت التهمة وصرف الأنظار عن المعجزة الواضحة إلى دعوى السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص189–190، تحت «بلاغة جماع المؤكدات في سياق الآية الكريمة»","url":""}]},{"id":"s7-632","number":632,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"لماذا أشاروا إلى موسى بـ﴿هذا﴾ بدل تسميته؟","answer":"اسم الإشارة للحاضر يعيّنه أمامهم، وقد يحمل نبرة تحقير وإبعاد عن وصف الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص189، تحت «علة التعبير باسم الإشارة فيما تحويه الآية من عبارة»","url":""}]},{"id":"s7-633","number":633,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"ماذا أضاف وصف ﴿عليم﴾ إلى تهمتهم لموسى بأنه ﴿ساحر﴾؟","answer":"نسبوا إليه الرسوخ والمهارة في السحر، ليزعموا أن ما شاهدوه من الآيات ناشئ عن معرفة فائقة بهذه الصناعة. والوصف يقوي التهمة في زعمهم ويهيئ طلب سحرة على قدر ما نسبوه إليه من العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص189–190، تحت «بلاغة جماع المؤكدات في سياق الآية الكريمة»","url":""}]},{"id":"s7-634","number":634,"surah":7,"verses":[109],"references":[{"surah":7,"verses":[109]}],"verseLabel":"الأعراف: 109","question":"لم نسب القول في الأعراف إلى ﴿الملأ من قوم فرعون﴾، وفي الشعراء إلى فرعون: ﴿قال للملإ حوله﴾؟","answer":"المشهد محاورة بين فرعون وملئه، وقد قالوا هذا الرأي وتداوله بعضهم مع بعض؛ فحكت الأعراف قول الملأ، وحكت الشعراء خطاب فرعون لهم. ويذكر المصدر أن نسبته إلى الملأ تلائم ذكرهم مع فرعون في افتتاح قصة الأعراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص188، تحت «بلاغة الفصل في الآية الكريمة»","url":""}]},{"id":"s7-635","number":635,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"لماذا نسب الملأ إلى موسى إرادة إخراجهم: ﴿يريد أن يخرجكم﴾ مع أنه طلب إخراج بني إسرائيل؟","answer":"حوّلوا طلب تحرير بني إسرائيل إلى مؤامرة على الأرض تحريضًا للناس؛ فقلبوا غاية الرسالة السياسية ليحموا سلطانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص193–194، تحت «نكتة نسبة الإخراج والأرض إليهم في السياق الحكيم»","url":""}]},{"id":"s7-636","number":636,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"لماذا جاء ﴿يريد﴾ بالمضارع؟","answer":"المضارع يصور الإرادة متجددة قائمة الآن، ويستحضر خطرًا مزعومًا يوشك الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص193، تحت «بلاغة التعبير بالمضارع والمصدر المؤول»","url":""}]},{"id":"s7-637","number":637,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"ما سرّ تعبيرهم بـ﴿يخرجكم من أرضكم﴾، وإضافة الأرض إليهم؟","answer":"أضافوا الأرض إلى المخاطبين لاستثارة عصبيتهم وخوفهم على الوطن والملك، مع أنهم هم المستبدون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص193–194، تحت «نكتة نسبة الإخراج والأرض إليهم في السياق الحكيم»","url":""}]},{"id":"s7-638","number":638,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"لماذا حُذف ذكر السحر من قوله: ﴿يريد أن يخرجكم﴾ مع أنه أساس تهمتهم؟","answer":"يجري عرض القصة في الأعراف على الاختصار، فطوي قيد ﴿بسحره﴾ مع وضوح تهمة السحر من كلامهم السابق. أما التصريح به في الشعراء فيأتي في كلام فرعون بما يصوره من خوفه وتشبثه بتلك التهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص194–195، تحت «العدول عن ذكر لفظ ﴿بسحره﴾ بحذفه من السياق»","url":""}]},{"id":"s7-639","number":639,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿فماذا تأمرون﴾، وفيه ظهور فرعون مستشيرًا للملأ أو مخاطبًا لهم؟","answer":"إما أن فرعون قال للملأ ﴿فماذا تأمرون﴾ طالبًا رأيهم، أو أن الملأ قالوا لفرعون فحكي الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص195–196، تحت «موقع الفعل المضارع ﴿تأمرون﴾ ودلالته في السياق»","url":""}]},{"id":"s7-640","number":640,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"لماذا اختير فعل ﴿تأمرون﴾ لا «تشيرون»؟","answer":"المراد طلب المشورة والرأي، وقد عبر عنه بالأمر تلطفًا بالمخاطبين وتطييبًا لنفوسهم. وعلى جعله كلام فرعون، يكشف استناده إلى رأي الملأ عن اضطرابه وحاجته إليهم أمام الحجة، بعد ما كان يدعيه من الاستعلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص196، تحت «سر التعبير بلفظ الأمر في السياق الكريم»","url":""}]},{"id":"s7-641","number":641,"surah":7,"verses":[110],"references":[{"surah":7,"verses":[110]}],"verseLabel":"الأعراف: 110","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿يريد أن يخرجكم من أرضكم﴾، وزاد في الشعراء: ﴿بسحره﴾؟","answer":"قصة الأعراف مبنية هنا على الاختصار، فحذف القيد مع سبق نسبة السحر إلى موسى. وفي الشعراء صرح فرعون بـ﴿بسحره﴾؛ ويذكر المصدر أن كلامه كان أشد إظهارًا للخوف من موسى، فأضاف الإخراج إلى السحر ترسيخًا لتهمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص194–195، تحت «العدول عن ذكر لفظ ﴿بسحره﴾ بحذفه من السياق»","url":""}]},{"id":"s7-642","number":642,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"ما سرّ تعبيرهم بـ﴿أرجه وأخاه﴾، وما دلالة ﴿أرجه﴾؟","answer":"﴿أرجه﴾ أي أخّره وأمهله ولا تعاجله بالعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص197، تحت «شرح المفردات: ﴿أرجه﴾»","url":""}]},{"id":"s7-643","number":643,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"لماذا جمعوا موسى وأخاه في التأخير مع أن المواجهة صدرت من موسى؟","answer":"أدخلوا هارون معه لأنه شريكه في الرسالة والعون، وإن كان موسى المتصدر لإظهار الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص200–201، تحت «علة إخفاء اسم هارون مع أنه مرسل مع أخيه ووزير له»","url":""}]},{"id":"s7-644","number":644,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"لماذا لم يصرح باسم هارون فقال: ﴿وأخاه﴾؟","answer":"استغني عن التصريح باسمه لظهور أنه كان مع موسى، وقد بينت مواضع أخرى ذلك وذكرت اسمه. وفي وصفه بالأخوة ما يكفي لتعيينه هنا، مع كون موسى متصدر هذه المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص200–201، تحت «علة إخفاء اسم هارون مع أنه مرسل مع أخيه ووزير له»","url":""}]},{"id":"s7-645","number":645,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿وأرسل في المدائن حاشرين﴾، وفي الشعراء: ﴿وابعث في المدائن حاشرين﴾؟","answer":"الإرسال أخص من البعث؛ فالبعث يأتي للإرسال وغيره كالإحياء. ويذكر المصدر أن الأعراف، وهي الموضع الأسبق، اختارت اللفظ الأخص، ثم ورد الأعم في الشعراء تنويعًا للعبارة، مع اتحاد المطلوب وهو إحضار السحرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص201، تحت «إيثار لفظ الإرسال»","url":""}]},{"id":"s7-646","number":646,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿في المدائن﴾ لا «إلى المدائن»؟","answer":"﴿في المدائن﴾ تصور الحاشرين منتشرين داخلها يجوبونها ويبحثون، لا متجهين إلى حدودها فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص201، تحت «سر تعدية فعل الإرسال بـ﴿في﴾ دون ﴿إلى﴾»","url":""}]},{"id":"s7-647","number":647,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"لماذا جمع ﴿المدائن﴾؟","answer":"الجمع لأن السحرة موزعون في مدن متعددة، فأرادوا استقصاء مراكزهم كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص201–202، تحت «نكتة جمع المدينة على ﴿المدائن﴾»","url":""}]},{"id":"s7-648","number":648,"surah":7,"verses":[111],"references":[{"surah":7,"verses":[111]}],"verseLabel":"الأعراف: 111","question":"لماذا وصف المرسلين بـ﴿حاشرين﴾ لا «جامعين»؟","answer":"الحشر جمع الناس من جهات مختلفة وسوقهم إلى مكان واحد، وهو أدق من مجرد الجمع في تصوير مهمتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص203–204، تحت «الجمع والحشر»","url":""}]},{"id":"s7-649","number":649,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"لم جاء ﴿يأتوك﴾ جوابًا للأمر بإرسال الحاشرين؟","answer":"وصل الجزمُ بين إرسال الحاشرين ومجيئهم بالسحرة، فجعل الإتيان نتيجة متصلة بالأمر. ففيه بيان أن تنفيذ الاقتراح يفضي إلى جمع من يريدون الاستعانة بهم في مواجهة موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص204، تحت «إيثار الفعل المجزوم ﴿يأتوك﴾»","url":""}]},{"id":"s7-650","number":650,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿بكل ساحر﴾، وما الذي أفادته ﴿كل﴾؟","answer":"﴿كل﴾ تفيد الاستقصاء العرفي أو الكثرة؛ أي لا تتركوا ساحرًا متقنًا يمكن الاستعانة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص205، تحت «نكتة التعبير بلفظ ﴿كل﴾ الدال على العموم»","url":""}]},{"id":"s7-651","number":651,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"لماذا قرئ ﴿ساحر عليم﴾ و﴿سحّار عليم﴾؟","answer":"﴿ساحر﴾ اسم فاعل، و﴿سحّار﴾ صيغة مبالغة في كثرة السحر وإتقانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص205–206، تحت «سر المجيء بصيغة اسم الفاعل ﴿ساحر﴾ وصفته»","url":""}]},{"id":"s7-652","number":652,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"لماذا وصف كل ساحر بـ﴿عليم﴾؟","answer":"﴿عليم﴾ يدل على رسوخ معرفته بصناعة السحر ودقائقه، لا مجرد ممارسته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص205–206، تحت «سر المجيء بصيغة اسم الفاعل ﴿ساحر﴾ وصفته»","url":""}]},{"id":"s7-653","number":653,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"لماذا لم يقولوا: يأتوك بسحرة كثيرين؟","answer":"﴿كل ساحر عليم﴾ توجه الطلب إلى كل فرد من أهل الخبرة، فتفيد استقصاء هذا الصنف بحسب المقام، أو المبالغة في كثرة المطلوبين. فليست الغاية كثرة العدد وحدها، بل جمع من توفرت فيه المعرفة التي يريدونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص205، تحت «نكتة التعبير بلفظ ﴿كل﴾ الدال على العموم»","url":""}]},{"id":"s7-654","number":654,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]}],"verseLabel":"الأعراف: 112","question":"ما سرّ التعبير في الأعراف بـ﴿كل ساحر عليم﴾، وفي الشعراء بـ﴿كل سحار عليم﴾؟","answer":"على قراءة ﴿ساحر﴾ في الأعراف يوافق اللفظ ما سبقه من قولهم: ﴿إن هذا لساحر عليم﴾، وجاءت الشعراء بـ﴿سحار﴾ للمبالغة في طلب من يضاهي ما زعموه لموسى من مهارة، بما يلائم اشتداد خوف فرعون. وفي الأعراف قراءة ﴿سحار﴾ أيضًا، فلا يعمم الفرق على جميع القراءات.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص477، تحت «توجيه التشابه اللفظي»","url":""}]},{"id":"s7-655","number":655,"surah":7,"verses":[112],"references":[{"surah":7,"verses":[112]},{"surah":10,"verses":[79]}],"verseLabel":"الأعراف: 112؛ يونس: 79","question":"ما سرّ اختلاف جهة الأمر: ﴿يأتوك بكل ساحر عليم﴾ على لسان الملأ في الأعراف، و﴿ائتوني بكل ساحر عليم﴾ على لسان فرعون في يونس؟","answer":"في الأعراف الحكاية عن مشورة الملأ لفرعون: أرسل حاشرين يأتوك بالسحرة؛ وفي يونس أصدر فرعون الأمر بنفسه فقال: ﴿ائتوني﴾، فناسب كل فعل جهة الخطاب ومن صدر عنه الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص33، تحت «توجيه التشابه اللفظي»","url":""}]},{"id":"s7-656","number":656,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"لم صرح باسم فرعون في ﴿وجاء السحرة فرعون﴾؟","answer":"التصريح باسمه يبين أنه المقصود بمجيئهم، وفيه اهتمام بصورة اجتماع السحرة عليه وتناصرهم معه. ويبرز بذلك طرف المواجهة الذي حشدهم في وجه رسالة موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص210، تحت «سر إظهار المفعول به ﴿فرعون﴾ في الجملة»","url":""}]},{"id":"s7-657","number":657,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"ما سرّ تقديم مجيء السحرة قبل حوارهم؟","answer":"قدم مجيئهم لإقامة المشهد وبيان تنفيذ خطة الحشر، ثم نقل الحوار الذي كشف غايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص210، تحت «دلالة التعبير عن المجيء بالماضي في ﴿وجاء السحرة﴾»","url":""}]},{"id":"s7-658","number":658,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"لماذا بدأ السحرة بالسؤال عن الأجر قبل المبارزة؟","answer":"كشف سؤالهم أن باعثهم الأجر والمنزلة لا طلب الحق؛ فجعلوا المقابل شرطًا لبذل مهارتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص212–213، تحت «بيان التعريض بالتخضع في كلام السحرة»","url":""}]},{"id":"s7-659","number":659,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"ماذا تضيف قراءة الاستفهام في طلب السحرة للأجر؟","answer":"تجعل القراءة الطلب استثباتًا للجزاء وإلزامًا لفرعون بإقراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص211–212، تحت «الاستفهام التقريري وتوجيه تعدد القراءات»","url":""}]},{"id":"s7-1612","number":1612,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"ما أثر حشد المؤكدات واسمية الجملة في قراءة الخبر؟","answer":"تؤكد استحقاق الأجر وتطلب تقريره وضمانه؛ فتجتمع ﴿إن﴾ واللام مع ثبات الجملة الاسمية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص211–212، تحت «بلاغة حشد المؤكدات واسمية الجملة»","url":""}]},{"id":"s7-660","number":660,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"لماذا نكّروا ﴿أجرًا﴾؟","answer":"نكروه للتعظيم والتكثير؛ أي أجرًا عظيمًا مجزيًا يليق بما سيصنعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص212، تحت «نكتة تنكير الأجر في قوله تعالى: ﴿لأجرًا﴾»","url":""}]},{"id":"s7-661","number":661,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"ما سرّ تعبيرهم بـ﴿إن كنا نحن الغالبين﴾ وإظهار ضمير ﴿نحن﴾؟","answer":"أظهروا ﴿نحن﴾ توكيدًا لاختصاصهم بالغلبة واستعلاءً بثقتهم في صناعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص212–213، تحت «فائدة جمع لفظ ﴿الغالبين﴾ ودلالته»","url":""}]},{"id":"s7-662","number":662,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"لماذا جاء في الشعراء استفهام صريح: ﴿أئن لنا لأجرًا﴾، وهنا ﴿إن لنا لأجرًا﴾؟","answer":"فعلى الخبر يقررون استحقاق الأجر، وعلى الاستفهام يستثبتونه ويطلبون إقرار فرعون به؛ أما مقارنة الخبرية هنا بالاستفهام في الشعراء فتكشف اختلاف أسلوب الاستيثاق، ولا يصح اختزال جميع القراءات في حذف همزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص211، تحت «الاستفهام التقريري وتوجيه تعدد القراءات»","url":""}]},{"id":"s7-663","number":663,"surah":7,"verses":[113],"references":[{"surah":7,"verses":[113]}],"verseLabel":"الأعراف: 113","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وجاء السحرة فرعون قالوا﴾، وفي الشعراء: ﴿فلما جاء السحرة قالوا لفرعون﴾؟","answer":"الأعراف تجمل ما بين إرسال الحاشرين ومجيء السحرة، فتصل المشهد بالواو، وتذكر فرعون مع المجيء لتبين أنهم قصدوه هو. أما الشعراء فتفصل الحشر وجمع الناس، ثم تقول ﴿فلما جاء السحرة قالوا لفرعون﴾، فتربط حضورهم بما سبق وتعين المخاطب في القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص513–515، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-664","number":664,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"لماذا أجاب فرعون بكلمة واحدة: ﴿نعم﴾؟","answer":"﴿نعم﴾ تصديق لقولهم على الوجه الخبري، وجواب بالإيجاب على الوجه الاستفهامي؛ فهي تقرر حصول مطلوبهم. ثم زاد فرعون وعد التقريب تشجيعًا لهم، فلا يقتصر جوابه كله على الكلمة الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص215–216، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-665","number":665,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"لماذا لم يكتف بالأجر بل قال: ﴿وإنكم لمن المقربين﴾؟","answer":"زادهم وعد القرب من مجلسه وسلطانه فوق المال، ليبلغ تحريضهم غايته ويضمن ولاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص216–217، تحت «فائدة التعبير بالجملة الاسمية واسم الفاعل»","url":""}]},{"id":"s7-666","number":666,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"كيف قوي وعد فرعون في ﴿وإنكم لمن المقربين﴾؟","answer":"أكد الوعد بإن واللام، وجاء به في جملة اسمية تفيد ثبات المنزلة. وتدخلهم ﴿من المقربين﴾ في زمرة خاصته ذوي الحظوة، فيجتمع توكيد الخبر مع إغرائهم بالمكانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص216–217، تحت «علة تجديد التكريم في إجابة فرعون للسحرة المغرورين»","url":""}]},{"id":"s7-667","number":667,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"ما سرّ التعبير بـ﴿من المقربين﴾ بدل «مقربون»؟","answer":"تفيد ﴿من﴾ أنهم سيكونون أفرادًا داخل زمرة معروفة من أهل القرب والمنزلة، وهو أبلغ من مجرد إثبات وصف التقريب لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص512، تحت «معنى ﴿من﴾ ودلالتها في قوله تعالى: ﴿لمن المقربين﴾»","url":""}]},{"id":"s7-668","number":668,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"ما المقابلة بين طلبهم ﴿أجرًا﴾ ووعده لهم بالقرب؟","answer":"طلبوا منفعة المال، فوعدهم معها منفعة الجاه والقرب؛ فصعد بالجزاء ليشتد تنافسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص217، تحت «علة تجديد التكريم في إجابة فرعون للسحرة المغرورين»","url":""}]},{"id":"s7-669","number":669,"surah":7,"verses":[114],"references":[{"surah":7,"verses":[114]}],"verseLabel":"الأعراف: 114","question":"ما سرّ زيادة ﴿إذًا﴾ في قول فرعون في الشعراء: ﴿نعم وإنكم إذًا لمن المقربين﴾، وحذفها في الأعراف؟","answer":"تصرح ﴿إذًا﴾ في الشعراء بالجواب والجزاء، فتربط التقريب بما سألوا عنه من أجر عند الغلبة. ويوجه المصدر زيادتها بمجيء كلام السحرة هناك في صورة سؤال، في حين وافق خلو الأعراف منها الأسلوب الخبري في القراءة التي تجري عليها المقارنة؛ وليس التعليل مجرد حذف كلمة مقدرة للاختصار.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص510–511، تحت «دلالة التعبير بـ﴿إذًا﴾»","url":""}]},{"id":"s7-670","number":670,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"لماذا خيّر السحرة موسى: ﴿إما أن تلقي وإما أن نكون نحن الملقين﴾؟","answer":"التخيير إظهار للثقة والأدب الظاهر قبل المنافسة، مع ما فيه من تحدٍ لمن يبدأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص221، تحت «سر التخيير بين المتقابلات»","url":""}]},{"id":"s7-671","number":671,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"ما سرّ التعبير أولًا بـ﴿أن تلقي﴾ بالفعل، وثانيًا بـ﴿أن نكون نحن الملقين﴾ بالكون والاسم؟","answer":"قالوا لموسى ﴿أن تلقي﴾ بالفعل المجرد، ووصفوا أنفسهم بالاسم ﴿الملقين﴾ مع ﴿نحن﴾ لتوكيد ثبات الإلقاء واختصاصهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص223، تحت «فائدة هيئة لفظ ﴿الملقين﴾»","url":""}]},{"id":"s7-672","number":672,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"لماذا كرروا ﴿إما﴾ في طرفي التخيير؟","answer":"تأتي ﴿إما﴾ لتفصيل وجهي التخيير، فيعرض كل طرف مستقلًا: إلقاء موسى أو إلقاؤهم. وتكرارها مع تركيب الطرفين يوضح التقسيم الذي يسألونه عنه، ويهيئ تعيين من يبدأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص220، تحت «دلالة التعبير بحرف التفصيل ﴿إما﴾»","url":""}]},{"id":"s7-673","number":673,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"لماذا أظهروا ضمير ﴿نحن﴾؟","answer":"ضمير ﴿نحن﴾ لتوكيد أنهم الفريق المقابل وتضخيم شأنهم واستعدادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص220–221، تحت «دلالة التعريف بأل للفظ ﴿الملقين﴾»","url":""}]},{"id":"s7-674","number":674,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"لم لم يذكروا ما سيلقونه في ﴿إما أن تلقي وإما أن نكون نحن الملقين﴾؟","answer":"حذف مفعول الإلقاء للعلم به من المقام؛ فالمواجهة بين عصا موسى وما معهم من أدوات السحر. وهذا إيجاز يركز الحوار على اختيار من يبدأ، ويترك تفصيل الملقى لمشهد الإلقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص223، تحت «بلاغة الإيجاز بحذف المفعولات»","url":""}]},{"id":"s7-675","number":675,"surah":7,"verses":[115],"references":[{"surah":7,"verses":[115]}],"verseLabel":"الأعراف: 115","question":"ما سرّ اختلاف التعبير بين قول السحرة في الأعراف: ﴿وإما أن نكون نحن الملقين﴾، وفي طه: ﴿وإما أن نكون أول من ألقى﴾؟","answer":"يؤكد تركيب الأعراف رغبتهم في تولي الإلقاء بصيغة ﴿نكون نحن الملقين﴾، وتصرح طه بقيد السبق في ﴿أول من ألقى﴾؛ وكلاهما في عرض التخيير في البدء. ويذكر المصدر أن كلا التعبيرين يلائم فواصل سورته، مع أداء المعنى المتقارب بأسلوبين مختلفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص224، تحت «بلاغة التشابه والاختلاف في الآي»","url":""}]},{"id":"s7-676","number":676,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"لماذا أجاب موسى باقتضاب: ﴿ألقوا﴾؟","answer":"اقتضب ثقةً بربه وعدم مبالاة بسحرهم؛ فأمرهم أن يظهروا أقصى ما عندهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص226–227، تحت «توجيه العموم في خطاب موسى»","url":""}]},{"id":"s7-677","number":677,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"لماذا سمح لهم موسى أن يبدؤوا بالإلقاء؟","answer":"قدم إلقاءهم ليبلغوا غاية جهدهم في السحر، ثم تأتي المعجزة فتبطل ما جمعوه. فظهور الحق بعد تشوق الناس وانتظارهم أشد وقعًا في نفوسهم وأوضح في إظهار عجز السحرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص226–227، تحت «توجيه العموم في خطاب موسى»","url":""}]},{"id":"s7-678","number":678,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"ما وجه الإيجاز في الانتقال من ﴿قال ألقوا﴾ إلى ﴿فلما ألقوا﴾؟","answer":"حذف ما دل عليه السياق، والتقدير: فألقوا، فلما ألقوا؛ كما حذف مفعول الإلقاء للعلم به، أي آلات سحرهم. فجمع التعبير إيجاز الحدث وإيجاز المفعول، وانتقل إلى بيان أثر السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص227، تحت «دلالة الإيجاز بالحذف، في قوله تعالى: ﴿فلما ألقوا﴾»","url":""}]},{"id":"s7-679","number":679,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿سحروا أعين الناس﴾، دون أن يقال: سحروا الناس؟","answer":"قصر أثر سحرهم على الأعين لأنه تخييل بصري، لا تغيير لحقيقة الحبال والعصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص227، تحت «بلاغة التعبير بالمجاز»","url":""}]},{"id":"s7-680","number":680,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"كيف أفاد ﴿أعين الناس﴾ شمول أثر السحر للحاضرين؟","answer":"﴿أعين﴾ جمع قلة أريد به الكثرة لإضافته إلى ﴿الناس﴾ المعرف بأل الجنسية المستغرقة عرفًا؛ أي عيون الناس المحتشدين في ذلك الجمع. فدل التركيب على عموم التأثير في أبصار الحاضرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص227–228، تحت «نكتة ائتلاف الجمع، والتعريف بأل الجنسية في لفظ ﴿الناس﴾»","url":""}]},{"id":"s7-681","number":681,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿واسترهبوهم﴾ لا «وأرهبوهم»؟","answer":"الاسترهـاب طلب الرهبة واستجلابها والمبالغة في إحداثها، فهو أقوى من مجرد أرهبوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص228، تحت «بلاغة صيغة الاستفعال، في الفعل: ﴿واسترهبوهم﴾»","url":""}]},{"id":"s7-682","number":682,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"ما دلالة تنكير ﴿سحر﴾ في ﴿وجاءوا بسحر عظيم﴾؟","answer":"يفيد التنكير تهويل شأن ما جاءوا به من السحر، بما فيه من تنوع ودقة وقوة تأثير في نفوس الناظرين؛ فيهيئ لوصفه بالعظمة من جهة أثره المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص228، تحت «علة تنكير السحر، في قوله تعالى: ﴿وجاءوا بسحر عظيم﴾»","url":""}]},{"id":"s7-683","number":683,"surah":7,"verses":[116],"references":[{"surah":7,"verses":[116]}],"verseLabel":"الأعراف: 116","question":"لماذا وصف السحر بـ﴿عظيم﴾ مع أنه باطل؟","answer":"وصف بالعظم من جهة قوته في التخييل وأثره في الناس وكثرة وسائله، لا من جهة الحق والقيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص228–229، تحت «دلالة وصف السحر بالعظمة»","url":""}]},{"id":"s7-684","number":684,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿وأوحينا إلى موسى﴾ في أثناء المواجهة؟","answer":"ذكر الوحي في قلب المواجهة يبين أن حركة موسى بتوجيه ربه، وأن المعجزة ليست صناعة بشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص232، تحت «سر إيثار فعل الوحي ﴿وأوحينا﴾»","url":""}]},{"id":"s7-685","number":685,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"لم أظهر اسم موسى في ﴿وأوحينا إلى موسى﴾؟","answer":"في إظهار اسمه تشريف له وإبراز لمكانته عند تلقي الوحي وظهور الآية على يده. ويقابل ذلك إغفال أسماء السحرة، فاختص موسى بالتنويه في مقام إبطال سحرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص232–233، تحت «نكتة إظهار اسم موسى»","url":""}]},{"id":"s7-686","number":686,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿أن ألق عصاك﴾، فعاد إلى العصا المضافة إليه؟","answer":"إضافة العصا تذكر بأنها أداته المعهودة نفسها، وأن التحول من الشيء المألوف هو موضع الإعجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص234، تحت «دلالة إضافة العصا، واستحضار الضمير، في ﴿عصاك﴾»","url":""}]},{"id":"s7-687","number":687,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"لماذا جاءت المفاجأة مرة أخرى: ﴿فإذا هي تلقف﴾؟","answer":"﴿إذا﴾ الفجائية تصور شروع العصا في ابتلاع إفكهم فور إلقائها، فتحول المشهد في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص234–235، تحت «دلالة حرف الفاء، والحذف في السياق»","url":""}]},{"id":"s7-688","number":688,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿تلقف﴾ بالمضارع لا «لقفت»؟","answer":"المضارع يستحضر سرعة الالتقاط وتتابعه أمام العيون، كأن القارئ يشاهدها تبتلع ما ألقوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص235–236، تحت «دلالة صيغة المضارع ﴿تلقف﴾»","url":""}]},{"id":"s7-689","number":689,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿تلقف ما يأفكون﴾، وفي طه: ﴿تلقف ما صنعوا﴾؟","answer":"﴿ما يأفكون﴾ يكشف حقيقة سحرهم الأخلاقية: كذب مصروف عن الحق، و﴿ما صنعوا﴾ يركز في طه على إحكام عملهم الذي أبطلته العصا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص299، تحت «سر اختيار لفظ ﴿صنعوا﴾»","url":""}]},{"id":"s7-690","number":690,"surah":7,"verses":[117],"references":[{"surah":7,"verses":[117]}],"verseLabel":"الأعراف: 117","question":"لماذا عبّر عن سحرهم بـ﴿ما يأفكون﴾؟","answer":"الإفك قلب الحقيقة وصرفها؛ فسحرهم أظهر الساكن متحركًا، ولذلك سمى عملهم إفكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص236، تحت «إيثار التعبير بالإفك، في فاصلة الآية»","url":""}]},{"id":"s7-691","number":691,"surah":7,"verses":[118],"references":[{"surah":7,"verses":[118]}],"verseLabel":"الأعراف: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿فوقع الحق﴾، وما معنى وقوع الحق؟","answer":"الوقوع هنا الثبوت والظهور والتحقق؛ فلما بطلت المخايل استقر الحق ظاهرًا لا يدفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص239–240، تحت «بلاغة التعبير، بالوقوع على طريق الاستعارة»","url":""}]},{"id":"s7-693","number":693,"surah":7,"verses":[118],"references":[{"surah":7,"verses":[118]}],"verseLabel":"الأعراف: 118","question":"لماذا قابل وقوع الحق بـ﴿وبطل ما كانوا يعملون﴾؟","answer":"قابل ثبوت الحق بزوال عملهم؛ فظهور أحد الضدين يقتضي بطلان الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص240، تحت «بلاغة الطباق بين الحق والباطل»","url":""}]},{"id":"s7-694","number":694,"surah":7,"verses":[118,139,147],"references":[{"surah":7,"verses":[118,139,147]}],"verseLabel":"الأعراف: 118؛ الأعراف: 139؛ الأعراف: 147","question":"ما دلالة ﴿ما كانوا يعملون﴾ في الأعراف118؟","answer":"تدل كان مع المضارع على أن السحر كان دأبًا راسخًا وصناعة متكررة، ثم أبطل الله ذلك العمل حين ظهر الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص241، تحت «بيان التعبير بكان والمضارع، في سياق الآية»","url":""}]},{"id":"s7-1613","number":1613,"surah":7,"verses":[118,139,147],"references":[{"surah":7,"verses":[118,139,147]}],"verseLabel":"الأعراف: 118؛ الأعراف: 139؛ الأعراف: 147","question":"ما دلالة الجمع بين الماضي والمضارع في ﴿ما كانوا يعملون﴾ بالأعراف139؟","answer":"يجمع التركيب معنى الاستمرار والتجدد مع استحضار صورة أعمالهم الباطلة؛ فكان ذلك شأنًا متكررًا لا حادثة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص421، تحت «سر الجمع بين الماضي والمضارع»","url":""}]},{"id":"s7-1614","number":1614,"surah":7,"verses":[118,139,147],"references":[{"surah":7,"verses":[118,139,147]}],"verseLabel":"الأعراف: 118؛ الأعراف: 139؛ الأعراف: 147","question":"ما دلالة لفظ ﴿يعملون﴾ في الأعراف147؟","answer":"يشمل العمل ما اعتقدوه وما ظهر من آثاره في أقوالهم وأفعالهم؛ فالجزاء متعلق بما قدموه من ذلك كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص541–542، تحت «نكتة التعبير بلفظ ﴿يعملون﴾»","url":""}]},{"id":"s7-695","number":695,"surah":7,"verses":[118],"references":[{"surah":7,"verses":[118]}],"verseLabel":"الأعراف: 118","question":"ما الفرق بين التعبير بـ﴿يعملون﴾ و﴿يفعلون﴾ و﴿يصنعون﴾؟","answer":"العمل فعل مقصود، ويستعمل في الصالح والسيئ؛ والفعل أعم منه، فقد يقع بقصد أو بغير قصد وينسب إلى الإنسان وغيره؛ والصنع أخص، لأنه فعل محكم مجاد. فاختيار ﴿يعملون﴾ يلائم سحرًا قصدوه وداوموا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص242–243، تحت «يعملون، يفعلون، يصنعون»","url":""}]},{"id":"s7-696","number":696,"surah":7,"verses":[119],"references":[{"surah":7,"verses":[119]}],"verseLabel":"الأعراف: 119","question":"لماذا بُني ﴿فغُلبوا﴾ للمجهول؟","answer":"يركز البناء للمجهول على تحقق الغلبة عليهم، فلا حاجة إلى التصريح بالغالب بعد ظهور آية موسى. وفي ذلك إسناد النصر والتثبيت إلى الله الذي أيده بالمعجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص246، تحت «نكتة التعبير بصيغة المبني للمجهول ﴿فغلبوا﴾»","url":""}]},{"id":"s7-697","number":697,"surah":7,"verses":[119],"references":[{"surah":7,"verses":[119]}],"verseLabel":"الأعراف: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿هنالك﴾ باسم الإشارة للمكان البعيد؟","answer":"﴿هنالك﴾ تشير إلى مقام المواجهة الحاسم وتبعده رتبةً لعظم ما وقع فيه، لا لمجرد البعد المكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص246–247، تحت «سر التعبير باسم الإشارة ﴿هنالك﴾»","url":""}]},{"id":"s7-698","number":698,"surah":7,"verses":[119],"references":[{"surah":7,"verses":[119]}],"verseLabel":"الأعراف: 119","question":"كيف يوضح الضمير في ﴿وانقلبوا صاغرين﴾ مآل أهل الباطل؟","answer":"إذا حمل الانقلاب على الرجوع شمل الضمير الجمع ومنهم السحرة؛ أما إذا حمل على الصيرورة فالمراد فرعون وملؤه الذين صاروا صاغرين. ولا يحمل الصغار في هذا الوجه على السحرة بعد إيمانهم، فقد انتقلوا إلى عزة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص247، تحت «مرجع الضمير في ﴿وانقلبوا﴾»","url":""}]},{"id":"s7-699","number":699,"surah":7,"verses":[119],"references":[{"surah":7,"verses":[119]}],"verseLabel":"الأعراف: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿انقلبوا صاغرين﴾ لا «رجعوا مهزومين»؟","answer":"يفيد الانقلاب تحول الحال، وهو أبلغ من مجرد الرجوع؛ فقد انقلب أهل الباطل إلى حال أدنى مما كانوا عليه. ويبين وصف الصغار أن الغلبة أورثتهم الذل والانقياد، مع مناسبة جرس ﴿انقلبوا﴾ لقوله ﴿فغلبوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص247–248، تحت «نكتة إيثار لفظ ﴿وانقلبوا﴾»","url":""}]},{"id":"s7-700","number":700,"surah":7,"verses":[119],"references":[{"surah":7,"verses":[119]}],"verseLabel":"الأعراف: 119","question":"لماذا وصفوا بـ﴿صاغرين﴾؟","answer":"الصغار ذلة مع قهر؛ فناسب من تكبروا بالسحر ثم أظهر الله عجزهم أمام الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص247، تحت «علة التعبير بلفظ ﴿صاغرين﴾»","url":""}]},{"id":"s7-701","number":701,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]}],"verseLabel":"الأعراف: 120","question":"لماذا بُني ﴿وألقي السحرة ساجدين﴾ للمجهول؟","answer":"يصور البناء للمجهول سرعة خرورهم وقوة استجابتهم لما عاينوه، كأن قوة قاهرة ألقتهم ساجدين؛ فقد أخذت المعجزة بمجامع قلوبهم. وهو تصوير لاندفاعهم إلى السجود من غير تردد، لا تقرير لإكراه ينفي اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص250–251، تحت «نكتة إطلاق فعل الإلقاء، بصيغة البناء للمجهول»","url":""}]},{"id":"s7-702","number":702,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]}],"verseLabel":"الأعراف: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿أُلقي السحرة﴾ مع أنهم سجدوا باختيارهم؟","answer":"مع اختيارهم الإيمان، كانت المعجزة من شدة ظهورها سببًا غالبًا حملهم على السجود بلا تردد؛ فصوّر الفعل الاختياري في هيئة إلقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص251، تحت «بلاغة الاستعارة التمثيلية، في الآية القرآنية»","url":""}]},{"id":"s7-703","number":703,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]}],"verseLabel":"الأعراف: 120","question":"لم أظهر وصف ﴿السحرة﴾ في ﴿وألقي السحرة ساجدين﴾ مع أنهم آمنوا؟","answer":"عين اللفظ السحرة المعروفين الذين باشروا المنازلة دون سائر الحاضرين، وأبرز أن أهل الصنعة أنفسهم عرفوا الفرق بين السحر والمعجزة. فسجودهم أقوى في الدلالة على بطلان السحر وصدق موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص252، تحت «سر عهدية الألف واللام، وإظهار الفاعل»","url":""}]},{"id":"s7-704","number":704,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]}],"verseLabel":"الأعراف: 120","question":"لماذا عبّر بـ﴿ساجدين﴾ لا «فسجدوا»؟","answer":"﴿ساجدين﴾ حال تصور هيئة سقوطهم وثباتهم في السجود لحظة الإلقاء، بخلاف فعل مجرد يخبر بوقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص252–253، تحت «نكتة الإتيان بالسجود على صيغة اسم الفاعل ﴿ساجدين﴾»","url":""}]},{"id":"s7-705","number":705,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]}],"verseLabel":"الأعراف: 120","question":"ما مناسبة انتقالهم من الإلقاء للسحر إلى أن يُلقوا هم ساجدين؟","answer":"في لفظ الإلقاء مشاكلة لإلقائهم السحر قبل ذلك؛ فألقوا أولًا أدوات سحرهم، ثم خروا هم ساجدين حين ظهر الحق. ويصور هذا التحول سرعة استجابتهم وشدة تأثير المعجزة فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص250–251، تحت «نكتة إطلاق فعل الإلقاء، بصيغة البناء للمجهول»","url":""}]},{"id":"s7-706","number":706,"surah":7,"verses":[120],"references":[{"surah":7,"verses":[120]},{"surah":20,"verses":[70]},{"surah":26,"verses":[46]}],"verseLabel":"الأعراف: 120؛ طه: 70؛ الشعراء: 46","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وألقي السحرة ساجدين﴾ بالواو، وفي طه والشعراء: ﴿فألقي السحرة﴾ بالفاء؟","answer":"الواو في الأعراف تشرك سجود السحرة مع ما سبق في الدلالة على ثبوت نبوة موسى وظهور الحق؛ فلا تجعله مجرد أثر مترتب على غلبة السحرة. وفي الشعراء تأتي الفاء بعد تلقف العصا ما يأفكون للتعقيب، وفي طه تفصح الفاء عن سرعة الاستجابة بعد الأمر بالإلقاء وما دل عليه من وقوع المعجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص251–252، تحت «سر العدول إلى العطف بالواو، دون غيره»","url":""}]},{"id":"s7-707","number":707,"surah":7,"verses":[121],"references":[{"surah":7,"verses":[121]}],"verseLabel":"الأعراف: 121","question":"ما دلالة الجملة الفعلية ﴿قالوا آمنا برب العالمين﴾ بعد سجودهم؟","answer":"تنسب إليهم إعلان الإيمان بالقول كما أظهروا السجود بالفعل، وتبرز حدوث هذا الإعلان عقب المعجزة. فصورته الجملة الفعلية انتقالًا متجددًا من الكفر إلى الإيمان، يوافق ما ظهر على جوارحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص255، تحت «التعبير بالفعل المبني للمعلوم، والجملة الفعلية»","url":""}]},{"id":"s7-708","number":708,"surah":7,"verses":[121],"references":[{"surah":7,"verses":[121]}],"verseLabel":"الأعراف: 121","question":"لماذا اختاروا وصف ﴿رب العالمين﴾ نفسه الذي واجه به موسى فرعون؟","answer":"اختاروا ﴿رب العالمين﴾ ردًا على ربوبية فرعون المزعومة، وموافقةً لما أعلن موسى أنه رسول منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص256–257، تحت «تعريف لفظ الرب، ودلالة الباء الجارة»","url":""}]},{"id":"s7-709","number":709,"surah":7,"verses":[121],"references":[{"surah":7,"verses":[121]}],"verseLabel":"الأعراف: 121","question":"لم أسند القول إلى السحرة معلومًا في ﴿قالوا آمنا﴾؟","answer":"ليصرح بأنهم أظهروا الإيمان بألسنتهم، كما أظهروه بسجودهم؛ فإسناد القول إليهم يثبت إعلانهم ما استقر في قلوبهم، ويجعل شهادة اللسان موافقة لعمل الجوارح.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص255، تحت «التعبير بالفعل المبني للمعلوم، والجملة الفعلية»","url":""}]},{"id":"s7-710","number":710,"surah":7,"verses":[121],"references":[{"surah":7,"verses":[121]}],"verseLabel":"الأعراف: 121","question":"ما أثر الجمع بين سجود السحرة وقولهم ﴿آمنا برب العالمين﴾؟","answer":"السجود إعلان مرئي للخضوع، وقولهم ﴿آمنا﴾ إعلان صريح لمعناه. فاجتمع الفعل والقول لتقرير إيمانهم وإزالة احتمال أن يحمل سجودهم على غير الإيمان بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص255، تحت «إعلان الإيمان، بين الفعل المرئي، والقولي»","url":""}]},{"id":"s7-711","number":711,"surah":7,"verses":[122],"references":[{"surah":7,"verses":[122]}],"verseLabel":"الأعراف: 122","question":"لماذا بيّنوا بعد ذلك: ﴿رب موسى وهارون﴾؟","answer":"بيّنوا ﴿رب موسى وهارون﴾ ليرفعوا احتمال أن يريد فرعون برب العالمين نفسه أو معبودًا آخر، فعيّنوا رب الرسولين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص258–259، تحت «وجه الاحتراس والتبكيت في الآية»","url":""}]},{"id":"s7-712","number":712,"surah":7,"verses":[122],"references":[{"surah":7,"verses":[122]}],"verseLabel":"الأعراف: 122","question":"ما سرّ تقديم موسى على هارون؟","answer":"قُدم موسى لأنه صاحب المواجهة وإظهار العصا والمتصدر في الرسالة، وهارون تابع له في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص260–261، تحت «توجيه متشابه اللفظ، بين هذه الآية ومثيلاتها في مواقع أخر»","url":""}]},{"id":"s7-713","number":713,"surah":7,"verses":[122],"references":[{"surah":7,"verses":[122]}],"verseLabel":"الأعراف: 122","question":"لماذا أضافوا الرب إلى موسى وهارون مع أنه رب العالمين؟","answer":"الإضافة تعيّن رب العالمين الذي دعوا إليه وتعلن انضمامهم إلى دعوة موسى وهارون في وجه فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص259–260، تحت «سر إتباع التراكيب بعضها بعضًا في السياق»","url":""}]},{"id":"s7-714","number":714,"surah":7,"verses":[122],"references":[{"surah":7,"verses":[122]}],"verseLabel":"الأعراف: 122","question":"ما أثر تكرير لفظ ﴿رب﴾ في ﴿رب العالمين﴾ ثم ﴿رب موسى وهارون﴾؟","answer":"هو من الترديد؛ عاد اللفظ متعلقًا في كل موضع بما يخصص جهة من المعنى. فالأول يقرر عموم الربوبية، والثاني يعين المقصود ويدفع اللبس، فيؤكد المعنى ويزيده وضوحًا في نفس السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص260، تحت «بلاغة الترديد في الآية الكريمة»","url":""}]},{"id":"s7-715","number":715,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"ما سرّ تعبير فرعون بـ﴿آمنتم به قبل أن آذن لكم﴾، فجعل الإيمان محتاجًا إلى إذنه؟","answer":"كشف قوله أن الطاغية يعد ضمائر الناس ملكًا له، فلا يجيز الإيمان إلا بإذنه؛ وفي ذلك تصوير لأقصى الاستبداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص265، تحت «فصل الكلام، والتعبير بالمصدر المنسبك»","url":""}]},{"id":"s7-716","number":716,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لماذا جاء الاستفهام في قراءة ﴿أآمنتم﴾ للإنكار؟","answer":"الاستفهام إنكاري توبيخي؛ يستنكر استقلالهم بالإيمان ويهددهم، لا يستفهم عن وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص263–264، تحت «توجيه تعدد القراءات القرآنية في السياق»","url":""}]},{"id":"s7-717","number":717,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿آمنتم به﴾، وفي طه والشعراء: ﴿آمنتم له﴾؟","answer":"﴿آمنتم به﴾ تفيد التصديق بموسى أو بالله، و﴿آمنتم له﴾ تتضمن معنى الانقياد والتصديق لما دعا إليه؛ وكل سياق يبرز جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص264–265، تحت «سر تعدية الإيمان بالباء ﴿به﴾ واللام ﴿له﴾»","url":""}]},{"id":"s7-718","number":718,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لم صرح باسم فرعون في ﴿قال فرعون آمنتم به﴾؟","answer":"أظهر اسمه في مورد الذم والخسران، كما أظهر اسم موسى في موطن التشريف. وفي التصريح تعيين لصاحب الاعتراض والطغيان، وزيادة في إشهار مذمته في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص263، تحت «سر إظهار الفاعل، لفظ ﴿فرعون﴾ في السياق»","url":""}]},{"id":"s7-719","number":719,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لم جاء ﴿قبل أن آذن لكم﴾ بالمصدر المؤول بدل «قبل إذني لكم»؟","answer":"يبرز تركيب ﴿أن آذن﴾ نفس فعل الإذن الذي يزعم فرعون اشتراطه، فيقوي توبيخه لهم على سبق إيمانهم إذنه، ويكشف كبره وادعاء التحكم في استجابتهم للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص265، تحت «فصل الكلام، والتعبير بالمصدر المنسبك»","url":""}]},{"id":"s7-720","number":720,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"كيف قوّى فرعون تهمة المكر في ﴿إن هذا لمكر مكرتموه﴾؟","answer":"حشد إن واللام، وجاء بالجملة الاسمية لتقرير التهمة في أذهان السامعين. ومقصوده تهويل ما نسبه إلى السحرة وتسويغ الوعيد الشديد الذي سيلحقه بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص265–266، تحت «بلاغة حشد التوكيدات والتعبير باسمية الجملة»","url":""}]},{"id":"s7-721","number":721,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لماذا كرر مادة المكر: ﴿لمكر مكرتموه﴾؟","answer":"الجمع بين الاسم والفعل توكيد؛ سمى الحادث كله مكرًا ثم نسب صنعه إليهم عمدًا، تثبيتًا لتهمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص266، تحت «بديع الجناس الاشتقاقي، في سياق الآية»","url":""}]},{"id":"s7-722","number":722,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿في المدينة﴾ مع أن المكر المزعوم ظهر في ساحة اللقاء؟","answer":"يجوز أن يريد اتفاقهم المزعوم في المدينة قبل خروجهم إلى موضع الاجتماع، ويجوز أن تكون الظرفية مجازية، أي مكر قصدوا به الإضرار بالمدينة وأهلها. فلا ينحصر التعبير في تعيين مكان تدبير المؤامرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص266–267، تحت «بلاغة مجاز الظرف للحرف ﴿في﴾ من الآية»","url":""}]},{"id":"s7-723","number":723,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"ما غرض فرعون من اتهامهم بقوله ﴿لتخرجوا منها أهلها﴾؟","answer":"زعم أن إيمانهم حيلة متفق عليها للإضرار بأهل المدينة وإخراجهم، فحول دلالة المعجزة إلى تهمة تهدد الملك والسلطان. والمراد بأهلها في هذا المقام فرعون وقومه الذين يتولى حمايتهم في زعمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص266–267، تحت «بلاغة مجاز الظرف للحرف ﴿في﴾ من الآية»","url":""}]},{"id":"s7-724","number":724,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لماذا قدّم الجار والمجرور في ﴿منها أهلها﴾؟","answer":"قدم ﴿منها﴾ للعناية بالمدينة؛ فهي مقر الحكم ودار الملك وموضع أطماع السلطان. فتصدر ذكرها يصور الخطر الذي يزعمه فرعون على سلطانه وأهل مدينته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص267–268، تحت «نكتة تقديم ﴿منها﴾ على المفعول ﴿أهلها﴾»","url":""}]},{"id":"s7-725","number":725,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"لماذا هددهم بإبهام: ﴿فسوف تعلمون﴾ قبل تفصيل العقوبة؟","answer":"أبهم ما سيعلمونه ليضخم الوعيد ويفتح الخيال على عقاب مهول، ثم فصله في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص268، تحت «بلاغة التفريع على الإنكار، على طريق المجاز»","url":""}]},{"id":"s7-726","number":726,"surah":7,"verses":[123],"references":[{"surah":7,"verses":[123]}],"verseLabel":"الأعراف: 123","question":"ما سرّ التصريح باسم فرعون في الأعراف: ﴿قال فرعون آمنتم به﴾، وإضماره في طه والشعراء؟","answer":"التصريح بفرعون في الأعراف يبرز اسمه في مقام الذم مقابل إظهار موسى في مقام التشريف. ويذكر المصدر في مقارنة طه أن ذكره في الأعراف يجلي المقابلة بين رب العالمين ومدعي الربوبية، أما طه فورد فيها ﴿رب هارون وموسى﴾. وفي الشعراء أضمر الفاعل لأمن اللبس، مع ملاءمة الإضمار للإعراض عنه؛ فلا يحصر الفرق في قرب الاسم وبعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص314، تحت «توجيه المتشابه اللفظي في الحذف والذكر»","url":""}]},{"id":"s7-727","number":727,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"لماذا أكد الوعيد باللام والنون: ﴿لأقطعن... ولأصلبنكم﴾؟","answer":"اللام ونون التوكيد الثقيلة تصوران قسمه وتصميمه على تنفيذ التعذيب، في مواجهة ثبات المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص271، تحت «بلاغة التوكيد باللام في لفظ ﴿لأقطعن﴾»","url":""}]},{"id":"s7-728","number":728,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"لماذا قدّم تقطيع الأيدي والأرجل على الصلب؟","answer":"على وجه الترتيب الزمني يبدأ الوعيد بالتقطيع ثم يتبعه التصليب، فتجتمع صور التنكيل ويشتد التهديد. ويعرض المصدر وجوهًا في توالي العقوبتين، منها إمهالهم بعد القطع ليشاهد الناس أثره، فلا يجعل تعليل الترتيب منحصرًا في إطالة الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص272–273، تحت «دلالة ﴿ثم﴾ على توالي العذابين، التقطيع ثم التصليب»","url":""}]},{"id":"s7-729","number":729,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿أيديكم وأرجلكم﴾ فجمع الطرفين؟","answer":"جمع الأيدي والأرجل لاستيعاب السحرة وبيان أن العقوبة ستصيب طرفي كل واحد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص271، تحت «سر تقديم لفظ ﴿أيديكم﴾ وجمعها»","url":""}]},{"id":"s7-730","number":730,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"كيف يُشرح بلاغيًا المفردات: ﴿خلاف﴾؟","answer":"أي يقطع اليد من جانب والرجل من الجانب المقابل؛ فتشتد الإعاقة والتشويه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص269، تحت «شرح المفردات: ﴿خلاف﴾»","url":""}]},{"id":"s7-731","number":731,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"لماذا عطف الصلب بـ﴿ثم﴾؟","answer":"تحتمل ﴿ثم﴾ التراخي الرتبي لتعظيم التصليب وما فيه من تنكيل، دون اشتراط مهلة زمنية. ويذكر المصدر أيضًا وجه الترتيب والمهلة بعد القطع؛ فالمقصود تهويل الوعيد، ولا تنحصر الدلالة في طول الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص272–273، تحت «دلالة التعبير بحرف التراخي ﴿ثم﴾»","url":""}]},{"id":"s7-732","number":732,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"لماذا ختم التهديد بـ﴿أجمعين﴾؟","answer":"﴿أجمعين﴾ تهديد بالاستئصال الشامل؛ لا يستثني من المؤمنين أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص272–273، تحت «دلالة ﴿ثم﴾ على توالي العذابين، التقطيع ثم التصليب»","url":""}]},{"id":"s7-733","number":733,"surah":7,"verses":[124],"references":[{"surah":7,"verses":[124]}],"verseLabel":"الأعراف: 124","question":"ما سرّ مجيء ﴿ثم لأصلبنكم﴾ في الأعراف، و﴿ولأصلبنكم﴾ في طه والشعراء؟","answer":"تخص ﴿ثم﴾ في الأعراف معنى التراخي، ومن وجوهه تعظيم التصليب رتبة بعد التقطيع. أما الواو في طه والشعراء فتفيد مطلق الجمع ولا تعين ترتيبًا أو مهلة، فلا تعارض بين التعبيرين. ويربط المصدر اتساع دلالة الواو ببسط القصة في السورتين، لا باختصارهما ولا بمجرد الفواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص273، تحت «بيان متشابه الألفاظ بين الآي»","url":""}]},{"id":"s7-734","number":734,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"لماذا أجاب السحرة التهديد بقولهم: ﴿إنا إلى ربنا منقلبون﴾؟","answer":"واجهوا تهديده بأن الموت ليس نهاية بل رجوع إلى ربهم؛ فسلطان فرعون ينتهي عند الجسد وحكم الله هو الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص275–276، تحت «بلاغة الإيجاز في الجواب الصادر منهم»","url":""}]},{"id":"s7-735","number":735,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"ما أثر الجملة الاسمية واسم الفاعل في ﴿إنا إلى ربنا منقلبون﴾؟","answer":"تقرر الجملة رجوعهم إلى الله أمرًا ثابتًا، ويصور اسم الفاعل ﴿منقلبون﴾ هذا المآل كالوصف المستقر لهم. فتكشف ثبات يقينهم وطمأنينتهم في مواجهة الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص277، تحت «قصدية التعبير بالجملة الاسمية، واسم الفاعل»","url":""}]},{"id":"s7-736","number":736,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"لماذا قدّموا ﴿إلى ربنا﴾ على ﴿منقلبون﴾؟","answer":"قدموا ﴿إلى ربنا﴾ للاختصاص والعناية: إلى ربنا وحده المصير، لا إلى سلطانك وحكمك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص276، تحت «بلاغة تقديم الجار والمجرور ﴿إلى ربنا﴾»","url":""}]},{"id":"s7-737","number":737,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"ما سرّ تعبير السحرة بـ﴿ربنا﴾ في وجه فرعون؟","answer":"إضافة الرب إليهم إعلان ولائهم لله وقطع لربوبية فرعون عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص276–277، تحت «بلاغة اتحاد الضمائر، في السياق الحكيم»","url":""}]},{"id":"s7-738","number":738,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"لماذا اختاروا ﴿منقلبون﴾ لا «راجعون» أو «ميتون»؟","answer":"الانقلاب رجوع مع تحول من حال إلى حال؛ فهو انتقال بالموت إلى حكم الله وثوابه، لا فناء مجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص274، تحت «شرح المفردات: ﴿منقلبون﴾»","url":""}]},{"id":"s7-739","number":739,"surah":7,"verses":[125],"references":[{"surah":7,"verses":[125]}],"verseLabel":"الأعراف: 125","question":"ما سرّ زيادة ﴿لا ضير﴾ في الشعراء قبل ﴿إنا إلى ربنا منقلبون﴾، وحذفها في الأعراف؟","answer":"زاد الشعراء ﴿لا ضير﴾ لأن قصتها أبسط وأوفى في حوار المواجهة، أما الأعراف فاختصرت فبدأت مباشرة بعلة عدم المبالاة: الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص277–278، تحت «بلاغة المتشابه اللفظي بين آية الأعراف125، وآية الشعراء50»","url":""}]},{"id":"s7-740","number":740,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"ما سرّ تعبيرهم بـ﴿وما تنقم منا﴾، وما دلالة ﴿تنقم﴾؟","answer":"﴿تنقم﴾ أي تعيب وتكره وتعاقب؛ فهم ينكرون أن يكون له عليهم مأخذ إلا إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص279، تحت «شرح المفردات: ﴿تنقم﴾»","url":""}]},{"id":"s7-741","number":741,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا جاء القصر: ﴿إلا أن آمنا﴾؟","answer":"القصر يفضح ظلم فرعون: لا جريمة لهم إلا أن صدقوا آيات ربهم حين ظهرت.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص281–282، تحت «بلاغة التعبير بالاستثناء المفرغ في السياق»","url":""}]},{"id":"s7-742","number":742,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"ما أثر ربط الإيمان بالآيات في ﴿آمنا بآيات ربنا﴾؟","answer":"تربط الباء إيمانهم بموضوع التصديق ربطًا وثيقًا، وتضيف الآيات إلى ربهم تنويهًا بها وبمصدرها. فإيمانهم استجابة لحجج ربهم التي ظهرت لهم، وهو ما يجعل معاقبتهم عليه ظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص282–283، تحت «دلالة حرف الباء في قوله تعالى: ﴿بآيات﴾»","url":""}]},{"id":"s7-743","number":743,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"ما وجه اختيار ﴿جاءتنا﴾ في وصف آيات الله التي آمن بها السحرة؟","answer":"المجيء أعم من الإتيان، وقد يقع فيما فيه شدة وصعوبة؛ والآيات التي شاهدوها كان لها وقع شديد مهيب في نفوسهم. فاختياره يصور قوة أثرها حين ظهرت لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص283، تحت «دلالة إيثار فعل المجيء، على الإتيان»","url":""}]},{"id":"s7-744","number":744,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"كيف تتكامل الإضافتان في ﴿آيات ربنا﴾؟","answer":"أضيفت الآيات إلى الرب تنويهًا بعظمتها، وأضيف الرب إلى ضميرهم إعلانًا لانتسابهم إلى ربوبيته. فاجتمع تشريف الآيات وتشريف المؤمنين بها، وتهيأ بذلك دعاؤهم اللاحق ﴿ربنا أفرغ علينا صبرًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص283، تحت «دلالة تعالق التعريفات بالإضافة»","url":""}]},{"id":"s7-745","number":745,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا قيدوا إيمانهم بـ﴿لما جاءتنا﴾؟","answer":"تربط ﴿لما﴾ إيمانهم بمجيء الآيات وظهورها، فتجعل الإيمان استجابة للدليل حين حضر. ويذكر المصدر احتمال الظرفية بمعنى حين، واحتمال الحرفية؛ وفي تقييد إيمانهم بظهور الآيات بيان لقوة حجتهم في مواجهة فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص283، تحت «سر توجيه التعبير بـ﴿لما﴾»","url":""}]},{"id":"s7-746","number":746,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا انتقلوا من محاورة فرعون إلى الدعاء: ﴿ربنا أفرغ علينا صبرًا﴾؟","answer":"بعد أن بان عجز فرعون وتهديده انقطع التعلق به، فتوجهوا إلى من يملك القلوب والمصير طالبين الثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص284، تحت «بلاغة الالتفات في الخطاب»","url":""}]},{"id":"s7-747","number":747,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا استعير الإفراغ للصبر: ﴿أفرغ علينا صبرًا﴾؟","answer":"شُبّه الصبر بماء كثير يفرغ عليهم فيغمرهم؛ فطلبوا صبرًا واسعًا يحيط بنفوسهم أمام العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص285–286، تحت «دلالة الكناية، وجماع الاستعارات، عن شدة اضطرارهم إلى الله»","url":""}]},{"id":"s7-748","number":748,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا عُدّي الإفراغ بـ﴿على﴾؟","answer":"عُدّي بـ﴿على﴾ لتصوير الصبر نازلًا من فوق يغشاهم ويثبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص284، تحت «علة تقديم الجار على المفعول المطلق»","url":""}]},{"id":"s7-749","number":749,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا نُكّر ﴿صبرًا﴾؟","answer":"نُكّر للتعظيم والتكثير؛ طلبوا صبرًا عظيمًا يناسب شدة ما توعدهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص284، تحت «بلاغة الالتفات في الخطاب»","url":""}]},{"id":"s7-750","number":750,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"لماذا دعوا: ﴿وتوفنا مسلمين﴾ ولم يسألوا النجاة من فرعون؟","answer":"سألوا الثبات على الإسلام حتى الموت لأن سلامة الدين أعظم من سلامة الجسد، وقد استهانوا بعقوبة فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص280–281، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-751","number":751,"surah":7,"verses":[126],"references":[{"surah":7,"verses":[126]}],"verseLabel":"الأعراف: 126","question":"ما دلالة وصفهم باسم الفاعل ﴿مسلمين﴾ في دعائهم ﴿وتوفنا مسلمين﴾؟","answer":"طلبوا أن تقع وفاتهم وهم ثابتون على الإسلام؛ فاسم الفاعل يصور الإسلام حالًا متحققة فيهم عند الوفاة. وفي الدعاء سؤال دوام الانقياد لله إلى ختام حياتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص286، تحت «بلاغة التعبير بلفظ اسم الفاعل، والجملة الفعلية»","url":""}]},{"id":"s7-752","number":752,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما سرّ قول الملأ: ﴿أتذر موسى وقومه﴾ بعد إشارتهم بتأخيره وجمع السحرة؟","answer":"بعد فشل السحرة عاد الملأ يحرضون فرعون، متناسين أنهم أشاروا بالإمهال؛ فالاستفهام يدفعه إلى استئناف البطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص288، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-753","number":753,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لم جعل الملأ موسى مفعولًا لفعل الترك في ﴿أتذر موسى وقومه﴾؟","answer":"صوروه بمنزلة من صار في يد فرعون ثم يوشك أن يطلقه؛ فوجهوا الإنكار إلى تركه هو، مع أنه أبعد الناس عن الخضوع لفرعون. وفي هذا التصوير تحريض على البطش وإيهام بالقدرة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص291، تحت «نكتة إسناد فعل الترك ﴿أتذر﴾ واقعًا على موسى»","url":""}]},{"id":"s7-754","number":754,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لم حذف مفعول الإفساد في اتهام موسى وقومه: ﴿ليفسدوا في الأرض﴾؟","answer":"حذف المفعول للتعميم، فكأنهم ينسبون إليهم إفساد كل ما يخشون عليه. ويدخل في زعمهم مخالفة دينهم، وانفضاض الناس عن فرعون، ومنازعة سلطانه؛ فتتسع التهمة للتحريض عليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص292–293، تحت «سر حذف مفعول الإفساد، في قوله تعالى: ﴿ليفسدوا﴾»","url":""}]},{"id":"s7-755","number":755,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما سرّ اتهامهم موسى وقومه بأنهم ﴿ليفسدوا في الأرض﴾ مع وصف السياق فرعون وملأه بالمفسدين؟","answer":"سموا دعوة الناس إلى ترك عبادة فرعون وآلهته، ورفع الاستعباد عن بني إسرائيل، إفسادًا بحسب تصورهم الباطل للمصلحة. فالتعبير يحكي تحريضهم وقلبهم حقيقة الإصلاح إلى تهمة، مع أن مقصدهم حماية سلطان فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص292–293، تحت «نكتة التعبير باللام على طريق المجاز»","url":""}]},{"id":"s7-756","number":756,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما سرّ تعبيرهم بـ﴿في الأرض﴾ مع إرادتهم أرض مصر؟","answer":"أل للعهد الحضوري؛ فالمراد أرض مصر، مملكة فرعون وموطن بني إسرائيل. فهو إطلاق اسم عام أريد به موضع مخصوص يعرفه المخاطبون، ولا يلزم منه أنهم عدوا مصر كل الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص293، تحت «دلالة أل التعريف، في لفظ ﴿الأرض﴾»","url":""}]},{"id":"s7-757","number":757,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لماذا عطفوا ﴿ويذرك وآلهتك﴾ على الإفساد؟","answer":"جمعوا بين دعوى الإفساد العامة وبين ما يعدونه أخص خطرًا، وهو ترك موسى عبادة فرعون وآلهته. فبدؤوا بالعلة العامة ثم بالتحريض الخاص الذي يمس سلطانه، ليغروه بالبطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص293–294، تحت «دلالة تقديم فعل ﴿ليفسدوا﴾ على ﴿ويذرك﴾»","url":""}]},{"id":"s7-758","number":758,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"كيف يُفهم وجود ﴿آلهة﴾ لفرعون مع ادعائه: ﴿أنا ربكم الأعلى﴾؟","answer":"يذكر المصدر أن فرعون وقومه كانوا على تعدد المعبودات، وأن الآلهة قد تكون مما عبدوه من صور الكواكب ونحوها، أو مما شرعه هو لقومه. فدعواه الربوبية العليا لا تستلزم أنه ينفي تلك الآلهة؛ وإنما جمع بين دعوى العلو عليهم وتقرير عبادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص294–295، تحت «نكتة جمع ﴿وآلهتك﴾»","url":""}]},{"id":"s7-759","number":759,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما سرّ تعبير فرعون بصيغة الاستقبال في قوله: ﴿سنقتل أبناءهم﴾؟","answer":"السين تهديد بفعل متجدد سيستأنفه مستقبلًا، بعد أن كان قتل الأبناء قد وقع من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص295–296، تحت «فائدة السين، وتشديد فعل القتل ﴿سنقتل﴾»","url":""}]},{"id":"s7-760","number":760,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما دلالة قراءة ﴿سنقتّل أبناءهم﴾ بالتشديد؟","answer":"التشديد يدل على التكثير والتكرار؛ أي يكثر قتل الأبناء مرة بعد مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص295–296، تحت «فائدة السين، وتشديد فعل القتل ﴿سنقتل﴾»","url":""}]},{"id":"s7-761","number":761,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿ونستحيي نساءهم﴾ لا «ونترك نساءهم»؟","answer":"الاستحياء إبقاؤهن أحياءً للخدمة والاستذلال، فهو أخص من مجرد الترك وينطوي على قصد مهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص297، تحت «التعبير عن فعل ﴿ونستحيي﴾، على طريق المبالغة والتتميم»","url":""}]},{"id":"s7-762","number":762,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لماذا قابل قتل الأبناء باستحياء النساء؟","answer":"جمع بين إفناء قوة الرجال وإبقاء النساء للخدمة، لتصوير سياسة استئصالٍ واستعباد شاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص297–298، تحت «بلاغة أسلوب الطباق، والأسلوب الحكيم»","url":""}]},{"id":"s7-763","number":763,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لماذا ختم فرعون بقوله: ﴿وإنا فوقهم قاهرون﴾؟","answer":"أكد قدرته بـ﴿إن﴾ والجملة الاسمية ردًا على خوف الملأ، وزعم أن قهره لبني إسرائيل ثابت لا يتغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص299، تحت «سر التوكيد في الفاصلة، في هذه الآية»","url":""}]},{"id":"s7-764","number":764,"surah":7,"verses":[127],"references":[{"surah":7,"verses":[127]}],"verseLabel":"الأعراف: 127","question":"لماذا اختار ﴿فوقهم﴾ بدل «عليهم»؟","answer":"﴿فوقهم﴾ تصور علو القاهر واستيلاءه، كأنه متمكن من أعلى، وهي أقوى تصويرًا من مجرد ﴿عليهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص299، تحت «بلاغة الاستعارة في الفاصلة»","url":""}]},{"id":"s7-765","number":765,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لماذا بدأ موسى جوابه لقومه بـ﴿استعينوا بالله﴾ قبل الأمر بالصبر؟","answer":"قدم الاستعانة لأنها مصدر القدرة على الصبر؛ فلا يثبتون أمام الطغيان بقوتهم وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص303–304، تحت «نكتة تقديم ﴿استعينوا﴾ على ﴿واصبروا﴾»","url":""}]},{"id":"s7-766","number":766,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لماذا جمع بين الاستعانة والصبر؟","answer":"جمع لهم بين التعلق بالله وطلب معونته، وبين الثبات على ما يلقونه من البلاء. فالاستعانة بما لله من القدرة والتدبير تمدهم بما يعين على الصبر، واجتماعهما يواجه دعوى فرعون القهر والقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص304، تحت «بلاغة التعبير عن معنى التوكل بالأسلوب الحكيم»","url":""}]},{"id":"s7-767","number":767,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لم حذف متعلق الصبر في ﴿استعينوا بالله واصبروا﴾؟","answer":"حذف للتعميم، فيشمل الصبر على انتظار نصر الله، وعلى البلاء الذي يصيبهم، وعلى أذى من يجاهرهم بالعداء. فالأمر يتسع لما يحتاجون فيه إلى الثبات ولا يقصره على صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص303، تحت «سر حذف مفعول ﴿واصبروا﴾»","url":""}]},{"id":"s7-768","number":768,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الأرض لله﴾ ردًا على تهديد فرعون؟","answer":"الجملة تهدم ملك فرعون المزعوم: الأرض كلها لله، فلا يملك الطاغية أن يمنحها أو يمنعها استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص305، تحت «علة الفصل في جملة ﴿إن الأرض لله﴾»","url":""}]},{"id":"s7-769","number":769,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لماذا عرّف ﴿الأرض﴾ مع أن النزاع على مصر؟","answer":"يحتمل التعريف العهد، فتكون الأرض أرض مصر خاصة، ويحتمل الجنس، فتدخل مصر في عموم الأرض المملوكة لله. ويذكر المصدر أيضًا حملها على أرض الجنة؛ فلا يجزم بأن التعريف للاستغراق وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص305، تحت «دلالة أل التعريف في لفظ ﴿الأرض﴾»","url":""}]},{"id":"s7-770","number":770,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"ما سرّ التعبير في قوله تعالى: ﴿يورثها﴾، دون أن يقال: يعطيها؟","answer":"الإيراث انتقال الملك بعد زوال سابقه؛ فيوحي بأن سلطان فرعون عارض وأن الله ينقل الأرض لمن يشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص304، تحت «بلاغة التعبير بالكناية»","url":""}]},{"id":"s7-771","number":771,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"ما دلالة المضارع ﴿يشاء﴾ في ﴿يورثها من يشاء من عباده﴾؟","answer":"يدل على دوام نفاذ مشيئة الله في تمكين من يشاء ونزع الملك ممن يشاء، في الحال والاستقبال. فإيراث الأرض جار وفق إرادته، ولا يثبت لفرعون سلطان مستقل عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص306، تحت «إيثار المضارع في فعل المشيئة ﴿يشاء﴾»","url":""}]},{"id":"s7-772","number":772,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"ما أثر إضافة العباد إلى ضمير الله في ﴿من يشاء من عباده﴾؟","answer":"تخص الإضافة العباد بانتسابهم إلى الله، وفيها تشريف لهم، وتصل إيراث الأرض بسلطانه ومشيئته. فمصير الملك مرده إلى ربهم الذي يتصرف في عباده وأرضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص306، تحت «سر تعريف العباد بالإضافة في ﴿عباده﴾»","url":""}]},{"id":"s7-773","number":773,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لماذا ختم بـ﴿والعاقبة للمتقين﴾ ولم يقل: والنصر لبني إسرائيل؟","answer":"عمم الوعد للمتقين بدل تخصيص بني إسرائيل ليقرر سنة باقية: حسن النهاية لكل من اتقى، لا امتيازًا عرقيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص307–308، تحت «بلاغة عموم جملتي الفاصلة»","url":""}]},{"id":"s7-774","number":774,"surah":7,"verses":[128],"references":[{"surah":7,"verses":[128]}],"verseLabel":"الأعراف: 128","question":"لماذا اختيرت ﴿العاقبة﴾ لا «الغلبة»؟","answer":"العاقبة تنظر إلى نهاية الطريق بعد الابتلاء، وهي أوسع من غلبة وقتية؛ تشمل النصر والنجاة وحسن المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص307–308، تحت «دلالة التعريف بأل للفظ ﴿والعاقبة﴾»","url":""}]},{"id":"s7-775","number":775,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"ما سرّ قول بني إسرائيل: ﴿أوذينا من قبل أن تأتينا ومن بعد ما جئتنا﴾؟","answer":"عبّروا عن ضيقهم لأن الأذى استمر قبل رسالة موسى وبعد مجيئه، فكأنهم لم يروا أثر البشارة العاجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص311–312، تحت «نكتة التعريض بنفاد الصبر، بعد طول القهر»","url":""}]},{"id":"s7-776","number":776,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير أولًا بـ﴿أن تأتينا﴾ ثم بـ﴿ما جئتنا﴾؟","answer":"﴿أن تأتينا﴾ مصدرية تنظر إلى زمن المجيء المتوقع، و﴿ما جئتنا﴾ تؤكد تحقق المجيء الذي أعقبه استمرار الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص312–313، تحت «بديع التناوب في استعمال الإتيان والمجيء»","url":""}]},{"id":"s7-777","number":777,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"لم بني ﴿أوذينا﴾ للمجهول في شكوى بني إسرائيل؟","answer":"صرف البناء للمجهول الاهتمام إلى الأذى الذي أصابهم وقوته، دون تعيين مصدره في كل صورة. فجمع ما لحقهم من قتل واستعباد وأعمال شاقة وما تجدد من الوعيد، وركز شكواهم على استمرار المعاناة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص312، تحت «سر التعبير بالفعل المبني للمجهول ﴿أوذينا﴾»","url":""}]},{"id":"s7-778","number":778,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"لماذا أجابهم موسى بـ﴿عسى ربكم﴾ مع يقينه بوعد الله؟","answer":"ساق موسى الوعد في صورة الرجاء تعليمًا لقومه ألا يتكلوا على حصول النصر فيتركوا التقوى والعمل. والرجاء من حصول المنّة يهيئهم لشكرها؛ ويذكر المصدر أيضًا احتمال أنه لم يجزم باستحقاقهم العطاء ما داموا على حال الشكوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص314–315، تحت «نكتة التعبير بفعل الرجاء ﴿عسى﴾»","url":""}]},{"id":"s7-779","number":779,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿ربكم﴾ لا «ربي»؟","answer":"قال ﴿ربكم﴾ ليقوي صلتهم بربهم ويطمئنهم أن من يتولى إهلاك عدوهم هو مربيهم وناصرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص315، تحت «بلاغة إضمار الفاعل مقدمًا بلفظ ﴿ربكم﴾»","url":""}]},{"id":"s7-780","number":780,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"ما دلالة إضافة العدو إلى ضمير القوم في ﴿عدوكم﴾؟","answer":"تستحضر الإضافة ما نالهم من هذا العدو من استعباد وإذلال وتعذيب، فتربط الوعد بالإهلاك بمعاناتهم المشتركة. وفيها تذكير لهم بأن أعظم الخسران الانصراف عن عبادة الله إلى الخضوع لذلك الطغيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص315، تحت «سر نسبة العدو إلى القوم ﴿عدوكم﴾، بصيغة الجمع»","url":""}]},{"id":"s7-781","number":781,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"لم جمع موسى بين ﴿أن يهلك عدوكم﴾ و﴿ويستخلفكم في الأرض﴾؟","answer":"جمع الوعد بزوال قهر العدو والوعد بقيامهم مقامه في الأرض أحرارًا بعد الاستعباد. فالاستخلاف يتم البشارة بإزالة الطغيان، ويقابل انتقالهم إلى التمكين ما كانوا فيه من القهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص315–316، تحت «بلاغة التعبير بالمقابلة في السياق الحكيم»","url":""}]},{"id":"s7-782","number":782,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿يستخلفكم في الأرض﴾ لا «يملككم الأرض»؟","answer":"الاستخلاف جعلهم خلفاء بعد عدوهم، فيتحولون من الاستعباد إلى الحرية والتمكين. ويتصل بقوله ﴿فينظر كيف تعملون﴾، ليذكرهم أن هذه النعمة موضع امتحان للعمل والشكر، فلا يقف المعنى عند مجرد تملك الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص315–316، تحت «علة اصطفاء لفظ ﴿ويستخلفكم﴾»","url":""}]},{"id":"s7-783","number":783,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]}],"verseLabel":"الأعراف: 129","question":"لماذا ختم بـ﴿فينظر كيف تعملون﴾ بعد بشارة الاستخلاف؟","answer":"الخاتمة تحول البشارة إلى تكليف: سيظهر في الواقع كيف يشكرون نعمة التمكين ويقيمون أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص316–317، تحت «نكتة التعبير بالفعل المضارع»","url":""}]},{"id":"s7-784","number":784,"surah":7,"verses":[129],"references":[{"surah":7,"verses":[129]},{"surah":10,"verses":[14]}],"verseLabel":"الأعراف: 129؛ يونس: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف تعملون﴾ لا «ماذا تعملون»؟","answer":"﴿كيف﴾ تسأل عن هيئة العمل وصفته من طاعة وعدل أو معصية، لا عن مجرد نوع الأفعال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص316، تحت «دلالة التعبير بـ﴿كيف﴾»","url":""}]},{"id":"s7-785","number":785,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"لماذا أكد الخبر بالقسم واللام: ﴿ولقد أخذنا آل فرعون﴾؟","answer":"القسم المقدر واللام و﴿قد﴾ تؤكد أن الابتلاء وقع حقًا، تمهيدًا للعبرة من موقفهم منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص320–321، تحت «بلاغة تصدير الجملة بالقسم»","url":""}]},{"id":"s7-786","number":786,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿آل فرعون﴾ لا «فرعون وقومه»؟","answer":"﴿آل فرعون﴾ تشمل خاصته وأتباعه وأهل دولته المرتبطين بسلطانه، وتبرز أن البلاء أصاب النظام الفرعوني.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص323–324، تحت «الآل، والأهل»","url":""}]},{"id":"s7-787","number":787,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"لماذا عبّر عن الابتلاء بـ﴿أخذنا﴾؟","answer":"الأخذ يصور إحاطة الشدة بهم وتمكنها منهم، مع أنه ابتلاء دون الاستئصال الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص321، تحت «سر التعبير بالأخذ على طريق المجاز، أو الاستعارة»","url":""}]},{"id":"s7-788","number":788,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿بالسنين﴾، وما المراد بالسنين هنا؟","answer":"السنون هنا القحوط؛ فقد غلب استعمال السنة في الجدب إذا عرفت بأل. ويعلل المصدر الجمع بكثرة مواقع القحط وعمومه للأراضي والبلدان، فلا ينحصر الجمع في عدد الأعوام وطولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص321–322، تحت «قصدية جمع لفظ ﴿بالسنين﴾ في السياق»","url":""}]},{"id":"s7-789","number":789,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"لماذا جمع بين ﴿السنين﴾ و﴿نقص من الثمرات﴾؟","answer":"جمع بين القحط الذي يصيب نبات الزرع والحبوب، وبين نقص ثمرات الأشجار. فتنوع البلاء في وجوه معاشهم ليحملهم على الاعتبار؛ ولا يتوقف الفرق بينهما على تعيين الآفة التي أنقصت الثمار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص322، تحت «سر تنكير لفظ ﴿ونقص﴾، وقطعه عن الإضافة»","url":""}]},{"id":"s7-790","number":790,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما دلالة تنكير ﴿نقص﴾ في ﴿ونقص من الثمرات﴾؟","answer":"يحتمل التنكير التقليل، أي قلة إنتاج الثمرات على خلاف المعتاد، ويحتمل تعظيم النقص وشدته. فصور التعبير اختلال ما ألفوه من وفرة الثمار، واتصل بسياق أخذهم بالقحط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص322، تحت «سر تنكير لفظ ﴿ونقص﴾، وقطعه عن الإضافة»","url":""}]},{"id":"s7-791","number":791,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما دلالة ﴿لعلهم يذكرون﴾ في بيان غاية الابتلاء؟","answer":"التذكر رجوع إلى الاعتبار بآيات الله واستحضار ما ينبه إلى ترك المعصية؛ فالابتلاء يدعوهم إلى قبول التذكير والرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص322–323، تحت «نكتة التعبير بصيغة الترجي، وفعل المطاوعة»","url":""}]},{"id":"s7-1615","number":1615,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما دلالة ﴿لعلهم يضرعون﴾ في الأعراف94؟","answer":"التضرع هو التذلل والتخشع، وهو كناية عن الاعتراف بالذنب والتوبة؛ فالمطلوب أن يحملهم الابتلاء على الانكسار لله والرجوع إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص71، تحت «بلاغة الكناية في لفظ التضرع»","url":""}]},{"id":"s7-792","number":792,"surah":7,"verses":[130],"references":[{"surah":7,"verses":[130]}],"verseLabel":"الأعراف: 130","question":"ما أثر صيغة ﴿يذكرون﴾ في بيان غاية الابتلاء؟","answer":"تفيد صيغة المطاوعة قوة حصول التذكر والاعتبار المراد منهم، وتوحي بعظم الآثار التي تدعو إليه. فالابتلاء ينبههم ليقبلوا التذكير ويرجعوا عن المعصية، ولا يعني الترجي جهلًا من الله بمآلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص322–323، تحت «نكتة التعبير بصيغة الترجي، وفعل المطاوعة»","url":""}]},{"id":"s7-793","number":793,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما دلالة ﴿إذا﴾ في ﴿فإذا جاءتهم الحسنة﴾؟","answer":"إذا هنا شرطية تفيد تكرر مجيء الحسنة وتحققه، بما يلائم كثرة النعم. وتفرع الفاء وصف حالهم على خبر ابتلائهم السابق: لم يعتبروا، بل كانوا ينسبون النعمة إلى استحقاقهم ويتشاءمون عند الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص330، تحت «دلالة اقتران المعرف بحرف التحقيق، واقتران المنكر بحرف الشك»","url":""}]},{"id":"s7-794","number":794,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"لم عرفت ﴿الحسنة﴾ ونكرت ﴿سيئة﴾ في الآية؟","answer":"تعريف الحسنة يلائم شمول النعم وكثرتها، وتنكير السيئة يلائم ندرة ما يصيبهم منها بالنسبة إلى ذلك الخير. وفي المقابلة توبيخ لهم؛ ينسبون جنس الحسنات إلى أنفسهم، ويتشاءمون بموسى عند أي سيئة تصيبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص329–330، تحت «سر تعريف الحسنة، وتنكير السيئة»","url":""}]},{"id":"s7-795","number":795,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما سرّ تعبيرهم في الحسنة بقولهم: ﴿لنا هذه﴾؟","answer":"قولهم ﴿لنا هذه﴾ ادعاء للاستحقاق الذاتي، كأن النعمة حق ثابت لهم لا فضل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص327–328، تحت «سر اختيار حروف الجر، وتقديم الضمير»","url":""}]},{"id":"s7-796","number":796,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"لماذا أشاروا إلى الحسنة بـ﴿هذه﴾؟","answer":"الإشارة إلى الحسنة دون التصريح بمصدرها تلائم إنكارهم أنها نعمة من الله؛ فقد نسبوها إلى استحقاقهم واكتفوا بقولهم ﴿لنا هذه﴾. ويبرز ذلك غفلتهم عن المنعم الذي يشهد به حصول النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص328، تحت «نكتة التعبير باسم الإشارة ﴿هذه﴾»","url":""}]},{"id":"s7-797","number":797,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن تصبهم سيئة﴾ بـ﴿إن﴾، بينما قال في الحسنة ﴿فإذا جاءتهم﴾؟","answer":"اقترنت الحسنة بإذا لكثرة وقوع النعم وتحققها، واقترنت السيئة بإن لندرتها بالنسبة إلى الخير الواسع. وفي ذلك إبراز لسوء موقفهم: يغترون بالنعم الكثيرة، ويتشاءمون عند السيئة القليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص330–331، تحت «دلالة اقتران المعرف بحرف التحقيق، واقتران المنكر بحرف الشك»","url":""}]},{"id":"s7-798","number":798,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى في الحسنة ﴿جاءتهم﴾، وفي السيئة ﴿تصبهم﴾؟","answer":"﴿جاءتهم﴾ تلائم الحسنة كوافد مرغوب، و﴿تصبهم﴾ تصور السيئة كضربة تقع عليهم؛ فاختلاف الفعلين يرسم اختلاف تلقيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص328–329، تحت «دلالة التعبير عن الحسنة بـ﴿جاءتهم﴾، وعن السيئة بـ﴿تصبهم﴾»","url":""}]},{"id":"s7-799","number":799,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما سرّ تشاؤمهم بـ﴿موسى ومن معه﴾، وإغفالهم النظر في أعمالهم؟","answer":"تشاءموا بموسى ومن معه، فجعلوا مجيئهم سبب الشدة، بدل أن يردّوا المصائب إلى كفرهم وأعمالهم؛ فجاء الرد بأن نصيبهم وما يحل بهم بتقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص333، تحت «الغرض من التعبير بالباء، في ﴿بموسى﴾»","url":""}]},{"id":"s7-800","number":800,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما أثر افتتاح الرد بـ﴿ألا﴾ في قوله: ﴿ألا إنما طائرهم عند الله﴾؟","answer":"تستفتح ﴿ألا﴾ الكلام بالتنبيه القوي إلى بطلان تشاؤمهم، وتهيئ السامع للحكم الذي يصحح زعمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص333، تحت «سر التعبير بأداة الاستفتاح والتنبيه»","url":""}]},{"id":"s7-1616","number":1616,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما أثر القصر بـ﴿إنما﴾ في قوله: ﴿إنما طائرهم عند الله﴾؟","answer":"يقصر ما يصيبهم من شؤم وعقاب على تقدير الله وجزائه، فيبطل نسبته إلى موسى ومن معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص335، تحت «سر أسلوب القصر، بالأداة ﴿إنما﴾»","url":""}]},{"id":"s7-801","number":801,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"لماذا كرر مادة الطير في ﴿يطيروا﴾ و﴿طائرهم﴾؟","answer":"في ﴿يطيروا﴾ حكاية لتشاؤمهم الباطل، وفي ﴿طائرهم﴾ مشاكلة لهم مع نقل اللفظ إلى سببه الحق: نصيبهم المترتب على أعمالهم عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص334–335، تحت «بلاغة التصريح بلفظ الطائر، على طريق الاستعارة»","url":""}]},{"id":"s7-802","number":802,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿عند الله﴾ لا «من الله»؟","answer":"﴿عند الله﴾ تفيد أن أمر حظهم وجزائهم في حكم الله وتقديره، لا أن موسى هو منشأ ما أصابهم؛ فالمقام مقام رد الأمر إلى تدبيره وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص334، تحت «بلاغة المجاز، والإظهار في مقام الإضمار، في قوله: ﴿عند الله﴾»","url":""}]},{"id":"s7-803","number":803,"surah":7,"verses":[131],"references":[{"surah":7,"verses":[131]}],"verseLabel":"الأعراف: 131","question":"لماذا ختم بـ﴿ولكن أكثرهم لا يعلمون﴾؟","answer":"نفت الخاتمة عن أكثرهم العلم بأن ما أصابهم من عند الله وبسبب أعمالهم، وأشعرت بأن قليلًا منهم يعلم الحق ولكنه لا يعمل بمقتضاه عنادًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص335–336، تحت «قصدية التعبير بالاعتراض، والاستدراك»","url":""}]},{"id":"s7-804","number":804,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"ما دلالة قولهم: ﴿مهما تأتنا به من آية﴾ بدل «أي آية تأتنا»؟","answer":"﴿مهما﴾ من ألفاظ العموم؛ فالمعنى: أيّ آية تأتنا بها، مهما كانت، لن نؤمن، وفيه إعلان العناد قبل النظر في الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص339–340، تحت «دلالة تنوع المعاني وتعدد التوجيهات، في تركب ﴿مهما﴾»","url":""}]},{"id":"s7-805","number":805,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"ما الذي يكشفه قولهم لموسى: ﴿لتسحرنا بها﴾؟","answer":"سمّوا الآية سحرًا، وزعموا أن غرض موسى بها صرفهم عما هم عليه؛ فحوّلوا الدليل إلى تهمة ليثبتوا على الإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص341–342، تحت «فائدة فعلية الجملة، والتعبير بالمضارع في ﴿لتسحرنا﴾»","url":""}]},{"id":"s7-806","number":806,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"لماذا أعادوا الضمير في ﴿به من آية﴾ ثم ﴿بها﴾؟","answer":"ذكر الضمير في ﴿به﴾ مراعاة للفظ ﴿مهما﴾ ومعناه المبهم، ثم أنثه في ﴿بها﴾ بعدما بين ذلك المبهم بقوله ﴿من آية﴾. فانتقل التعبير من مراعاة اللفظ إلى ما كشف عنه البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص341، تحت «نكتة تذكير الضمير وتأنيثه، في قوله: ﴿به﴾ و﴿بها﴾»","url":""}]},{"id":"s7-807","number":807,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"ما سرّ تعبيرهم: ﴿فما نحن لك بمؤمنين﴾ بدل «فلن نؤمن بك»؟","answer":"الجملة الاسمية مع الباء الزائدة في ﴿بمؤمنين﴾ أشد توكيدًا لنفي الإيمان من قولهم: لن نؤمن؛ فهي تصور تمكّن العناد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص342، تحت «بلاغة التعبير بالمؤكدات، واسمية الجملة، وتقديم الجار والمجرور»","url":""}]},{"id":"s7-808","number":808,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"لماذا قدّموا ﴿لك﴾ على ﴿بمؤمنين﴾؟","answer":"تقديم ﴿لك﴾ يخص موسى بالرفض ويبرز عنادهم لشخصه ورسالته: فما نحن لك، على وجه الخصوص، بمصدقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص342، تحت «بلاغة التعبير بالمؤكدات، واسمية الجملة، وتقديم الجار والمجرور»","url":""}]},{"id":"s7-809","number":809,"surah":7,"verses":[132],"references":[{"surah":7,"verses":[132]}],"verseLabel":"الأعراف: 132","question":"لماذا عبّروا باسم الفاعل ﴿مؤمنين﴾؟","answer":"اسم الفاعل في ﴿مؤمنين﴾ يثبت نفي صفة الإيمان عنهم، لا مجرد نفي فعل يقع مرة؛ وهو ملائم لإصرارهم الدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص342، تحت «بلاغة التعبير بالمؤكدات، واسمية الجملة، وتقديم الجار والمجرور»","url":""}]},{"id":"s7-810","number":810,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا عطف إرسال الآيات بالفاء: ﴿فأرسلنا عليهم﴾؟","answer":"الفاء تفيد تعقيب العقوبات على عنادهم المعلن في الآية السابقة، فكان الإرسال جوابًا عمليًا عن قولهم إنهم لن يؤمنوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص346، تحت «بلاغة الوصل بالفاء، في قوله: ﴿فأرسلنا﴾»","url":""}]},{"id":"s7-811","number":811,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا عُدّيت الآيات بـ﴿على﴾: ﴿أرسلنا عليهم﴾؟","answer":"عدّي الإرسال بـ﴿على﴾ لأن هذه الآيات عقوبات نازلة مستعلية محيطة بهم، لا آيات مسوقة لهم على جهة التكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص346–347، تحت «علة صوغ الإرسال ماضيًا، وتعديه بعلى»","url":""}]},{"id":"s7-812","number":812,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"ما أثر نظم أسماء الآفات في ﴿الطوفان والجراد والقمل والضفادع والدم﴾؟","answer":"جمعت الآية أسماء أصناف متناسبة من العذاب في نسق واحد. ويبرز المصدر حسن تأليف هذه الألفاظ وترتيبها في اللفظ، بما فيه من انسجام يخفف ثقل بعض مفرداتها عند اجتماعها، مع وضوح تنوع العقوبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص348، تحت «بلاغة مراعاة النظير، وما لها من حسن وتأثير»","url":""}]},{"id":"s7-813","number":813,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"كيف تلائم صيغة ﴿الطوفان﴾ تصوير العذاب؟","answer":"الطوفان ما يطوف ويحيط، ويذكر المصدر أن بناء فعلان يفيد المبالغة أو يجيء اسم جنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص343، تحت «شرح المفردات: ﴿الطوفان﴾»","url":""}]},{"id":"s7-814","number":814,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"كيف تنوعت صيغ أسماء الآفات في الآية، وما دلالة هذا التنوع؟","answer":"لم تجئ كلها مفردة؛ فالضفادع جمع ضفدع، ويعرض المصدر في الطوفان والجراد والقمل أبنية تدل على المبالغة أو أسماء الجنس. أما الدم فاسم جنس يصدق على قليله وكثيره. فيجتمع اختلاف الأبنية مع تصوير كثرة العذاب وتنوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص347–348، تحت «بديع تنوع الصيغ الصرفية، تعبيرًا عن صنوف العذاب المرئية»","url":""}]},{"id":"s7-815","number":815,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا خُتمت القائمة بـ﴿الدم﴾؟","answer":"يربط المصدر تأخير ﴿الدم﴾ بحسن نظم القائمة وائتلاف ألفاظها؛ فاللفظ أخف وأحسن في السمع في هذا الموضع بعد الأسماء السابقة. ولا يجعل سبب تأخيره مجرد بلوغ العذاب ماء الشرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص348، تحت «بلاغة مراعاة النظير، وما لها من حسن وتأثير»","url":""}]},{"id":"s7-816","number":816,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا وصفها بـ﴿آيات مفصلات﴾؟","answer":"﴿مفصلات﴾ أي مبينات ظاهرات، يفصل بعضها عن بعض، تأتي آية بعد آية وبينها مهلة ليعتبروا ويرجعوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص349–350، تحت «سبب التعبير بلفظ ﴿آيات﴾، ووصفها بأنها ﴿مفصلات﴾»","url":""}]},{"id":"s7-817","number":817,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا جاءت ﴿مفصلات﴾ بصيغة التفعيل؟","answer":"صيغة التفعيل تدل على قوة الفصل والتبيين؛ فقد جاءت الآيات متميزة متتابعة، لا حادثة ملتبسة يمكن صرفها عن دلالتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص349–350، تحت «سبب التعبير بلفظ ﴿آيات﴾، ووصفها بأنها ﴿مفصلات﴾»","url":""}]},{"id":"s7-818","number":818,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿فاستكبروا﴾ بعد ظهور الآيات؟","answer":"تفرع الفاء استكبارهم على ظهور الآيات، مع أن مقتضى تلك الدلائل أن يصدقوا ويؤمنوا. فتكشف شدة عنادهم وفساد تلقيهم، وصيغة الاستكبار تصور تعاظمهم عن القبول، لا خفاء الدليل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص350، تحت «إيثار التعبير بالفاء السببية، والفعل المزيد، في ﴿فاستكبروا﴾»","url":""}]},{"id":"s7-819","number":819,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"لماذا ختم بـ﴿وكانوا قومًا مجرمين﴾؟","answer":"الخاتمة تبين أن الاستكبار ليس عارضًا؛ فقد كانوا راسخين في الإجرام، ولذلك قابلوا الآيات الواضحة بالعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص350–351، تحت «بلاغة التعبير بفن التذييل»","url":""}]},{"id":"s7-820","number":820,"surah":7,"verses":[133],"references":[{"surah":7,"verses":[133]}],"verseLabel":"الأعراف: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿قومًا مجرمين﴾ بدل «وكانوا مجرمين»؟","answer":"﴿قومًا﴾ خبر موطئ للوصف بعده، فيقوي تقرير صفة الإجرام ويبالغ في إثباتها لهم. والجملة تذيل خبر استكبارهم، فتفسره بما رسخ فيهم من الإجرام قبل ظهور هذه الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص350–351، تحت «بلاغة التعبير بفن التذييل»","url":""}]},{"id":"s7-821","number":821,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما وقع عليهم الرجز﴾، فصوّر العذاب واقعًا عليهم؟","answer":"﴿وقع﴾ يصور الرجز كحمل نازل استقر فوقهم وأحاط بهم، فيجسد شدة العذاب وتمكنه منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص355–356، تحت «بلاغة التعبير بلفظ ﴿وقع﴾، على طريق الاستعارة»","url":""}]},{"id":"s7-822","number":822,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا عبّر بـ﴿الرجز﴾ بعد تسمية الآيات الخمس؟","answer":"الرجز هو العذاب الموجب للاضطراب.؛ ويرجح المصدر أن أل للعهد، فيجمع اللفظ أصناف العذاب المذكورة قبلها تحت وصف العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص356–357، تحت «دلالة أل العهدية، في لفظ ﴿الرجز﴾»","url":""}]},{"id":"s7-823","number":823,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا نادوا: ﴿يا موسى﴾ بعد أن اتهموه بالسحر؟","answer":"لما مسهم العذاب عادوا إلى من اتهموه بالسحر، ونادوه باسمه استمالةً وطلبًا للنجدة؛ فكشف البلاء اضطرارهم إلى الاعتراف بمكان دعائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص357، تحت «سر التعبير بالنداء، وقصدية إظهار المنادى ﴿يا موسى﴾»","url":""}]},{"id":"s7-824","number":824,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"ما الذي تكشفه إضافتهم الرب إلى موسى في قولهم: ﴿ادع لنا ربك﴾ لا «ربنا»؟","answer":"إضافتهم الرب إلى موسى في ﴿ربك﴾ لا ﴿ربنا﴾ تكشف أنهم لم يدخلوا بعد في الإيمان، وإنما طلبوا كشف الضر ممن عرفوا قربه من ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص357–358، تحت «سر انتقاء الضمير في الإضافة إلى موسى بلفظ ﴿ربك﴾»","url":""}]},{"id":"s7-825","number":825,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"ما دلالة قولهم: ﴿بما عهد عندك﴾، وما المراد بالعهد؟","answer":"العهد هو ما أعطاه الله موسى من وعد بإجابة دعائه أو ما خصه به من النبوة والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص358، تحت «التعبير عن النبوة بالعهد»","url":""}]},{"id":"s7-826","number":826,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا قدّموا رفع الرجز: ﴿لئن كشفت عنا الرجز لنؤمنن لك﴾؟","answer":"جعلوا كشف الرجز شرطًا سابقًا، ثم رتبوا عليه وعد الإيمان والإرسال؛ فدل ترتيبهم على أن همهم العاجل النجاة من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص359–360، تحت «دلالة استئناف جملة ﴿لئن كشفت﴾»","url":""}]},{"id":"s7-827","number":827,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا اختير ﴿كشفت﴾ لا «رفعت»؟","answer":"الكشف إزالة ما يغطي ويحيط، فصور الرجز كغطاء ثقيل أطبق عليهم ثم أزيل، وهو أنسب من الرفع المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص354، تحت «شرح المفردات: ﴿كشفت﴾»","url":""}]},{"id":"s7-828","number":828,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا أكدوا وعد الإيمان والإرسال بالنون واللام؟","answer":"اللام ونون التوكيد الثقيلة في ﴿لنؤمنن﴾ و﴿لنرسلن﴾ غلظتا وعدهم، لتظهر المفارقة حين نكثوه بعد كشف الرجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص359–360، تحت «بديع حشد التوكيدات في الآية»","url":""}]},{"id":"s7-829","number":829,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"ما سرّ تعبيرهم: ﴿لنؤمنن لك﴾ لا «بك»؟","answer":"الإيمان المعدّى باللام هنا بمعنى التصديق والانقياد لموسى فيما جاء به، لا مجرد الإقرار بوجوده؛ أي لنصدقن دعوتك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص360، تحت «دلالة التضمين في لفظ الإيمان، في قوله: ﴿لنؤمنن لك﴾»","url":""}]},{"id":"s7-830","number":830,"surah":7,"verses":[134],"references":[{"surah":7,"verses":[134]}],"verseLabel":"الأعراف: 134","question":"لماذا عطفوا ﴿ولنرسلن معك بني إسرائيل﴾ على الإيمان؟","answer":"جمعوا بين حق الله بالإيمان وحق بني إسرائيل بإطلاقهم؛ لأن موسى طالبهم بالأمرين، فتعهدوا بهما معًا رجاء كشف البلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص360–361، تحت «بلاغة تقديم الإيمان، في قوله: ﴿لنؤمنن لك﴾»","url":""}]},{"id":"s7-831","number":831,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما كشفنا عنهم الرجز﴾ بالفاء؟","answer":"الفاء تصل الكشف مباشرة بدعاء موسى ووعدهم، وتبين سرعة إجابة الطلب وإقامة الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص364–365، تحت «دلالة الفاء، والتعبير بالفعل الماضي ﴿كشفنا﴾»","url":""}]},{"id":"s7-832","number":832,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"لماذا أعاد لفظ ﴿الرجز﴾ ظاهرًا ولم يضمره؟","answer":"كرر ﴿الرجز﴾ تصريحًا به وتوكيدًا لمعناه، مع اختلاف المقام: جاء أولًا في طلبهم، ثم في خبر كشفه عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص365–366، تحت «بيان التقديم والتأخير، في قوله: ﴿عنهم الرجز﴾»","url":""}]},{"id":"s7-833","number":833,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"لماذا قيد الكشف بـ﴿إلى أجل هم بالغوه﴾؟","answer":"بيّن القيد أن الكشف إمهال مؤقت إلى نهاية مقدرة سيبلغونها حتمًا، لا نجاة مطلقة من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص366–367، تحت «سر التعبير بالأجل، دون غيره»","url":""}]},{"id":"s7-834","number":834,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"ما أثر وصف الأجل بالجملة ﴿هم بالغوه﴾؟","answer":"جاء الوصف جملة اسمية، و﴿هم﴾ مبتدأ و﴿بالغوه﴾ خبره، فتقوى نسبة بلوغ الأجل إليهم وتصور تحققها. وفي ذلك تقرير أنهم صائرون إلى الغاية المقدرة لهم، وأن كشف العذاب لا يخرجهم من سلطانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص367، تحت «فائدة العدول عن الوصف بالمفرد، إلى الوصف بالجملة»","url":""}]},{"id":"s7-835","number":835,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"لماذا جاءت المفاجأة: ﴿إذا هم ينكثون﴾؟","answer":"﴿إذا﴾ الفجائية تصور أنهم ما إن وجدوا العافية حتى بادروا إلى نقض العهد، من غير تردد أو وفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص367، تحت «نكتة التعبير بحرف المفاجاة ﴿اذا﴾»","url":""}]},{"id":"s7-836","number":836,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"لماذا عبّر بالمضارع ﴿ينكثون﴾؟","answer":"المضارع يستحضر مشهد النكث ويصوره عادة متجددة منهم كلما كشف عنهم البلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص368–369، تحت «قصدية تقديم ضمير الفصل، والتعبير بالفعل المضارع»","url":""}]},{"id":"s7-837","number":837,"surah":7,"verses":[135],"references":[{"surah":7,"verses":[135]}],"verseLabel":"الأعراف: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿ينكثون﴾ لا «يخلفون»؟","answer":"النكث أصله نقض المفتول بعد إحكامه، فصوّر إفسادهم للعهد المؤكد كحل حبل محكم، وهو أبلغ من مطلق الإخلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص368–369، تحت «بلاغة التعبير عن نقض العهد، على طريق الاستعارة»","url":""}]},{"id":"s7-838","number":838,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لماذا بدأت العقوبة بـ﴿فانتقمنا منهم﴾ بعد تكرر النكث؟","answer":"الفاء تجعل الانتقام نتيجة متعقبة لتكرر النكث بعد تمام الحجة، فلا يبدو الإغراق عقوبة بلا سبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص373–374، تحت «سر التعبير عن الانتقام بصيغة الافتعال ﴿فانتقمنا﴾»","url":""}]},{"id":"s7-839","number":839,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]},{"surah":15,"verses":[79]}],"verseLabel":"الأعراف: 136؛ الحجر: 79","question":"ما سر اختيار لفظ ﴿فانتقمنا﴾ في قوله تعالى: ﴿فانتقمنا منهم﴾؟","answer":"لأن الانتقام هنا عقوبة مترتبة على ظلم متقدم وإصرار على التكذيب؛ فدل اللفظ على أن ما نزل بهم جزاء عدل بسبب جرمهم وكفرانهم للنعمة، لا عذابًا مجردًا بلا سبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص681، تحت «سر اختيار لفظ ﴿فانتقمنا﴾ دون (عذبنا) أو (عاقبنا)»","url":""}]},{"id":"s7-840","number":840,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لماذا فصّل الانتقام بقوله: ﴿فأغرقناهم في اليم﴾؟","answer":"جاء ﴿فأغرقناهم﴾ بيانًا لصورة الانتقام وكيفية وقوعه، بعد ذكره إجمالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص374–375، تحت «دلالة تفريع الانتقام بالإغراق، في ﴿فأغرقناهم في اليم﴾»","url":""}]},{"id":"s7-841","number":841,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لماذا اختير ﴿اليم﴾ لا «البحر»؟","answer":"اليم اسم للماء الكثير العميق الذي لا يدرك قعره، وهو يلائم مقام الإغراق والهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص379–381، تحت «البحر واليم»","url":""}]},{"id":"s7-842","number":842,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لم أجمل خبر إغراق فرعون وقومه في ﴿فأغرقناهم في اليم﴾؟","answer":"ساق خبر الإغراق هنا موجزًا لأن المقام مقام الأخذ الحاسم بعد طول الإمهال، فناسبه الإيجاز وسرعة انقضاء الخبر. وأجمل ما فصلته مواضع أخرى، ليقع الوعيد في النفس ويتهيأ الانتقال إلى خبر إنجاء المستضعفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص375–376، تحت «سر العدول عن الإطناب، إلى الإيجاز والإجمال»","url":""}]},{"id":"s7-843","number":843,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لماذا صرّح بسبب الإغراق: ﴿بأنهم كذبوا بآياتنا﴾؟","answer":"صرح بالسبب ليبين عدل العقوبة وأنها جزاء تكذيب مقصود بالآيات، لا حادثة منفصلة عن أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص376–377، تحت «دلالة الباء والمصدر في قوله: ﴿بأنهم كذبوا﴾»","url":""}]},{"id":"s7-844","number":844,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"لماذا جمع بين التكذيب والغفلة: ﴿كذبوا بآياتنا وكانوا عنها غافلين﴾؟","answer":"التكذيب فعلهم الظاهر في مقابلة الحجج، والغفلة إعراضهم المستمر عن دلالتها وعواقبها؛ فجمع بين الجحود وترك الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص377، تحت «نكتة التعبير بالجملتين: الاسمية والفعلية»","url":""}]},{"id":"s7-845","number":845,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"كيف وُصفوا بالغفلة مع أنهم رأوا الآيات وطلبوا كشف العذاب؟","answer":"الغفلة هنا ليست عدم رؤية الآيات، بل الإعراض عن موجبها وترك الاعتبار بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص377–378، تحت «دلالة عود الضمير في ﴿عنها﴾، إلى الآيات المدرجات في السياق»","url":""}]},{"id":"s7-846","number":846,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"ما سرّ التعبير في قوله تعالى: ﴿عنها غافلين﴾ بتقديم الجار والمجرور؟","answer":"تقديم ﴿عنها﴾ يبرز أن الآيات، مع وضوحها وكثرتها، هي عين ما أعرضوا عنه؛ وفيه تشديد للتوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص378–379، تحت «علة تقديم شبه الجملة على الخبر، والتعبير باسم الفاعل ﴿غافلين﴾»","url":""}]},{"id":"s7-847","number":847,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿وأورثنا القوم الذين كانوا يستضعفون﴾، دون أن يقال: وأعطينا بني إسرائيل؟","answer":"الإيراث تمليك يعقب زوال المالك السابق من غير كلفة على الوارث، فناسب انتقال أرض الجبارين إلى المستضعفين، وذكرهم بوصفهم السابق يبرز انقلاب الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص386–387، تحت «علة إيثار التعبير بالإيراث ﴿وأورثنا﴾، وكونه بصيغة الماضي»","url":""}]},{"id":"s7-848","number":848,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا وصفهم بالماضي المستمر: ﴿كانوا يستضعفون﴾؟","answer":"﴿كانوا يستضعفون﴾ تدل على أن الاستضعاف كان حالة مستمرة متكررة قبل التمكين، لا واقعة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص388، تحت «علة بناء فعل الاستضعاف ﴿يستضعفون﴾ للمجهول»","url":""}]},{"id":"s7-849","number":849,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا بُني ﴿يستضعفون﴾ للمجهول؟","answer":"يصور البناء للمجهول وقوع الاستضعاف عليهم من قاهر، ولا يصفهم بضعف ذاتي لازم. ويتصل بكان والمضارع لإبراز استمرار ما فرض عليهم من أسباب الضعف وتجددها، ثم يظهر الفرق بين تلك الحال وما أورثهم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص388، تحت «علة بناء فعل الاستضعاف ﴿يستضعفون﴾ للمجهول»","url":""}]},{"id":"s7-850","number":850,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿مشارق الأرض ومغاربها﴾ بالجمع؟","answer":"الجمع يلحظ تعدد جهات الشروق والغروب واختلافها في الأرض الموروثة، فيفيد سعتها وشمول التمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص389، تحت «السر في جمع المشارق والمغارب»","url":""}]},{"id":"s7-851","number":851,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا جمع بين المشارق والمغارب؟","answer":"ذكر المشارق والمغارب إحاطة بطرفي الأرض، أي أورثهم نواحيها الممتدة كلها، لا جهة واحدة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص388–389، تحت «دلالة وجهي المجاز والحقيقة، في التعبير عن تمليك أطراف الأرض»","url":""}]},{"id":"s7-852","number":852,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا وصف الأرض بـ﴿التي باركنا فيها﴾؟","answer":"يبين الوصف دوام الخير والخصب وسعة الأرزاق في الأرض التي أورثوها، ويذكر المصدر كونها مساكن الأنبياء والصالحين. ويعرض تفسير الأرض بالشام، ويذكر أيضًا مصر والشام؛ فلا يحصر الجواب تعيينها في قول واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص389–390، تحت «نكتة إيثار صيغة فاعل، في ﴿باركنا﴾»","url":""}]},{"id":"s7-853","number":853,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿وتمت كلمة ربك الحسنى﴾، وكيف تتم الكلمة؟","answer":"تمام الكلمة تحقق مضمون الوعد كاملًا في الواقع؛ فقد أنجز الله وعده بنجاة المستضعفين وتمكينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص390–391، تحت «براعة التعبير بالتمام على طريق الاستعارة، في قوله: ﴿وتمت﴾»","url":""}]},{"id":"s7-854","number":854,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا أضيف الرب إلى النبي: ﴿ربك﴾ بعد أن كان الخطاب عن بني إسرائيل؟","answer":"إضافة الرب إلى النبي ﷺ في ﴿ربك﴾ تسلية له وتثبيت: فالرب الذي أنجز وعده لبني إسرائيل سينجز وعده لرسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص392، تحت «الالتفات في قوله: ﴿ربك﴾»","url":""}]},{"id":"s7-855","number":855,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لماذا وُصفت الكلمة بـ﴿الحسنى﴾؟","answer":"﴿الحسنى﴾ لأن الكلمة وعد جميل بالنصر والتمكين، ولأن عاقبتها الحسنى ظهرت بتمامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص392، تحت «بلاغة الوصف بلفظ ﴿الحسنى﴾»","url":""}]},{"id":"s7-856","number":856,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿بما صبروا﴾ لا «لأنهم استُضعفوا»؟","answer":"علّق تمام الوعد بصبرهم ليبين أن التمكين جزاء ثباتهم على البلاء، لا لمجرد وقوع الاستضعاف عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص393، تحت «سر التعبير بالباء السببية والمصدر في ﴿بما صبروا﴾»","url":""}]},{"id":"s7-857","number":857,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما فائدة التعبير بالتدمير عن الإهلاك في قوله تعالى: ﴿ودمرنا ما كان يصنع فرعون وقومه﴾؟","answer":"التدمير إهلاك الشيء وإفساد بنائه، فشمل ما أنشأه فرعون وقومه من صنائع ومنشآت وما أقاموه من سلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص393–394، تحت «فائدة التعبير بالتدمير عن الإهلاك»","url":""}]},{"id":"s7-858","number":858,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"لم أظهر اسما فرعون وقومه في ﴿ما كان يصنع فرعون وقومه﴾؟","answer":"في التصريح بهما زيادة في ذمهما بعد ذكر تدمير مصنوعاتهما، إذ وقع الاسمان في مقام الخسران والعقوبة. وعطف قومه عليه يبين مشاركتهم له في أعمال الاستعباد والظلم والفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص393–394، تحت «بلاغة تقديم الصنع، وإظهار فاعليه»","url":""}]},{"id":"s7-859","number":859,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما أثر اجتماع كان والمضارع في ﴿ما كان يصنع فرعون وقومه وما كانوا يعرشون﴾؟","answer":"تدل كان على تحقق تلك الأعمال في الماضي، ويستحضر المضارع تكرر الصنع والعرش واستمرارهما. فيصور ما كانوا يزاولونه عملًا متجددًا مألوفًا، ثم وقع عليه التدمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص395، تحت «دلالة الجمع بين الماضي والمضارع، والعدول في الخبر إلى المضارع»","url":""}]},{"id":"s7-860","number":860,"surah":7,"verses":[137],"references":[{"surah":7,"verses":[137]}],"verseLabel":"الأعراف: 137","question":"ما الفرق بين ﴿ما كان يصنع فرعون وقومه﴾ و﴿ما كانوا يعرشون﴾؟","answer":"الصنع أعم، فيشمل تدبيرهم وأعمالهم ومنشآتهم؛ والعروش أخص بما كانوا يرفعونه من أبنية أو سقوف وكروم، فجمع النص العام والخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص385، تحت «شرح المفردات: ﴿يصنع﴾ و﴿يعرشون﴾»","url":""}]},{"id":"s7-861","number":861,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاوزنا ببني إسرائيل البحر﴾، فعُدّي التجاوز بالباء؟","answer":"تتضمن الباء معنى التعدية، أي جعلناهم يجاوزون البحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص401–402، تحت «دلالة الباء، في قوله: ﴿ببني إسرائيل﴾»","url":""}]},{"id":"s7-862","number":862,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما وجه استئناف خبر العبور بالواو في ﴿وجاوزنا ببني إسرائيل البحر﴾؟","answer":"وصلت الواو هذا الخبر بأصل القصة التي بدأت ببعثة موسى، لأن القرآن يقص جوانب منها في مقاطع متعددة. فانتقل من خبر هلاك فرعون وإيراث المستضعفين إلى ما أحدثه بنو إسرائيل بعد النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص403، تحت «سر العطف على أول القصة»","url":""}]},{"id":"s7-863","number":863,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتوا على قوم﴾ لا «فمروا بقوم»؟","answer":"ضمن الإتيان معنى المرور، فعدي بعلى التي تفيد استعلاء مجازيًا. فقد وجدوا القوم في طريقهم ولم يقصدوا الإقامة عندهم؛ فالتعبير يصور ما صادفوه في مسيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص403–404، تحت «دلالة تعدية فعل الإتيان بعلى، على طريق التضمين»","url":""}]},{"id":"s7-864","number":864,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما دلالة تنكير ﴿أصنام﴾ في وصف القوم؟","answer":"أبهم التنكير هذه الأصنام وحقر شأنها، ثم جاء وصفها بأنها ﴿لهم﴾ ليزيد التهكم باتخاذ القوم مصنوعات يملكونها آلهة يعبدونها. فالتنكير يبرز ضآلة معبوداتهم في مقام الإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص404، تحت «نكتة تنكير لفظ ﴿أصنام﴾»","url":""}]},{"id":"s7-865","number":865,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير بالمضارع ﴿يعكفون﴾؟","answer":"العكوف هو الملازمة مع الإقبال والتعظيم؛ فصورت الآية دوام إقامتهم على أصنام يعبدونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص404، تحت «سر التعبير بالمضارع ﴿يعكفون﴾»","url":""}]},{"id":"s7-866","number":866,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"لماذا عُدّي العكوف بـ﴿على﴾ لا بـ«عند»؟","answer":"عدي العكوف بـ﴿على﴾ لما فيه من الملازمة والإقبال والمواظبة على الشيء، وهي أبلغ من مجرد الكون عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص404، تحت «تعدية فعل العكوف بعلى على طريق التضمين»","url":""}]},{"id":"s7-867","number":867,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"لماذا وصف الأصنام بأنها ﴿لهم﴾؟","answer":"﴿لهم﴾ تكشف اختصاصهم بهذه الأصنام واتخاذهم إياها لأنفسهم، مع أنها مصنوعات مملوكة لهم لا آلهة تملكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص404، تحت «سر وصف الأصنام بأنها ﴿لهم﴾»","url":""}]},{"id":"s7-868","number":868,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"كيف طلب بنو إسرائيل إلهًا بعد أن جاوزوا البحر ورأوا هلاك فرعون؟","answer":"ولذلك واجههم موسى بالإنكار والتوبيخ على هذا الطلب بعد ما رأوه من آيات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص407، تحت «سر الوصف بالجهل المطلق، على طريق التوكيد بإن»","url":""}]},{"id":"s7-869","number":869,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما دلالة طلبهم: ﴿اجعل لنا إلهًا﴾، وهل يُجعل الإله؟","answer":"طلبهم ﴿اجعل﴾ لا يعني إمكان خلق إله حق، بل طلبوا أن يعين لهم معبودًا محسوسًا يتخذونه إلهًا كما اتخذ أولئك أصنامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص405–406، تحت «بلاغة التشبيه في قوله: ﴿كما لهم آلهة﴾»","url":""}]},{"id":"s7-870","number":870,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما سرّ قولهم: ﴿كما لهم آلهة﴾ بالجمع بعد طلب إله واحد؟","answer":"طلبوا معبودًا واحدًا لجماعتهم، وشبهوا حالهم بقوم لهم أصنام متعددة؛ فالمقصود مماثلتهم في أصل اتخاذ المعبود المحسوس لا في العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص405–406، تحت «بلاغة التشبيه في قوله: ﴿كما لهم آلهة﴾»","url":""}]},{"id":"s7-871","number":871,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما مناسبة جواب موسى: ﴿إنكم قوم تجهلون﴾؟","answer":"جاء الرد مؤكدًا بـ﴿إن﴾، ووصفهم بأنهم ﴿قوم تجهلون﴾ لأن طلبهم تعلق بأصل التوحيد بعد مشاهدة أعظم آيات النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص407–408، تحت «فائدة التعبير بالجملة الاسمية ﴿إنكم قوم تجهلون﴾»","url":""}]},{"id":"s7-872","number":872,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿تجهلون﴾ بالمضارع لا «جاهلون»؟","answer":"يصور المضارع الجهل متجددًا منهم في الحال والاستقبال، ويجعله خلة يظهر أثرها في سلوكهم. ويقوي هذا الإنكار تركيب ﴿قوم تجهلون﴾؛ فلا يدل اختيار المضارع وحده على أن الجهل عارض لا ثبات له.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص406–407، تحت «سر التعبير بالمضارع ﴿تجهلون﴾»","url":""}]},{"id":"s7-873","number":873,"surah":7,"verses":[138],"references":[{"surah":7,"verses":[138]}],"verseLabel":"الأعراف: 138","question":"ما أثر الانتقال من حكاية ﴿قالوا﴾ إلى مواجهتهم بقوله ﴿إنكم قوم تجهلون﴾؟","answer":"انتقل السرد من الحديث عنهم إلى خطاب موسى المباشر لهم، فبلغ الإنكار أسماعهم معينًا إياهم. وفي هذه المواجهة تقريع على طلبهم، وزجر لهم عن اتباع أهل الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص408، تحت «سر الالتفات من الغيبة إلى الخطاب»","url":""}]},{"id":"s7-874","number":874,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"لماذا بدأ إبطال عبادة الأصنام باسم الإشارة: ﴿إن هؤلاء﴾؟","answer":"اسم الإشارة يحضر أهل الأصنام أمام السامعين كأنهم مشاهدون، ثم يصدر الحكم على حالهم: ما هم فيه إلى هلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص417، تحت «سر التعريف باسم الإشارة، في قوله: ﴿هؤلاء﴾»","url":""}]},{"id":"s7-875","number":875,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿متبر ما هم فيه﴾، وما دلالة «متبر»؟","answer":"﴿متبر﴾ أي مهلك مدمر؛ فالمعنى أن ما هم فيه من دين وعبادة مصيره الزوال والهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص417–418، تحت «التعبير بالاشتقاق المضعف ﴿متبر﴾، على طريق الاستعارة التبعية»","url":""}]},{"id":"s7-876","number":876,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"لماذا جاء ﴿متبر﴾ اسمًا لا فعلًا؟","answer":"اسم المفعول ﴿متبر﴾ يثبت الحكم ويصوره مآلًا محققًا قائمًا، لا فعلًا عارضًا قد يقع أو لا يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص417–418، تحت «بلاغة التعبير بالتتبير، على صيغة التفعيل»","url":""}]},{"id":"s7-877","number":877,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿ما هم فيه﴾ بدل «عبادتهم»؟","answer":"﴿ما هم فيه﴾ يصور العبادة الباطلة كظرف أحاط بهم واستغرق حياتهم، وهو أوسع من تسمية فعل العبادة وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص419، تحت «بلاغة التعريف بالموصول ﴿ما﴾»","url":""}]},{"id":"s7-878","number":878,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿وباطل ما كانوا يعملون﴾ بعد ﴿متبر ما هم فيه﴾؟","answer":"الأول يحكم على المعبودات والحال التي لابسوها بالهلاك، والثاني يحكم على أعمالهم نفسها بالبطلان؛ فشمل فساد المعبود والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص419–420، تحت «بلاغة التعبير بالجملة الاسمية ﴿وباطل ما كانوا يعملون﴾»","url":""}]},{"id":"s7-880","number":880,"surah":7,"verses":[139],"references":[{"surah":7,"verses":[139]}],"verseLabel":"الأعراف: 139","question":"ما الفرق بين ﴿متبر ما هم فيه﴾ و﴿باطل ما كانوا يعملون﴾؟","answer":"﴿متبر﴾ يبين مآل ما هم فيه إلى التدمير، و﴿باطل﴾ يبين أن أعمالهم لا حقيقة نافعة لها ولا ثواب؛ فالأول للعاقبة والثاني للقيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص417–418، تحت «بلاغة التعبير بالتتبير، على صيغة التفعيل»","url":""}]},{"id":"s7-881","number":881,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"ما دلالة الاستفهام في قول موسى: ﴿أغير الله أبغيكم إلهًا﴾؟","answer":"الاستفهام إنكاري تعجبي: أيستبدل موسى بالله إلهًا آخر يطلبه لهم؟ وفيه إظهار فظاعة طلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص426–427، تحت «غرض الاستفهام في الآية الكريمة»","url":""}]},{"id":"s7-882","number":882,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"لماذا قدّم ﴿غير الله﴾ على الفعل؟","answer":"قدم ﴿غير الله﴾ لأنه محور الإنكار؛ فالمنكر أولًا أن يكون المطلوب أحدًا غير الله، أيًا كان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص427–428، تحت «بلاغة تقديم المفعول، وإنكاره بالهمزة»","url":""}]},{"id":"s7-883","number":883,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿أبغيكم﴾ لا «أجعل لكم» كما طلبوا؟","answer":"﴿أبغيكم﴾ تعني أطلب لكم وألتمس، وفيها رد طلبهم بصورته: أتطلبون مني أن أبحث لكم عن معبود غير الله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص423–424، تحت «شرح المفردات: ﴿أبغيكم﴾»","url":""}]},{"id":"s7-884","number":884,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"ما أثر مقابلة ﴿غير﴾ باسم الجلالة في ﴿أغير الله أبغيكم إلهًا﴾؟","answer":"﴿غير﴾ من أشد الأسماء إبهامًا، واسم الجلالة أعرف الأعلام وأخصها بالمعبود الحق. فتقابل الصيغتان يقرر إنكار طلب أي معبود آخر، مهما تنوعت صورته أو عظم في ظن طالبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص426، تحت «نكتة الإيغال في التنكير والتعريف»","url":""}]},{"id":"s7-885","number":885,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"لماذا عقب بقوله: ﴿وهو فضلكم على العالمين﴾؟","answer":"ذكّرهم بتفضيل الله لهم بالنعم والنجاة ليقيم الحجة من واقع إحسانه إليهم: فكيف يطلبون غير المنعم إلهًا؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص428–429، تحت «معنى اختصاصهم المعنوي بالتفضيل في ﴿فضلكم﴾»","url":""}]},{"id":"s7-886","number":886,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿فضلكم﴾ بالماضي؟","answer":"الماضي في ﴿فضلكم﴾ يقرر نعمة تحققت وشاهدوها، فتقوم بها الحجة عليهم ولا تبقى وعدًا منتظرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص429–430، تحت «بلاغة تقديم الضمير هو، والتخصيص بالفعل الماضي»","url":""}]},{"id":"s7-887","number":887,"surah":7,"verses":[140],"references":[{"surah":7,"verses":[140]}],"verseLabel":"الأعراف: 140","question":"كيف يُفهم قوله تعالى: ﴿على العالمين﴾ مع وجود أمم أفضل منهم؟","answer":"المراد عالمو زمانهم، أو التفضيل بما خصوا به من النجاة والآيات في ذلك المقام، لا أنهم أفضل من كل أمة في كل زمان وعلى كل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص430–431، تحت «نكتة اختيار لفظ ﴿العالمين﴾، في السياق»","url":""}]},{"id":"s7-888","number":888,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا انتقل الخطاب إلى ﴿وإذ أنجيناكم من آل فرعون﴾؟","answer":"ليقابل قبح الشرك بعظمة النعمة التي تلقوها من ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص434–435، تحت «بلاغة تكرار الآية، والتذكير بالعذاب دون النعمة»","url":""}]},{"id":"s7-889","number":889,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿أنجيناكم﴾ هنا، وفي البقرة: ﴿نجيناكم﴾؟","answer":"فيربط أنجيناكم في الأعراف بشدة المعاناة والحاجة إلى سرعة الخلاص، بينما تأتي نجيناكم في البقرة ضمن تذكيرهم بنعم امتدت في قصتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص436–437، تحت «نكتة العدول من لفظ نجيناكم إلى ﴿أنجيناكم﴾»","url":""}]},{"id":"s7-890","number":890,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"كيف يوجه خطاب ﴿أنجيناكم﴾ إذا حمل على أبناء الذين نجوا من فرعون؟","answer":"يعد الإنجاء نعمة على الأبناء أيضًا؛ فلو أهلك الآباء لم يوجد نسلهم. وعلى هذا التوجيه يكون إسناد نجاة الآباء إلى المخاطبين من المجاز العقلي، لأن صلاح حال الأسلاف يعود أثره على أخلافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص436، تحت «سر تعلق الإنجاء بالمخاطبين، ودلالة المجاز العقلي»","url":""}]},{"id":"s7-891","number":891,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]},{"surah":14,"verses":[6]}],"verseLabel":"الأعراف: 141؛ إبراهيم: 6","question":"ما سر التعبير بـ﴿آل فرعون﴾ بدل الاقتصار على فرعون؟","answer":"لأن الآل تشمل خاصة فرعون وأتباعه وأعوانه القائمين بأمره، وهم الذين باشروا استضعاف بني إسرائيل؛ فالنجاة كانت من سلطان جماعة ونظام بطش، لا من فعل شخص واحد فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص555، تحت «سر اختيار ﴿آل﴾»","url":""}]},{"id":"s7-892","number":892,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿يسومونكم سوء العذاب﴾، وما صورة «السوم»؟","answer":"السوم إلزام الشيء وإدامته؛ فصورت العبارة آل فرعون يذيقونهم العذاب مرارًا ويكلفونهم صنوفه بلا انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص441–442، تحت «وجه التضمين في قوله: ﴿يسومونكم﴾»","url":""}]},{"id":"s7-893","number":893,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا أضيف ﴿سوء﴾ إلى ﴿العذاب﴾؟","answer":"الإضافة في ﴿سوء العذاب﴾ تبين أنه أشد العذاب وأقبحه، ثم فصلت صورته بقتل الأبناء واستحياء النساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص443، تحت «بلاغة التعبير بالسوء، على صيغة التنكير والمصدرية»","url":""}]},{"id":"s7-894","number":894,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا قدّم ﴿يقتلون أبناءكم﴾ على ﴿ويستحيون نساءكم﴾؟","answer":"قدم قتل الأبناء لأنه أفجع وأشد إهلاكًا للجماعة، ثم ذكر إبقاء النساء للخدمة والاستذلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص445، تحت «سر تقديم ﴿يقتلون﴾ على ﴿ويستحيون﴾، وتخصيصه بالذكور»","url":""}]},{"id":"s7-895","number":895,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"ما الفرق بين ﴿يقتلون﴾ في الأعراف و﴿يذبحون﴾ في البقرة؟","answer":"القتل أعم من الذبح ويصور إزهاق الأرواح، أما ﴿يذبحون﴾ فتفصل هيئة القتل البشعة؛ فكل موضع يبرز جهة من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص452، تحت «يذبح و يقتل»","url":""}]},{"id":"s7-896","number":896,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لم جاءت ﴿يقتلون﴾ في الأعراف و﴿يذبحون﴾ في البقرة بلا واو، وجاءت ﴿ويذبحون﴾ في إبراهيم بالواو؟","answer":"في البقرة والأعراف جاءت جملة القتل أو التذبيح بيانًا لسوء العذاب وتفسيرًا له، فناسب الفصل. وفي إبراهيم عُطفت بالواو لأن موسى كان في مقام تعداد نعم الله على قومه، فاستحضر التذبيح عذابًا مخصوصًا مستقلًا ضمن صنوف العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص557–558، تحت «توجيه المتشابه اللفظي في الفصل والوصل»","url":""}]},{"id":"s7-897","number":897,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا عبّر بالمضارع ﴿يقتلون... ويستحيون﴾ عن أحداث ماضية؟","answer":"المضارع يستحضر مشهد القتل والاستحياء ويصور تكرره واستمراره، حتى كأن العذاب يقع أمام السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص448–449، تحت «سر العدول عن الماضي إلى المضارع، في فعلي القتل والاستحياء»","url":""}]},{"id":"s7-898","number":898,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"إلى ماذا يشير قوله تعالى: ﴿ذلكم﴾؟","answer":"يشير إلى ما سبق من العذاب والإنجاء، فيجمع المشهدين ليكونا موضع اعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص449–450، تحت «دلالة التعبير باسم الإشارة، في قوله: ﴿ذلكم﴾»","url":""}]},{"id":"s7-1617","number":1617,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا اختير لفظ ﴿البلاء﴾ في هذا الموضع؟","answer":"لأن البلاء يحتمل المحنة والاختبار والنعمة؛ فتجتمع فيه شدة ما وقع وعبرة النجاة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص450، تحت «بلاغة اختيار لفظ البلاء»","url":""}]},{"id":"s7-1618","number":1618,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"ما أثر تنكير ﴿بلاء﴾ و﴿عظيم﴾؟","answer":"يفخم التنكير شأن البلاء ويهول أثره، ويبين أنه عظيم صادر من ربهم ليستوجب الاعتبار والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص450–451، تحت «بلاغة تنكير لفظي ﴿بلاء﴾ و﴿عظيم﴾»","url":""}]},{"id":"s7-899","number":899,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"إلى ماذا يشير ﴿ذلكم﴾: إلى العذاب أم إلى الإنجاء؟","answer":"يجوز أن تعود الإشارة إلى سوء العذاب المذكور، وأن تشمل مجموع ما سبق من العذاب والإنجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص449–450، تحت «دلالة التعبير باسم الإشارة، في قوله: ﴿ذلكم﴾»","url":""}]},{"id":"s7-900","number":900,"surah":7,"verses":[141],"references":[{"surah":7,"verses":[141]}],"verseLabel":"الأعراف: 141","question":"لماذا وصف البلاء بأنه ﴿من ربكم﴾؟","answer":"إضافة البلاء إلى ﴿ربكم﴾ تذكر بأن ما جرى صادر عن تدبير المربي: ابتلى بالشدة وأنعم بالنجاة، ليستوجب الصبر والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص450–451، تحت «دلالة التعبير بلفظ ﴿ربكم﴾، مضافًا إلى المخاطب»","url":""}]},{"id":"s7-901","number":901,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿وواعدنا موسى﴾ بصيغة المفاعلة مع أن ابتداء الوعد من الله؟","answer":"المواعدة تفيد أن الله وعد موسى الحضور والتكليم، وموسى قابل الوعد بالحضور والوفاء؛ فصيغت المفاعلة لاشتراك الطرفين في متعلق الموعد، وإن كان ابتداء الوعد من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص455–456، تحت «نكتة التعبير بلفظ ﴿وواعدنا﴾»","url":""}]},{"id":"s7-902","number":902,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لم أجملت الأربعون ليلة في البقرة، وفصلت إلى ثلاثين وعشر في الأعراف؟","answer":"وردت قصة الأعراف مفصلة في شأن موسى وميقاته، فناسبها بيان الثلاثين وإتمامها بعشر وما تعلق بغيابه واستخلاف هارون. أما البقرة فجاءت الأربعون مجملة في سياق تذكير بني إسرائيل بالنعم؛ فلكل من الإجمال والتفصيل موقعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص462–463، تحت «نكتة العدول من الإجمال إلى التفصيل»","url":""}]},{"id":"s7-903","number":903,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لماذا بدأ الموعد بـ﴿ثلاثين ليلة﴾ ثم قال: ﴿وأتممناها بعشر﴾ بدل أن يقول: أربعين ليلة؟","answer":"ذُكرت الثلاثون أولًا ثم الزيادة بالعشر لإظهار أن الموعد مر بمرحلتين، وأن العشر إتمام لما سبق، وفي ذلك تمهيد لما وقع في مدة غياب موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص457–458، تحت «سر التعبير بلفظ الإتمام مع التفريق»","url":""}]},{"id":"s7-904","number":904,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لماذا عُبّر بالليالي لا بالأيام؟","answer":"عُبر بالليالي لأنها مبدأ حساب الشهور عند العرب، ولأن الخلوة والمناجاة ألصق بالليل؛ والمراد الليالي بأيامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص464–465، تحت «سر التعبير بالليالي دون الأيام»","url":""}]},{"id":"s7-905","number":905,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿وأتممناها بعشر﴾ ولم يكرر «ليال»؟","answer":"حذف تمييز ﴿عشر﴾ لدلالة ﴿ثلاثين ليلة﴾ عليه، فاستغنى عن تكراره إيجازًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص462، تحت «سر حذف تمييز لفظ ﴿بعشر﴾ في السياق»","url":""}]},{"id":"s7-906","number":906,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿فتم ميقات ربه أربعين ليلة﴾ بعد أن صار المجموع معلومًا؟","answer":"صرح بالمجموع توكيدًا لتمام الموعد ورفعًا لاحتمال أن تكون العشر داخلة في الثلاثين؛ فثبت أن الميقات أربعون ليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص459–460، تحت «سر التكرار بجملة إتمام الأربعين»","url":""}]},{"id":"s7-907","number":907,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لماذا أضاف الميقات إلى ﴿ربه﴾؟","answer":"إضافة الميقات إلى ﴿ربه﴾ تشريف له وبيان أن تحديده صادر عن الرب، وفي الإضافة معنى العناية بموسى وتربيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص464، تحت «نكتة العدول إلى التصريح بلفظ ﴿ربه﴾، وإضافة موسى إليه»","url":""}]},{"id":"s7-908","number":908,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لماذا عاد من ضمير التعظيم في ﴿واعدنا... أتممنا﴾ إلى الغيبة ﴿ربه﴾؟","answer":"عدل عن ضمير المتكلم إلى ﴿ربه﴾ لإظهار ربوبية الله لموسى؛ فهو مصلحه والناظر في أمره ومالكه والمتصرف فيه. فتخدم الإضافة مقام تربيته وإصلاحه وتهيئته لما سيلقاه في الميقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص464، تحت «نكتة العدول إلى التصريح بلفظ ﴿ربه﴾، وإضافة موسى إليه»","url":""}]},{"id":"s7-909","number":909,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما دلالة طلب موسى من هارون: ﴿اخلفني في قومي﴾ مع أنه نبي؟","answer":"فالخلافة هنا في سياسة القوم وحفظهم، ولا تنافي نبوة هارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص468–469، تحت «علة استخلاف هارون وعدم اصطحابه»","url":""}]},{"id":"s7-910","number":910,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لم أضاف موسى القوم إلى نفسه في ﴿اخلفني في قومي﴾؟","answer":"تؤكد الإضافة صلته بهم ومكانته عندهم، وأنه يريد لهم الخير ويحفظ مصلحتهم حين يغيب. وفيها تقوية لوصيته إلى هارون وتذكير للقوم بمراعاة عهد موسى وطاعة من استخلفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص468–469، تحت «نكتة تأكيد موسى نسبة قومه إليه ﴿قومي﴾»","url":""}]},{"id":"s7-911","number":911,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"لماذا أمر هارون بـ﴿وأصلح﴾ مع صلاحه ونبوته؟","answer":"الأمر بالإصلاح طلب للاستمرار عليه وبذل الجهد في إصلاح ما قد يطرأ أثناء غيبة موسى، لا اتهام لهارون بالفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص465–466، تحت «وجه التعبير عن الإصلاح بالأمر ﴿وأصلح﴾، مع إضمار مفعوله»","url":""}]},{"id":"s7-912","number":912,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تتبع سبيل المفسدين﴾، دون أن يقال: ولا تفسد؟","answer":"النهي عن اتباع سبيل المفسدين أوسع من قول «لا تفسد».","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص466–467، تحت «دلالة النهي، في قوله: ﴿ولا تتبع سبيل المفسدين﴾»","url":""}]},{"id":"s7-913","number":913,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما وجه البلاغة في التعبير بالاتباع، على طريق الاستعارة؟","answer":"استعير الطريق للمنهج الذي يؤدي إلى مشاركة المفسدين أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص467، تحت «بلاغة التعبير بالاتباع، على طريق الاستعارة»","url":""}]},{"id":"s7-1619","number":1619,"surah":7,"verses":[142],"references":[{"surah":7,"verses":[142]}],"verseLabel":"الأعراف: 142","question":"ما دلالة تعريف النكرة بالإضافة، والتعبير باسم الفاعل مجموعًا؟","answer":"ويصور اسم الفاعل ﴿المفسدين﴾ الصفة راسخة في أصحاب هذا المنهج.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص470، تحت «دلالة تعريف النكرة بالإضافة، والتعبير باسم الفاعل مجموعًا»","url":""}]},{"id":"s7-914","number":914,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"كيف يوجه تعلق المجيء بالميقات في ﴿جاء موسى لميقاتنا﴾؟","answer":"يذكر المصدر أن اللام للاختصاص، أي جاء في الميقات المعين له دون تأخر، ويجوز أن تكون للأجل، أي جاء لأجل الموعد وما تضمنه من المناجاة. فليس لازمًا أن يفسر التركيب بمجيء إلى الزمن نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص477، تحت «نكتة توجيه معنى اللام، في قوله: ﴿لميقاتنا﴾»","url":""}]},{"id":"s7-915","number":915,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا أضاف الميقات إلى الله: ﴿لميقاتنا﴾ بعد قوله ﴿ميقات ربه﴾؟","answer":"في ﴿ميقات ربه﴾ إبراز لعناية الرب بموسى، وفي ﴿لميقاتنا﴾ تشريف الموعد بإضافته إلى ضمير العظمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص464، تحت «نكتة العدول إلى التصريح بلفظ ﴿ربه﴾، وإضافة موسى إليه»","url":""}]},{"id":"s7-916","number":916,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما أثر اقتران التكليم بمجيء موسى في ﴿ولما جاء موسى لميقاتنا وكلمه ربه﴾؟","answer":"اجتمع المجيء والتكليم في تمهيد طلب موسى الرؤية؛ فلما أكرمه الله بالكلام ازداد شوقه إلى المعرفة والقرب فسأل أن يراه. فارتبط الطلب بما ناله في ذلك المقام من تشريف التكليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص478–479، تحت «سر جعل ﴿وكلمه ربه﴾ شرطًا للأداة ﴿ولما﴾»","url":""}]},{"id":"s7-917","number":917,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا أظهر ﴿ربه﴾ بدل الضمير: «وكلمناه»؟","answer":"إظهار ﴿ربه﴾ بدل «كلمناه» يستحضر وصف الربوبية والعناية في أشرف مقام، ويجعل المتكلم معلومًا على وجه التعظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص479، تحت «نكتة العدول عن الإضمار إلى الإظهار»","url":""}]},{"id":"s7-918","number":918,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما دلالة طلب موسى: ﴿رب أرني أنظر إليك﴾، فجمع بين الإراءة والنظر؟","answer":"طلب بقوله ﴿أرني﴾ أن يمكنه الله من رؤيته، وحذف المفعول الثاني لدلالة ﴿إليك﴾ عليه.؛ ثم بين ﴿أنظر إليك﴾ ما يرجوه من تلك الإراءة، فيكشف الجمع بينهما شدة شوقه إلى الرؤية بعد نعمة التكليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص479–480، تحت «دلالة جملة ﴿رب أرني أنظر إليك﴾»","url":""}]},{"id":"s7-919","number":919,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لم حذف حرف النداء «يا» فقال موسى: ﴿رب أرني﴾؟","answer":"يدل حذف حرف النداء على القرب في المناجاة، ويجمع لفظ ﴿رب﴾ معاني الإحسان والتربية والرعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص479–480، تحت «بلاغة الحذف في ﴿رب أرني أنظر﴾»","url":""}]},{"id":"s7-920","number":920,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا أجابه الله بـ﴿لن تراني﴾ لا «لا تراني»؟","answer":"﴿لن﴾ تنفي حصول الرؤية في الحال الدنيوية التي عليها موسى نفيًا مؤكدًا، ولا تدل بذاتها على امتناع الرؤية أبدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص481–482، تحت «دلالة أداة النصب ﴿لن﴾»","url":""}]},{"id":"s7-921","number":921,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا علق الرؤية على استقرار الجبل: ﴿فإن استقر مكانه فسوف تراني﴾؟","answer":"فلما عجز الجبل عن الثبات ظهر بطريق المشاهدة أن بنية موسى البشرية لا تحتملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص483–484، تحت «وجه تعليق الشرط، بالحرف المشبه بالفعل إن»","url":""}]},{"id":"s7-922","number":922,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا اختير الجبل مقياسًا لاحتمال التجلي؟","answer":"اختير الجبل لرسوخه وصلابته وعظم جرمه؛ فإذا لم يثبت هو للتجلي فالإنسان أضعف عن احتماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص482–483، تحت «بلاغة الاستدراك بلفظ ﴿ولكن﴾»","url":""}]},{"id":"s7-923","number":923,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما دلالة ﴿فسوف تراني﴾ في سياق تعليق الرؤية باستقرار الجبل؟","answer":"تأتي في جواب الشرط، ويجعل المصدر التعبير بالمستقبل البعيد ملائمًا للاستبعاد في هذا المقام. فاختبار ثبات الجبل يكشف عجز القوة البشرية عن احتمال ذلك التجلي، ولا يفسر سوف هنا بمجرد إعطاء مهلة للنظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص483–484، تحت «نكتة التعبير بأسلوب التعريض»","url":""}]},{"id":"s7-924","number":924,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما تجلى ربه للجبل﴾، وعُدي التجلي باللام؟","answer":"التجلي الظهور والانكشاف، واللام في ﴿للجبل﴾ توجه التجلي إليه وتخصه به، فوقع أثره عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص484–485، تحت «سر التعبير بصيغة التجلي، دون غيره»","url":""}]},{"id":"s7-925","number":925,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿جعله دكًا﴾ لا «فدكّه»؟","answer":"﴿جعله دكًا﴾ يدل على تحويل الجبل كله إلى هيئة الدك والتسوية، لا مجرد وقوع فعل الدق عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص485، تحت «نكتة الإخبار عن الجبل بلفظ الدك»","url":""}]},{"id":"s7-926","number":926,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما أثر الإخبار عن الجبل بالمصدر في ﴿جعله دكًا﴾؟","answer":"أخبر عنه بالمصدر مبالغة في شدة ما أصابه من الهدم وتفرق الأجزاء؛ فالمعنى جعله مدكوكًا. وتقابل قوة الجبل وثباته مع هذا التحول يزيد المشهد تهويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص485، تحت «نكتة الإخبار عن الجبل بلفظ الدك»","url":""}]},{"id":"s7-927","number":927,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿وخر موسى صعقًا﴾ لا «سقط»؟","answer":"الخرور سقوط تقترن به جلبة؛ وأصل اللفظ متصل بصوت الخرير. فيصور سقوط موسى وصعقه في ذلك المشهد المهيب، ويزيد الإحساس بهول ما وقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص486، تحت «إيثار التعبير بالفعل: ﴿وخر﴾»","url":""}]},{"id":"s7-928","number":928,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما دلالة الصفة المشبهة ﴿صَعِقًا﴾ في ﴿وخر موسى صعقًا﴾؟","answer":"﴿صَعِقًا﴾ صفة مشبهة من الصعق، وليست مصدرًا هنا. تصور ما استولى عليه من الغشي وشدة التأثر بهول المشهد، وتؤكد تمكن تلك الحالة منه حين خر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص486، تحت «سر التعبير بالماضي المشدد، والصفة المشبهة»","url":""}]},{"id":"s7-929","number":929,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما أفاق﴾ لا «فلما استيقظ»؟","answer":"الإفاقة رجوع العقل والحس بعد غشي أو صعق، أما الاستيقاظ فرجوع من النوم؛ فالإفاقة هي المطابقة لما أصابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص486–487، تحت «دلالة إظهار الحرف، وحذفه في السياق»","url":""}]},{"id":"s7-930","number":930,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا بدأ موسى بعد الإفاقة بالتسبيح: ﴿سبحانك﴾؟","answer":"بدأ بالتسبيح تنزيهًا لله عن أن تحيط به الأبصار، واعترافًا بعظمته بعد أن شاهد أثر التجلي في الجبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص487–488، تحت «إنشاء الثناء على الله، والتنزيه عما لا يليق به، ديدن النبيئين»","url":""}]},{"id":"s7-931","number":931,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿تبت إليك﴾، وممَّ تاب موسى؟","answer":"تاب من الإقدام على سؤال الرؤية في الدنيا قبل الإذن، ورجع إلى الوقوف عند ما بينه الله له، لا من شك في ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص488، تحت «بلاغة التعبير عن التوبة بالفعل الماضي»","url":""}]},{"id":"s7-932","number":932,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"لماذا ختم بقوله: ﴿وأنا أول المؤمنين﴾؟","answer":"أطلق الأول على المبادر إلى الإيمان؛ فالأولية هنا كناية عن قوة إيمانه وشدة يقينه حتى كأنه سبق غيره إليه. وفي ختام الموقف بهذا الإقرار إعلان للتسليم والثبات على الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص488، تحت «دلالة التعبير عن أولية الإيمان على طريق المجاز كناية»","url":""}]},{"id":"s7-933","number":933,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لماذا خاطبه الله باسمه: ﴿يا موسى﴾ بعد الصعق والإفاقة؟","answer":"النداء باسمه تلطف وتشريف بعد الإفاقة، ورد له من هول الصعق إلى خطاب الاصطفاء والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص494، تحت «بلاغة المجاز المرسل في النداء»","url":""}]},{"id":"s7-934","number":934,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لماذا أكد الخبر بـ﴿إني اصطفيتك﴾؟","answer":"التوكيد هنا للاعتناء بشأن الخبر وإثارة اهتمام موسى بما اختصه الله به؛ إذ لا إنكار منه للاصطفاء. ويلائم هذا الاهتمام ما راعه في مشهد التجلي، فيتلقى خبر النعمة والتشريف مؤكدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص494–495، تحت «توجيه التوكيد بالحرف ﴿إن﴾»","url":""}]},{"id":"s7-935","number":935,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿اصطفيتك﴾ لا «اخترتك»؟","answer":"الاصطفاء اختيار مع تنقية وتفضيل، فهو أخص من مطلق الاختيار، ويلائم الرسالة والتكليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص491–492، تحت «شرح المفردات: ﴿اصطفيتك﴾»","url":""}]},{"id":"s7-936","number":936,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لماذا عُدّي الاصطفاء بـ﴿على الناس﴾؟","answer":"﴿على الناس﴾ تبين رفعة منزلته بينهم بما خص به، فالاصطفاء تفضيل لا مجرد اختيار لمهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص495–496، تحت «توجيه تعدية الاصطفاء بحرف الجر ﴿على﴾»","url":""}]},{"id":"s7-937","number":937,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"هل المراد بـ﴿على الناس﴾ جميع البشر أم أهل زمان موسى؟","answer":"يذكر المصدر أكثر من توجيه: أن المراد قومه الذين أرسل إليهم، أو أهل زمانه، ويجوز حمله على العموم بالنظر إلى اجتماع الرسالة والتكليم له. فلا يلزم من الاصطفاء بهذه الخصيصة تفضيله على كل نبي في كل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص496، تحت «دلالة العموم مع إرادة الخصوص، في لفظ ﴿الناس﴾»","url":""}]},{"id":"s7-938","number":938,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"ما وجه الجمع في ﴿برسالاتي﴾، ووجه قراءة الإفراد «برسالتي»؟","answer":"الجمع يلائم تعدد ما أرسل به من العقائد والأحكام والإرشادات، وتعدد الإبلاغ في أوقاته. والإفراد يجري على معنى المصدر أو يجعل الرسالة بمجموعها رسالة واحدة؛ فتلتقي القراءتان في أصل المعنى مع اختلاف الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص497–498، تحت «توجيه قراءتي الجمع والإفراد، للفظ ﴿برسالاتي﴾»","url":""}]},{"id":"s7-939","number":939,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لماذا قدّم ﴿برسالاتي﴾ على ﴿بكلامي﴾؟","answer":"يذكر المصدر أن الرسالة أسبق في الزمان، ويذكر وجهًا آخر هو الانتقال من شريف إلى أشرف، فيأتي التكليم زيادة في التشريف بعد الاصطفاء بالرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص497، تحت «نكتة تقديم الرسالات على الكلام»","url":""}]},{"id":"s7-940","number":940,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لم كررت الباء في ﴿برسالاتي وبكلامي﴾؟","answer":"إعادة الباء تنبه إلى أن الاصطفاء بالتكليم منقبة متميزة عن الاصطفاء بالرسالات، وتبرز خصوصية تكليم الله لموسى من غير واسطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص498، تحت «سر تكرار حرف الجر ﴿الباء﴾ في لفظ ﴿وبكلامي﴾»","url":""}]},{"id":"s7-941","number":941,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"لماذا فرّع على الاصطفاء قوله: ﴿فخذ ما آتيتك﴾؟","answer":"الفاء تجعل أخذ العطاء والشكر نتيجة عملية للاصطفاء؛ فمن اختير للرسالة لزمه قبولها والقيام بحقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص501، تحت «جمال الإجمال والتفريع في الآية»","url":""}]},{"id":"s7-942","number":942,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿ما آتيتك﴾ ولم يحدد المأخوذ؟","answer":"﴿ما آتيتك﴾ تعم ما وهبه الله من الرسالات والكلام والألواح وسائر النعم، فلم تقيده بشيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص499–500، تحت «بلاغة التعبير عن الإيتاء، بين المجاز والحقيقة»","url":""}]},{"id":"s7-943","number":943,"surah":7,"verses":[144],"references":[{"surah":7,"verses":[144]}],"verseLabel":"الأعراف: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿وكن من الشاكرين﴾ لا «واشكر»؟","answer":"﴿كن من الشاكرين﴾ تطلب ثباته في جماعة المتصفين بالشكر ودوام الصفة، لا فعل شكر عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص498–499، تحت «بلاغة التعبير بفعل الأمر ﴿وكن﴾»","url":""}]},{"id":"s7-944","number":944,"surah":7,"verses":[144,145],"references":[{"surah":7,"verses":[144,145]}],"verseLabel":"الأعراف: 144–145","question":"ما سرّ ذكر القوة في قوله تعالى: ﴿فخذها بقوة﴾، وعدم ذكرها قبلها في ﴿فخذ ما آتيتك﴾؟","answer":"الأولى إجمال في الأخذ وجاءت عقب الإفاقة من الصعق؛ والثانية في الألواح المفصلة وتبليغ القوم والعمل بها، وذلك يحتاج إلى قوة وعزيمة. فناسب الإجمالُ الإجمالَ والتفصيلُ التفصيلَ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص513، تحت «نكتة ذكر القوة مع الأخذ في هذه الآية»","url":""}]},{"id":"s7-945","number":945,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما أثر الانتقال من ﴿إني اصطفيتك﴾ إلى ضمير التعظيم في ﴿وكتبنا﴾؟","answer":"يلائم الإفراد في خطاب الاصطفاء مقام القرب والتأنيس، ثم يأتي ضمير التعظيم عند كتابة الألواح لما فيها من عظمة الشرائع والأحكام. فيناسب كل ضمير المقام الذي ورد فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص507، تحت «نكتة الالتفات إلى ضمير التعظيم، في ﴿وكتبنا﴾»","url":""}]},{"id":"s7-946","number":946,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما دلالة إسناد كتابة الألواح إلى الله في ﴿وكتبنا له﴾؟","answer":"تدل الإضافة على تشريف المكتوب وكونه بأمر الله وتقديره؛ فهو وحي محض لا صنع لفكر إنسان فيه ولا كسب لبشر من عند نفسه. ويقرر الماضي تحقق الكتابة ووقوع الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص506–507، تحت «التعبير بالماضي في ﴿وكتبنا﴾، وإضافته إلى نفسه»","url":""}]},{"id":"s7-947","number":947,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما وجه تعريف ﴿الألواح﴾ مع أنها لم تذكر قبل ذلك صراحة؟","answer":"يجوز أن يكون تعريف عهد لما يفهم من العطاء المذكور في ﴿ما آتيتك﴾، فيبين الكلام أن ذلك العطاء كان في ألواح. ويجوز تعريف الجنس؛ أي كتب له في ألواح من هذا الجنس، وقيل إن الألواح معروفة الصفة بينه وبين موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص507–508، تحت «نكتة تعريف ﴿الألواح﴾»","url":""}]},{"id":"s7-948","number":948,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿من كل شيء﴾ مع أن الألواح لم تشمل كل معلومات الوجود؟","answer":"﴿من كل شيء﴾ أي من كل ما يحتاج إليه بنو إسرائيل في دينهم وشريعتهم، لا كل معلومات الوجود؛ فالعموم مقيد بالمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص508، تحت «دلالة العموم في ﴿كل شيء﴾»","url":""}]},{"id":"s7-949","number":949,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"كيف يجمع المكتوب في الألواح بين ﴿موعظة﴾ و﴿تفصيلًا﴾؟","answer":"الموعظة تذكر بما يرغب في الطاعة وينفر من المعصية، والتفصيل يبين الأحكام والحلال والحرام. فجمع العطاء بين تربية النفس وبيان ما تعمل به، ولم يقتصر على جانب منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص508–509، تحت «سر الجمع بين الموعظة والتفصيل»","url":""}]},{"id":"s7-950","number":950,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما سرّ تقديم ﴿موعظة﴾ على ﴿تفصيلًا﴾؟","answer":"قُدمت الموعظة لأنها تصلح القلب وتحمله على القبول، ثم يأتي التفصيل الذي يبين الأحكام والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص509، تحت «فائدة تقديم الموعظة على التفصيل».","url":""}]},{"id":"s7-951","number":951,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"لماذا كرر ﴿كل شيء﴾ في الآية نفسها؟","answer":"الأولى تعم أنواع ما يحتاجون إليه من المكتوبات، والثانية تؤكد تفصيل كل أمر من تلك الأمور وبيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص508–509، تحت «دلالة العموم في ﴿كل شيء﴾»","url":""}]},{"id":"s7-952","number":952,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿فخذها بقوة﴾، وما القوة المطلوبة في أخذ الألواح؟","answer":"الأخذ بقوة هو الجد والعزم في الحفظ والفهم والعمل والتبليغ، لا مجرد حمل الألواح باليد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص510–511، تحت «سر التعبير بلفظ ﴿القوة﴾، دون غيره»","url":""}]}]);
